INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(109, 1, '2026-08-14 22:49:54', '2026-08-14 22:49:54', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- The hub supplies its own H1 inside the Rooted hero, so the page title is\n     not rendered here. Content comes from the Renton category, not this file. -->\n<!-- wp:group {\"tagName\":\"main\",\"className\":\"tb-renton-page\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group tb-renton-page\">\n	<!-- wp:html -->\n	<style>\n	.tb-renton-page{background:#fbf7ee;color:#243653}.tb-renton-hero{min-height:660px;display:flex;align-items:flex-end;background:linear-gradient(90deg,rgba(28,45,78,.94) 0%,rgba(28,45,78,.78) 52%,rgba(28,45,78,.22) 100%),url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\') center/cover no-repeat}.tb-renton-hero__inner{width:min(1180px,calc(100% - 48px));margin:auto;padding:72px 0}.tb-renton-stamp{width:132px;height:132px;margin-bottom:26px}.tb-renton-title{max-width:720px;margin:0 0 18px;color:#fff;font-size:clamp(3rem,7vw,5.5rem);line-height:.95}.tb-renton-dek{max-width:650px;color:#fff;font-size:clamp(1.1rem,2vw,1.35rem);line-height:1.65}.tb-renton-featured,.tb-renton-latest{padding:84px 24px}.tb-renton-featured .tb-page-shell,.tb-renton-latest .tb-page-shell,.tb-renton-editorial .tb-page-shell{max-width:1180px;margin:auto}.tb-renton-feature-card{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(280px,.7fr);gap:42px;align-items:center;background:#fff;padding:24px;border:1px solid #e4dccd}.tb-renton-feature-card .wp-block-post-featured-image{grid-row:1/6;margin:0}.tb-renton-feature-card:before{content:\"\";display:block;grid-column:1;grid-row:1/6;min-height:430px;background:url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\') center/cover no-repeat}.tb-renton-feature-card>p,.tb-renton-feature-card>h2,.tb-renton-feature-card>.wp-block-post-terms,.tb-renton-feature-card>.wp-block-post-date{grid-column:2}.tb-renton-feature-card h2{font-size:clamp(2rem,4vw,3.25rem);line-height:1.05}.tb-renton-topics{background:#d5a719;padding:26px 24px}.tb-renton-topics .tb-page-shell{display:flex;justify-content:center;gap:12px 32px;flex-wrap:wrap}.tb-renton-topics a{color:#1c2d4e;font-weight:700}.tb-renton-latest .wp-block-post-template{gap:28px}.tb-renton-card{background:#fff;overflow:hidden;border:1px solid #e4dccd;height:100%}.tb-renton-card__body{padding:22px}.tb-renton-card h3{font-size:1.75rem;line-height:1.15}.tb-renton-editorial{padding:80px 24px}.tb-renton-editorial--navy{background:#1c2d4e;color:#fff}.tb-renton-editorial--mustard{background:#d5a719}.tb-renton-editorial h2{margin:0 0 18px;font-size:clamp(2.25rem,5vw,4rem);line-height:1.05}.tb-renton-editorial__intro{max-width:720px;font-size:1.15rem;line-height:1.7}.tb-renton-favorites{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:36px}.tb-renton-favorite{background:#fff;color:#243653;padding:28px;border-top:6px solid #d5a719}.tb-renton-favorite strong{display:block;margin-bottom:8px;font-size:1.2rem}.tb-renton-actions{display:flex;gap:14px;flex-wrap:wrap;margin-top:28px}.tb-renton-action{display:inline-block;padding:14px 22px;background:#d5a719;color:#1c2d4e;font-weight:700;text-decoration:none}.tb-renton-action--navy{background:#1c2d4e;color:#fff}.tb-renton-cta{padding:72px 24px}.tb-renton-cta .tb-page-shell{max-width:900px;margin:auto}.tb-renton-cta h2{font-size:clamp(2.25rem,5vw,4rem)}@media(max-width:760px){.tb-renton-hero{min-height:560px;background-position:62% center}.tb-renton-hero__inner{padding:48px 0}.tb-renton-feature-card{grid-template-columns:1fr}.tb-renton-feature-card .wp-block-post-featured-image{grid-row:auto}.tb-renton-feature-card:before{grid-column:1;grid-row:auto;min-height:280px}.tb-renton-feature-card>p,.tb-renton-feature-card>h2,.tb-renton-feature-card>.wp-block-post-terms,.tb-renton-