:relative;padding:28px 0 0 28px}.tb-buy-hero-media:before{content:\"\";position:absolute;left:0;top:0;width:74%;height:72%;background:var(--sage)}.tb-buy-hero-media img{position:relative;width:100%;height:610px;object-fit:cover;display:block}.tb-buy-hero-note{position:absolute;right:-20px;bottom:45px;background:var(--white);padding:20px 24px;max-width:245px;box-shadow:0 14px 40px rgba(38,57,79,.14);font:20px/1.3 Georgia,serif;color:var(--navy);transform:rotate(2deg)}.tb-buy-clarity{padding:88px 0;background:#fff}.tb-buy-intro{display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:end;margin-bottom:48px}.tb-buy-intro h2,.tb-buy-search h2,.tb-buy-process h2,.tb-buy-homebot h2{font-size:clamp(40px,5vw,60px);color:var(--navy);margin-bottom:0}.tb-buy-intro p{font-size:17px;margin:0}.tb-buy-priorities{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.tb-buy-priority{background:var(--cream);padding:30px 26px;border-top:5px solid var(--blush)}.tb-buy-priority h3{font-size:26px;color:var(--navy);margin-bottom:12px}.tb-buy-local{background:var(--navy);color:#fff;padding:88px 0}.tb-buy-local .tb-buy-eyebrow{color:#f0cbd7}.tb-buy-local h2{font-size:clamp(42px,5vw,62px);color:#fff;max-width:720px;margin-bottom:38px}.tb-buy-city-grid{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid rgba(255,255,255,.3)}.tb-buy-city{padding:32px 35px 5px 0}.tb-buy-city+.tb-buy-city{border-left:1px solid rgba(255,255,255,.3);padding-left:35px}.tb-buy-city h3{font-size:31px;color:#fff;margin-bottom:12px}.tb-buy-story{padding:100px 0;background:var(--white)}.tb-buy-story-head{text-align:center;max-width:760px;margin:0 auto 48px}.tb-buy-story-head h2{font-size:clamp(40px,5vw,60px);color:var(--navy);margin-bottom:18px}.tb-buy-photo-grid{display:grid;grid-template-columns:.75fr 1.25fr;grid-template-rows:275px 275px;gap:22px}.tb-buy-photo{position:relative;overflow:hidden;background:linear-gradient(135deg,#e7d8cc,#f8f0e7);display:flex;align-items:flex-end;padding:30px}.tb-buy-photo:nth-child(2){grid-row:1/3;grid-column:2;background:linear-gradient(145deg,#c5d0d8,#f2e5db)}.tb-buy-photo:before{content:\"PHOTO TO COME\";position:absolute;top:28px;left:30px;font-size:11px;letter-spacing:.2em;font-weight:700;color:var(--navy)}.tb-buy-photo span{background:rgba(255,253,249,.92);padding:16px 18px;color:var(--navy);font:20px/1.3 Georgia,serif;max-width:350px}.tb-buy-process{padding:96px 0;background:var(--cream)}.tb-buy-process-head{max-width:780px;margin-bottom:50px}.tb-buy-process-head h2{margin-bottom:18px}.tb-buy-steps{display:grid;grid-template-columns:repeat(2,1fr);gap:0 60px;counter-reset:step}.tb-buy-step{counter-increment:step;display:grid;grid-template-columns:54px 1fr;gap:20px;border-top:1px solid #cfc5b8;padding:26px 0}.tb-buy-step:before{content:counter(step,decimal-leading-zero);font:32px Georgia,serif;color:var(--blush)}.tb-buy-step h3{font-size:27px;color:var(--navy);margin-bottom:8px}.tb-buy-step p{margin:0}.tb-buy-search{padding:100px 0;background:#fff}.tb-buy-search-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:70px;align-items:center}.tb-buy-search-panel{background:#f3e2e7;padding:45px}.tb-buy-search-panel blockquote{font-size:32px;color:var(--navy);margin:0 0 22px}.tb-buy-search-list{list-style:none;padding:0;margin:28px 0 0;display:grid;grid-template-columns:1fr 1fr;gap:0 25px}.tb-buy-search-list li{border-top:1px solid #d7d0c8;padding:15px 0}.tb-buy-search-list li:before{content:\"✓\";color:var(--blush);font-weight:bold;margin-right:10px}.tb-buy-homebot{padding:90px 0;background:var(--cream);text-align:center}.tb-buy-homebot p{max-width:700px;margin:0 auto 30px}.tb-buy-homebot-card{max-width:780px;margin:38px auto 0;padding:42px;background:#fff;border:1px solid rgba(52,76,106,.2)}.tb-buy-homebot-card strong{display:block;font:34px Georgia,serif;color:var(--navy);margin-bottom:12px}.tb-buy-final{padding:90px 0;background:var(--cream);color:var(--navy);text-align:center}.tb-buy-final h2{font-size:clamp(42px,5vw,65px);color:var(--navy);margin-bottom:20px}.tb-buy-final p{max-width:650px;margin:0 auto 30px;font-size:17px}\n@media(max-width:800px){.tb-buy-wrap{width:min(100% - 30px,1180px)}.tb-buy-hero{padding:45px 0}.tb-buy-hero-grid,.tb-buy-intro,.tb-buy-search-grid{grid-template-columns:1fr;gap:35px}.tb-buy-hero-media img{height:470px}.tb-buy-priorities,.tb-buy-city-grid,.tb-buy-steps{grid-template-columns:1fr}.tb-buy-city+.tb-buy-city{border-left:0;border-top:1px solid rgba(255,255,255,.3);padding-left:0}.tb-buy-photo-grid{grid-template-columns:1fr;grid-template-rows:250px 400px 250px}.tb-buy-photo:nth-child(2){grid-column:auto;grid-row:auto}.tb-buy-search-list{grid-template-columns:1fr}.tb-buy-hero-note{right:10px}}\n</style>\n\n<section class=\"tb-buy-hero\">\n <div class=\"tb-buy-wrap tb-buy-hero-grid\">\n  <div class=\"tb-buy-hero-copy\"><p class=\"tb-buy-eyebrow\">Buying in Renton, Kent &amp; Covington</p><h1>Buying a Home in Renton, Kent, or Covington</h1><p>Buying a home in Renton, Kent, or Covington starts with more than a listing search. Tanya helps you compare neighborhoods, set a comfortable budget, evaluate homes, and build an offer strategy around the way you want to live.</p><div class=\"tb-buy-actions\"><a class=\"tb-buy-button\" href=\"/contact/\">Plan Your Renton Home Search</a><a class=\"tb-buy-link\" href=\"#buying-power\">Explore my buying power →</a></div></div>\n  <div class=\"tb-buy-hero-media\"><img src=\"/wp-content/themes/tanya-barrans/assets/images/lwyl-living-room.jpg\" alt=\"A warm and inviting living room\"><div class=\"tb-buy-hero-note\">The right home should make everyday life feel more like yours.</div></div>\n </div>\n</section>\n\n<section class=\"tb-buy-clarity\">\n <div class=\"tb-buy-wrap\"><div class=\"tb-buy-intro\"><div><p class=\"tb-buy-eyebrow\">Before we open the apps</p><h2>A clear plan keeps the search from getting noisy.</h2></div><p>Instead of chasing every new listing, we define your priorities and build a search around the way you actually want to live. That gives us a better filter—and gives you more confidence when the right home appears.</p></div>\n <div class=\"tb-buy-priorities\"><article class=\"tb-buy-priority\"><h3>Your everyday</h3><p>Commute, routines, pets, hobbies, hosting, and the little things that make a place work.</p></article><article class=\"tb-buy-priority\"><h3>Your numbers</h3><p>A comfortable monthly range, cash-to-close expectations, and room for life after the purchase.</p></article><article class=\"tb-buy-priority\"><h3>Your non-negotiables</h3><p>The needs we protect, the preferences we rank, and the tradeoffs you are willing to make.</p></article><article class=\"tb-buy-priority\"><h3>Your timing</h3><p>A search pace and offer strategy that reflect your real-world plans—not artificial urgency.</p></article></div></div>\n</section>\n\n<section class=\"tb-buy-local\">\n <div class=\"tb-buy-wrap\"><p class=\"tb-buy-eyebrow\">Neighborhoods are part of the home</p><h2>Three communities. Many different ways to feel at home.</h2>\n <div class=\"tb-buy-city-grid\"><article class=\"tb-buy-city\"><h3>Renton</h3><p>Waterfront energy, established neighborhoods, convenient connections, and plenty of local personality. We will narrow the search to the Renton lifestyle that fits you.</p></article><article class=\"tb-buy-city\"><h3>Kent</h3><p>A broad mix of neighborhoods, housing styles, and everyday conveniences. We will compare the pockets that align with your needs and budget.</p></article><article class=\"tb-buy-city\"><h3>Covington</h3><p>For buyers drawn to community, space, and easy access to outdoor life. We will look beyond the listing photos to how each location lives.</p></article></div></div>\n</section>\n\n<section class=\"tb-buy-story\">\n <div class=\"tb-buy-wrap\"><div class=\"tb-buy-story-head\"><p class=\"tb-buy-eyebrow\">Picture yourself here</p><h2>A home search is really a life search.</h2><p>These placeholders are ready for personal lifestyle photography that makes the page feel even more like you and your work.</p></div>\n <div class=\"tb-buy-photo-grid\"><div class=\"tb-buy-photo\"><span>Tanya touring a home with buyers or opening the front door.</span></div><div class=\"tb-buy-photo\"><span>A neighborhood walk, coffee stop, park, or favorite local corner.</span></div><div class=\"tb-buy-photo\"><span>Keys in hand, a moving-day detail, or a joyful closing moment.</span></div></div></div>\n</section>\n\n<section class=\"tb-buy-process\">\n <div class=\"tb-buy-wrap\"><div class=\"tb-buy-process-head\"><p class=\"tb-buy-eyebrow\">The path from curious to keys</p><h2>Guidance at every decision point.</h2><p>You will know what comes next, what deserves a closer look, and when it is worth moving quickly.</p></div>\n <div class=\"tb-buy-steps\"><article class=\"tb-buy-step\"><div><h3>Strategy conversation</h3><p>We define your goals, priorities, timing, and ideal next chapter.</p></div></article><article class=\"tb-buy-step\"><div><h3>Financing preparation</h3><p>We connect the purchase price to a monthly reality that feels sustainable.</p></div></article><article class=\"tb-buy-step\"><div><h3>Focused home search</h3><p>We watch the right homes and neighborhoods without flooding your inbox.</p></div></article><article class=\"tb-buy-step\"><div><h3>Thoughtful touring</h3><p>We evaluate condition, layout, location, resale considerations, and hidden tradeoffs.</p></div></article><article class=\"tb-buy-step\"><div><h3>Offer strategy</h3><p>We build terms around the property, the competition, and your comfort level.</p></div></article><article class=\"tb-buy-step\"><div><h3>Due diligence</h3><p>I help you navigate inspection findings, documents, timelines, and questions.</p></div></article><article class=\"tb-buy-step\"><div><h3>Closing and keys</h3><p>We stay ahead of the final details so the transition feels organized and exciting.</p></div></article><article class=\"tb-buy-step\"><div><h3>Beyond closing</h3><p>You still have a local resource for vendors, home questions, and the community.</p></div></article></div></div>\n</section>\n\n<section class=\"tb-buy-search\">\n <div class=\"tb-buy-wrap tb-buy-search-grid\"><div><p class=\"tb-buy-eyebrow\">Your advocate in the room</p><h2>Fall in love—but keep your eyes open.</h2><p>I will celebrate the beautiful kitchen with you and help you notice the things that could affect value, comfort, or your future plans. The goal is not simply to win a house. It is to feel good about the home after the excitement settles.</p><ul class=\"tb-buy-search-list\"><li>Local market context</li><li>Property condition questions</li><li>Offer-term guidance</li><li>Comparable-sale review</li><li>Inspection support</li><li>Clear communication</li></ul></div>\n <div class=\"tb-buy-search-panel\"><blockquote>“You deserve enough information to make a confident decision—and enough breathing room to know it is truly yours.”</blockquote><a class=\"tb-buy-button tb-buy-button--outline\" href=\"/contact/\">Ask Tanya a question</a></div></div>\n</section>\n\n<section id=\"buying-power\" class=\"tb-buy-homebot\">\n <div class=\"tb-buy-wrap\"><p class=\"tb-buy-eyebrow\">A useful place to begin</p><h2>Explore your buying power.</h2><p>Get an early look at the numbers, then let’s put them into context—monthly comfort, cash needs, market conditions, and the homes that may fit.</p><div class=\"tb-buy-homebot-card\"><strong>Ready for a clearer starting point?</strong><p>Use the buyer planning tool, then bring me every question it creates.</p><div id=\"homebot_homeowner\"></div><script>(function (h,b) { var w = window, d = document, s = \'script\', x, y; w[\'__hb_namespace\'] = h; w[h] = w[h] || function () { (w[h].q=w[h].q||[]).push(arguments) }; y = d.createElement(s); x = d.getElementsByTagName(s)[0]; y.async = 1; y.src = b; x.parentNode.insertBefore(y,x) })(\'Homebot\',\'https://embed.homebotapp.com/lgw/v1/widget.js\'); Homebot(\'#homebot_homeowner\', \'e8ad63175f4b48e9242c83995e101fe1ae82895cbb6c069e\',{\'mode\':\'buyers-mode\'})</script></div></div>\n</section>\n\n<section class=\"tb-buy-final\"><div class=\"tb-buy-wrap\"><p class=\"tb-buy-eyebrow\">Let’s find your version of home</p><h2>Your search can start with a conversation.</h2><p>You do not need to have everything figured out. Tell me what you are considering, and we will turn it into a practical next step.</p><a class=\"tb-buy-button\" href=\"/contact/\">Talk with Tanya</a></div></section>\n<!-- /wp:html -->\n</main>\n<!-- /wp:group -->\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"tanya-barrans\",\"tagName\":\"footer\"} /-->', 'page-buy', '', 'inherit', 'closed', 'closed', '', '112-revision-v1', '', '', '2026-08-20 02:43:38', '2026-08-20 02:43:38', '', 112, 'https://violet-wren-104886.hostingersite.com/?p=90200', 0, 'revision', '', 0),
(90201, 2, '2026-08-20 02:52:27', '2026-08-20 02:52:27', '<!-- wp:navigation-link {\"label\":\"Home\",\"url\":\"/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n<!-- wp:navigation-link {\"label\":\"Buy\",\"url\":\"/buy/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n<!-- wp:navigation-link {\"label\":\"Sell\",\"url\":\"/sell/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n<!-- wp:navigation-link {\"label\":\"Listings\",\"url\":\"/listings/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n<!-- wp:navigation-submenu {\"label\":\"Neighborhoods\",\"url\":\"/neighborhoods/\",\"kind\":\"custom\",\"isTopLevelItem\":true} -->\n<!-- wp:navigation-link {\"label\":\"All neighborhoods\",\"url\":\"/neighborhoods/\",\"kind\":\"custom\"} /-->\n<!-- wp:navigation-link {\"label\":\"Renton\",\"url\":\"/renton/\",\"kind\":\"custom\"} /-->\n<!-- /wp:navigation-submenu -->\n<!-- wp:navigation-link {\"label\":\"The Journal\",\"url\":\"/blog/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n<!-- wp:navigation-link {\"label\":\"About Tanya\",\"url\":\"/about/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n<!-- wp:navigation-link {\"label\":\"Contact\",\"url\":\"/contact/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->', 'Navigation', '', 'inherit', 'closed', 'closed', '', '4-revision-v1', '', '', '2026-08-20 02:52:27', '2026-08-20 02:52:27', '', 4, 'https://violet-wren-104886.hostingersite.com/?p=90201', 0, 'revision', '', 0),
(90202, 2, '2026-08-20 03:02:18', '2026-08-20 03:02:18', '<!-- wp:group {\"align\":\"full\",\"className\":\"tb-topo-bg\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"800px\"}} -->\n<div class=\"wp-block-group alignfull tb-topo-bg\" style=\"padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--40)\">\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-eyebrow\"} -->\n<p class=\"has-text-align-center tb-eyebrow\">Puget Sound Real Estate</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"xx-large\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-xx-large-font-size\">Homes worth a closer look.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"graphite\"} -->\n<p class=\"has-text-align-center has-graphite-color has-text-color\">From homes just hitting the market to a track record of successful sales across Renton, Kent, and Covington, this is where you can see Tanya\'s work in action.</p>\n<!-- /wp:paragraph -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"tb-editorial-feature tb-editorial-feature\\u002d\\u002dphoto-left tb-current-listings\",\"backgroundColor\":\"sand\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull tb-editorial-feature tb-editorial-feature--photo-left tb-current-listings has-sand-background-color has-background\">\n\n<!-- wp:group {\"className\":\"tb-editorial-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group tb-editorial-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-living-room.jpg);background-position:center\"></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"tb-editorial-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group tb-editorial-feature__content tb-reveal\">\n\n<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n<p class=\"tb-eyebrow\">Current Listings</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"fontSize\":\"xx-large\"} -->\n<h2 class=\"wp-block-heading has-xx-large-font-size\">New listings, added as they go live.</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n<p class=\"has-graphite-color has-text-color\">Tanya updates this page the moment a new property is ready to share. Want first access before it is posted here? Reach out directly and she will send you the newest opportunities in Renton, Kent, and Covington.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"className\":\"tb-real-estate-links\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-group tb-real-estate-links\">\n<!-- wp:paragraph -->\n<p><a href=\"/contact/\">Get in touch <span aria-hidden=\"true\">→</span></a></p>\n<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"tb-topo-bg\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n<div class=\"wp-block-group alignfull tb-topo-bg has-alabaster-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--40)\">\n\n	<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-eyebrow\"} -->\n	<p cl