(90216, 2, '2026-08-20 06:20:06', '2026-08-20 06:20:06', '<!-- wp:html --><style>body .wp-block-post-title{display:none!important}.tb-property-template{width:100vw;max-width:none!important;margin-left:calc(50% - 50vw);margin-top:-96px;overflow:hidden;color:#344c6a;background:#fbf8f4}.tb-property-template *{box-sizing:border-box}.tbp-hero{min-height:680px;position:relative;background:linear-gradient(90deg,rgba(30,48,70,.18),rgba(30,48,70,.02)),url(\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/renton-pending.jpg\") center/cover no-repeat}.tbp-hero-card{position:absolute;left:max(4vw,24px);bottom:-65px;width:min(720px,calc(100% - 48px));padding:clamp(34px,5vw,66px);background:#fbf8f4;box-shadow:0 24px 70px rgba(52,76,106,.2)}.tbp-kicker{font-size:.7rem;letter-spacing:.18em;text-transform:uppercase;font-weight:700;color:#6f8a74}.tbp-hero h1{font-family:Georgia,serif;font-size:clamp(2.8rem,5.5vw,5.6rem);line-height:.95;margin:.6rem 0 1rem;color:#344c6a}.tbp-status{display:inline-block;padding:8px 12px;background:#d6a3b5;color:#344c6a;font-size:.68rem;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.tbp-price{font-family:Georgia,serif;font-size:1.7rem;margin:.6rem 0}.tbp-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:22px}.tbp-btn{display:inline-block;padding:14px 22px;background:#344c6a;color:#fff!important;text-decoration:none!important;text-transform:uppercase;letter-spacing:.1em;font-size:.7rem;font-weight:700;border:1px solid #344c6a}.tbp-btn.alt{background:transparent;color:#344c6a!important}.tbp-btn:hover{background:#6f8a74;border-color:#6f8a74;color:#fff!important}.tbp-facts{padding:110px 28px 42px;background:#dbc8b3;display:grid;grid-template-columns:repeat(5,1fr);gap:1px}.tbp-fact{text-align:center;padding:16px;border-right:1px solid rgba(52,76,106,.25)}.tbp-fact:last-child{border:0}.tbp-fact strong{display:block;font-family:Georgia,serif;font-size:1.55rem}.tbp-fact span{font-size:.65rem;text-transform:uppercase;letter-spacing:.12em}.tbp-story{max-width:900px;margin:auto;padding:clamp(70px,9vw,125px) 28px;text-align:center}.tbp-story h2,.tbp-section h2,.tbp-neighborhood h2,.tbp-contact h2{font-family:Georgia,serif;font-size:clamp(2.5rem,4.8vw,4.8rem);line-height:1.03;margin:.5rem 0 1.4rem}.tbp-story p,.tbp-copy p,.tbp-neighborhood p{font-size:1.06rem;line-height:1.8;color:#3f4650}.tbp-gallery{max-width:1280px;margin:auto;padding:0 28px 100px;display:grid;grid-template-columns:2fr 1fr 1fr;grid-template-rows:310px 310px;gap:16px}.tbp-gallery img{width:100%;height:100%;object-fit:cover}.tbp-gallery img:first-child{grid-row:1/3}.tbp-gallery img:nth-child(4){grid-column:2/4}.tbp-section{display:grid;grid-template-columns:1fr 1fr;min-height:620px}.tbp-section.reverse .tbp-image{order:2}.tbp-image{min-height:520px;background-size:cover;background-position:center}.tbp-copy{display:flex;flex-direction:column;justify-content:center;padding:clamp(45px,7vw,100px);background:#fff}.tbp-copy .tbp-kicker{color:#b46f88}.tbp-feature-list{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:20px 0 0;padding:0;list-style:none}.tbp-feature-list li{padding:12px 0;border-bottom:1px solid #dbc8b3;font-size:.87rem}.tbp-highlights{background:#344c6a;color:#fff;padding:clamp(70px,8vw,110px) 28px}.tbp-highlights-inner{max-width:1200px;margin:auto}.tbp-highlights h2{font-family:Georgia,serif;font-size:clamp(2.5rem,4.7vw,4.6rem);text-align:center;margin:.5rem 0 3rem}.tbp-highlight-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.tbp-highlight{border:1px solid rgba(255,255,255,.3);padding:28px}.tbp-highlight h3{font-family:Georgia,serif;font-size:1.45rem;color:#fff;margin:0 0 8px}.tbp-highlight p{line-height:1.65;margin:0;color:rgba(255,255,255,.82)}.tbp-video{max-width:1100px;margin:auto;padding:100px 28px;text-align:center}.tbp-video-box{aspect-ratio:16/9;background:#6f8a74;display:flex;align-items:center;justify-content:center;color:#fff}.tbp-video-box span{border:1px solid rgba(