(90246, 2, '2026-08-20 22:18:38', '2026-08-20 22:18:38', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"className\":\"tb-rooted-page\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group tb-rooted-page\">\n\n<!-- wp:html -->\n<style>\n.tb-rooted-page{--navy:#26364a;--blue:#344c6a;--green:#718c78;--rose:#c77798;--cream:#fbf7f0;--white:#fffefa;--ink:#26364a;background:var(--cream);color:var(--ink)}\n.tb-rooted-page *{box-sizing:border-box}\n.tb-shell{width:min(1180px,calc(100% - 48px));margin:auto}\n.tb-eyebrow{margin:0 0 18px;color:var(--rose);font-size:.78rem;font-weight:800;letter-spacing:.18em;text-transform:uppercase}\n.tb-rooted-hero{position:relative;min-height:660px;display:flex;align-items:flex-end;overflow:hidden;background:linear-gradient(90deg,rgba(25,39,57,.96) 0%,rgba(38,54,74,.83) 48%,rgba(38,54,74,.34) 100%),url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\') center/cover no-repeat}\n.tb-rooted-hero:after{content:\"\";position:absolute;right:-80px;bottom:-130px;width:360px;height:360px;border:1px solid rgba(255,255,255,.24);border-radius:50%}\n.tb-rooted-hero__inner{position:relative;z-index:1;padding:108px 0 88px}\n.tb-rooted-hero .tb-eyebrow{color:#f0b7ce}\n.tb-rooted-hero h1{max-width:830px;margin:0 0 24px;color:#fff!important;font-family:Georgia,\"Times New Roman\",serif;font-size:clamp(3.5rem,8vw,6.8rem);font-weight:400;line-height:.93;letter-spacing:-.035em}\n.tb-rooted-hero__lead{max-width:700px;margin:0;color:#f7f2ea;font-size:clamp(1.08rem,1.8vw,1.28rem);line-height:1.7}\n.tb-rooted-hero__lead strong{color:#fff}\n.tb-story{padding:108px 0 92px;background:var(--white)}\n.tb-story__grid{display:grid;grid-template-columns:.82fr 1.18fr;gap:9vw;align-items:start}\n.tb-story h2,.tb-places h2,.tb-cities h2{margin:0;font-family:Georgia,\"Times New Roman\",serif;font-size:clamp(2.6rem,5vw,4.6rem);font-weight:400;line-height:1.02;letter-spacing:-.025em}\n.tb-story__copy{font-size:1.08rem;line-height:1.85;color:#4a5868}\n.tb-story__copy p{margin:0 0 20px}\n.tb-story__signature{display:block;margin-top:30px;padding-left:22px;border-left:3px solid var(--rose);color:var(--navy);font-family:Georgia,\"Times New Roman\",serif;font-size:1.45rem;line-height:1.5}\n.tb-places{padding:96px 0;background:var(--cream)}\n.tb-places__head{display:grid;grid-template-columns:1fr 1fr;gap:7vw;align-items:end;margin-bottom:52px}\n.tb-places__intro{margin:0;color:#596574;font-size:1.03rem;line-height:1.75}\n.tb-timeline{display:flex;gap:0;overflow-x:auto;padding:18px 0 26px;scroll-snap-type:x mandatory}\n.tb-stop{position:relative;min-width:245px;padding:38px 30px 12px 0;border-top:1px solid #b8c0b8;scroll-snap-align:start}\n.tb-stop:before{content:\"\";position:absolute;top:-7px;left:0;width:13px;height:13px;border-radius:50%;background:var(--rose);box-shadow:0 0 0 6px var(--cream)}\n.tb-stop__city{display:block;margin-bottom:10px;color:var(--green);font-size:.72rem;font-weight:800;letter-spacing:.15em;text-transform:uppercase}\n.tb-stop strong{display:block;margin-bottom:9px;font-family:Georgia,\"Times New Roman\",serif;font-size:1.45rem;font-weight:400;color:var(--navy)}\n.tb-stop p{margin:0;color:#66717e;font-size:.92rem;line-height:1.55}\n.tb-cities{padding:110px 0;background:var(--white)}\n.tb-cities__head{max-width:780px;margin-bottom:52px}\n.tb-cities__head p:last-child{max-width:610px;margin:20px 0 0;color:#5b6775;font-size:1.04rem;line-height:1.7}\n.tb-city-grid{display:grid;grid-template-columns:repeat(12,1fr);gap:24px;list-style:none;margin:0;padding:0}\n.tb-city-card{grid-column:span 4;min-height:390px;border-radius:22px;overflow:hidden;box-shadow:0 18px 45px rgba(38,54,74,.14);transition:transform .22s ease,box-shadow .22s ease}\n.tb-city-card:nth-child(1),.tb-city-card:nth-child(4){grid-column:span 8}\n.tb-city-card a,.tb-city-card__static{position:relative;display:flex;flex-direction:column;justify-content:flex-end;height:100%;min-height:390px;padding:30px;color:#fff;text-decoration:none;background-position:center;background-size:cover}\n.tb-city-card a:before,.tb-city-card__static:before{content:\"\";position:absolute;inset:0;background:linear-gradient(180deg,rgba(38,54,74,.05),rgba(27,39,55,.94))}\n.tb-city-card a>*,.tb-city-card__static>*{position:relative;z-index:1}\n.tb-city-card:hover{transform:translateY(-5px);box-shadow:0 26px 54px rgba(38,54,74,.2)}\n.tb-city-card--renton a{background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\')}\n.tb-city-card--kent a{background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/kent-green-river-scaled.jpg\')}\n.tb-city-card--covington a{background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/covington-rainier-scaled.jpg\')}\n.tb-city-card--maple a{background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/maple-valley-lake-wilderness-scaled.jpg\')}\n.tb-city-card--newcastle a{background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/newcastle-lake-boren.jpg\')}\n.tb-city-card--ravensdale a{background-image:url(\'https://digitalcollections.lib.washington.edu/digital/api/singleitem/image/wastate/1047/default.jpg\')}\n.tb-city-card__label{align-self:flex-start;margin-bottom:15px;padding:7px 13px;border-radius:999px;background:var(--rose);font-size:.7rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase}\n.tb-city-card__name{margin-bottom:10px;font-family:Georgia,\"Times New Roman\",serif;font-size:2.45rem;line-height:1}\n.tb-city-card__hook{max-width:520px;margin-bottom:18px;color:#f7f2ea;font-size:.98rem;line-height:1.55}\n.tb-city-card__go{width:max-content;padding-bottom:4px;border-bottom:2px solid var(--rose);font-weight:750;font-size:.88rem}\n.tb-city-card:nth-child(1) .tb-city-card__name,.tb-city-card:nth-child(4) .tb-city-card__name{font-size:3rem}\n.tb-city-card--issaquah .tb-city-card__static{display:flex;flex-direction:column;justify-content:flex-end;height:100%;min-height:390px;padding:30px;color:#fff;background-image:linear-gradient(135deg,#718c78 0%,#344c6a 100%)} .tb-city-card--issaquah .tb-city-card__static:before{background:linear-gradient(180deg,rgba(38,54,74,.05),rgba(27,39,55,.72))} .tb-rooted-note{margin-top:52px;padding:30px 0 0;border-top:1px solid #d9d8d1;color:#596574;line-height:1.7}\n.tb-rooted-note a{color:var(--navy);font-weight:800}\n.tb-rooted-hero{min-height:640px;align-items:stretch;background:url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\') 72% center/cover no-repeat} .tb-rooted-hero:before{content:\"\";position:absolute;inset:0 50% 0 0;width:auto;height:auto;border:0;border-radius:0;background:var(--navy);box-shadow:18px 0 38px rgba(18,31,47,.2)} .tb-rooted-hero:after{display:none}.tb-rooted-hero__inner{display:flex;flex-direction:column;justify-content:center;margin:auto;padding:86px 0}.tb-rooted-hero h1{max-width:530px;font-size:clamp(3.5rem,6vw,5.5rem)}.tb-rooted-hero__lead{max-width:520px;padding-right:44px}\n@media(max-width:900px){\n .tb-story__grid,.tb-places__head{grid-template-columns:1fr;gap:34px}\n .tb-city-card,.tb-city-card:nth-child(1),.tb-city-card:nth-child(4){grid-column:span 6}\n}\n@media(max-width:720px){.tb-rooted-hero{min-height:720px;align-items:flex-end;background-position:center top;background-size:auto 310px;background-color:var(--navy)}.tb-rooted-hero:before{inset:290px 0 0;box-shadow:0 -16px 35px rgba(18,31,47,.18)}.tb-rooted-hero__inner{justify-content:flex-end;padding:340px 0 58px}.tb-rooted-hero__lead{padding-right:0}.tb-rooted-hero h1{font-size:clamp(3.1rem,15vw,4.8rem)}}\n@media(max-width:620px){\n .tb-shell{width:min(100% - 36px,1180px)}\n .tb-rooted-hero{min-height:600px}\n .tb-rooted-hero__inner{padding:86px 0 64px}\n .tb-story,.tb-cities{padding:76px 0}.tb-places{padding:72px 0}\n .tb-city-card,.tb-city-card:nth-child(1),.tb-city-card:nth-child(4){grid-column:1/-1;min-height:340px}\n .tb-city-card a{min-height:340px;padding:25px}\n .tb-city-card:nth-child(1) .tb-city-card__name,.tb-city-card:nth-child(4) .tb-city-card__name{font-size:2.45rem}\n}\n</style>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<section class=\"tb-rooted-hero\">\n <div class=\"tb-shell tb-rooted-hero__inner\">\n  <p class=\"tb-eyebrow\">Rooted In</p>\n  <h1>These Places Raised Me.</h1>\n  <p class=\"tb-rooted-hero__lead\">I was born in Renton, grew up in Issaquah, and over the years I’ve called Renton, Kent, Covington, Maple Valley, Newcastle and Ravensdale home. <strong>These aren’t simply markets I learned. They’re places filled with my own memories.</strong></p>\n </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<section class=\"tb-story\">\n <div class=\"tb-shell tb-story__grid\">\n  <div>\n   <p class=\"tb-eyebrow\">My corner of the PNW</p>\n   <h2>This corner of Washington is personal.</h2>\n  </div>\n  <div class=\"tb-story__copy\">\n   <p>I went to school here. Worked my first jobs here. Bought my first home here. Found favorite restaurants here. Made lifelong friends here. Raised my family here.</p>\n   <p>And after 45 years, I still love discovering the stories behind the communities that make this corner of Washington home.</p>\n   <span class=\"tb-story__signature\">These aren’t just places I sell homes. They’re the places that made me.</span>\n  </div>\n </div>\n</section>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<section class=\"tb-places\">\n <div class=\"tb-shell\">\n  <div class=\"tb-places__head\">\n   <div>\n    <p class=\"tb-eyebrow\">The places along the way</p>\n    <h2>A Lifetime Lived Here</h2>\n   </div>\n   <p class=\"tb-places__intro\">From childhood and first jobs to first homes and fresh chapters, these cities aren’t dots on a service-area map. They’re the places that shaped my life.</p>\n  </div>\n  <div class=\"tb-timeline\" aria-label=\"Tanya\'s local timeline\">\n   <article class=\"tb-stop\"><span class=\"tb-stop__city\">Renton</span><strong>Where it started.</strong><p>Born in Renton, attended Renton Christian School, and even after moving away, kept coming back for church, youth group, friends and family. Renton has been a constant in my life from the very beginning.</p></article>\n   <article class=\"tb-stop\"><span class=\"tb-stop__city\">Issaquah</span><strong>Where I was raised.</strong><p>I grew up here and graduated from Liberty High School. The drive between Renton and Issaquah looked a whole lot different then — I remember fields where golf courses, neighborhoods and shopping centers eventually appeared. My first real job was just down the road at Coal Creek Chiropractic.</p></article>\n   <article class=\"tb-stop\"><span class=\"tb-stop__city\">Ravensdale</span><strong>A house with history.</strong><p>At 18, I got to call a restored turn-of-the-century family home in Ravensdale home for a year. It gave me a glimpse of this area\'s history long before I ever thought I\'d make a career out of homes.</p></article>\n   <article class=\"tb-stop\"><span class=\"tb-stop__city\">Maple Valley</span><strong>My first front door.</strong><p>This is where I bought my very first home and became a homeowner myself. I\'ve watched Maple Valley grow tremendously since then, but there are still pieces of the community I remember from those earlier days.</p></article>\n   <article class=\"tb-stop\"><span class=\"tb-stop__city\">Kent &amp; Covington</span><strong>My twenty-something years.</strong><p>These cities were home during my early adult years. I knew Kent when a night out looked a little different than it does today, and I lived in Covington before much of what we now think of as “Covington” had even arrived.</p></article>\n   <article class=\"tb-stop\"><span class=\"tb-stop__city\">Renton</span><strong>Coming home.</strong><p>Homeownership eventually brought me back to the city where my story started, this time purchasing my second home here. By then, I knew Renton through a completely different lens.</p></article>\n   <article class=\"tb-stop\"><span class=\"tb-stop__city\">Newcastle</span><strong>Another place to call home.</strong><p>Years after my first job in Coal Creek, life brought me back to Newcastle — this time as a resident. It\'s one of those funny full-circle places in my story: I knew this area before Newcastle looked much like the Newcastle we know today.</p></article>\n   <article class=\"tb-stop\"><span class=\"tb-stop__city\">Renton</span><strong>Rooted.</strong><p>And eventually, home brought me back to Renton once again. I bought a house here for my son and me, and more than five years later, we\'re still here — in the city where my story began.</p></article>\n  </div>\n </div>\n</section></section>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<section class=\"tb-cities\">\n <div class=\"tb-shell\">\n  <div class=\"tb-cities__head\">\n   <p class=\"tb-eyebrow\">Rooted In</p>\n   <h2>Pick a place. I’ll tell you its story.</h2>\n   <p>Start with the cities—their history, personality, everyday rhythm and the things I know from actually living here. We’ll dig into individual neighborhoods next.</p>\n  </div>\n  <ul class=\"tb-city-grid\">\n   <li class=\"tb-city-card tb-city-card--renton\"><a href=\"/renton/\"><span class=\"tb-city-card__label\">Rooted In</span><span class=\"tb-city-card__name\">Renton</span><span class=\"tb-city-card__hook\">My hometown—and still one of my favorite places to talk about.</span><span class=\"tb-city-card__go\">Explore Renton &rarr;</span></a></li>\n   <li class=\"tb-city-card tb-city-card--issaquah\"><div class=\"tb-city-card__static\"><span class=\"tb-city-card__label\">Rooted In</span><span class=\"tb-city-card__name\">Issaquah</span><span class=\"tb-city-card__hook\">The town I grew up in became a city right along with me.</span><span class=\"tb-city-card__go\">Guide coming soon</span></div></li>\n   <li class=\"tb-city-card tb-city-card--kent\"><a href=\"/kent/\"><span class=\"tb-city-card__label\">Rooted In</span><span class=\"tb-city-card__name\">Kent</span><span class=\"tb-city-card__hook\">One city with dramatically different personalities, depending on which hill you’re standing on.</span><span class=\"tb-city-card__go\">Explore Kent &rarr;</span></a></li>\n   <li class=\"tb-city-card tb-city-card--covington\"><a href=\"/covington/\"><span class=\"tb-city-card__label\">Rooted In</span><span class=\"tb-city-card__name\">Covington</span><span class=\"tb-city-card__hook\">I remember when there wasn’t much “Covington” in Covington.</span><span class=\"tb-city-card__go\">Explore Covington &rarr;</span></a></li>\n   <li class=\"tb-city-card tb-city-card--maple\"><a href=\"/maple-valley/\"><span class=\"tb-city-card__label\">Rooted In</span><span class=\"tb-city-card__name\">Maple Valley</span><span class=\"tb-city-card__hook\">Where I bought my first home and watched a small community explode with growth.</span><span class=\"tb-city-card__go\">Explore Maple Valley &rarr;</span></a></li>\n   <li class=\"tb-city-card tb-city-card--newcastle\"><a href=\"/rooted-in-newcastle/\"><span class=\"tb-city-card__label\">Rooted In</span><span class=\"tb-city-card__name\">Newcastle</span><span class=\"tb-city-card__hook\">From open fields and a first job at Coal Creek Chiropractic to one of the Eastside’s most distinctive little cities.</span><span class=\"tb-city-card__go\">Explore Newcastle &rarr;</span></a></li>\n   <li class=\"tb-city-card tb-city-card--ravensdale\"><a href=\"/rooted-in-ravensdale/\"><span class=\"tb-city-card__label\">Rooted In</span><span class=\"tb-city-card__name\">Ravensdale</span><span class=\"tb-city-card__hook\">A little piece of old King County that still feels like one.</span><span class=\"tb-city-card__go\">Explore Ravensdale &rarr;</span></a></li>\n  </ul>\n  <p class=\"tb-rooted-note\">Looking somewhere not listed here? <a href=\"/contact/\">Ask Tanya.</a> I cover the wider Puget Sound area—and I’ll tell you honestly what I know about a place and what I don’t.</p>\n </div>\n</section>\n<!-- /wp:html -->\n\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->', 'page-neighborhoods', '', 'publish', 'closed', 'closed', '', 'page-neighborhoods', '', '', '2026-08-26 17:29:41', '2026-08-26 17:29:41', '', 0, 'https://violet-wren-104886.hostingersite.com/page-neighborhoods/', 0, 'wp_template', '', 0),
(90247, 2, '2026-08-20 22:18:57', '2026-08-20 22:18:57', '<!-- wp:navigation-link {\"label\":\"Home\",\"url\":\"/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n<!-- wp:navigation-link {\"label\":\"Buy\",\"url\":\"/buy/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n<!-- wp:navigation-link {\"label\":\"Sell\",\"url\":\"/sell/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n<!-- wp:navigation-link {\"label\":\"Listings\",\"url\":\"/listings/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n<!-- wp:navigation-submenu {\"label\":\"Neighborhoods\",\"url\":\"/neighborhoods/\",\"kind\":\"custom\",\"isTopLevelItem\":true} -->\n<!-- wp:navigation-link {\"label\":\"All neighborhoods\",\"url\":\"/neighborhoods/\",\"kind\":\"custom\"} /-->\n<!-- wp:navigation-link {\"label\":\"Renton\",\"url\":\"/renton/\",\"kind\":\"custom\"} /-->\n<!-- wp:navigation-link {\"label\":\"Kent\",\"url\":\"/kent/\",\"kind\":\"custom\"} /-->\n<!-- wp:navigation-link {\"label\":\"Covington\",\"url\":\"/covington/\",\"kind\":\"custom\"} /-->\n<!-- wp:navigation-link {\"label\":\"Maple Valley\",\"url\":\"/maple-valley/\",\"kind\":\"custom\"} /-->\n<!-- wp:navigation-link {\"label\":\"Newcastle\",\"url\":\"/newcastle/\",\"kind\":\"custom\"} /-->\n<!-- /wp:navigation-submenu -->\n<!-- wp:navigation-link {\"label\":\"The Journal\",\"url\":\"/blog/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n<!-- wp:navigation-link {\"label\":\"About Tanya\",\"url\":\"/about/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n<!-- wp:navigation-link {\"label\":\"Contact\",\"url\":\"/contact/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->', 'Navigation', '', 'inherit', 'closed', 'closed', '', '4-revision-v1', '', '', '2026-08-20 22:18:57', '2026-08-20 22:18:57', '', 4, 'https://violet-wren-104886.hostingersite.com/?p=90247', 0, 'revision', '', 0),
(90263, 2, '2026-08-21 18:19:55', '2026-08-21 18:19:55', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:group {\"tagName\":\"main\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<main class=\"wp-block-group\">\n	<!-- Section order follows the Homepage Blueprint (updated 2026-08-19):\n	     Meet Tanya moved back to blueprint position seven, per Tanya\'s\n	     request to lead with the consumer-facing hero and value sections\n	     rather than the agent bio. -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-home-hero\",\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/hero\",\"name\":\"Homepage Hero\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-home-hero has-alabaster-background-color has-background\">\n\n	<!-- wp:html -->\n	<img\n		class=\"tb-home-hero__image\"\n		src=\"/wp-content/themes/tanya-barrans/assets/images/lwyl-hero.jpg\"\n		alt=\"\"\n		width=\"1720\"\n		height=\"914\"\n		fetchpriority=\"high\"\n		decoding=\"async\"\n	/>\n	<!-- /wp:html -->\n\n	<!-- wp:group {\"className\":\"tb-home-hero__inner\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-home-hero__inner\">\n\n		<!-- wp:group {\"className\":\"tb-home-hero__content tb-hero-arrive\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-home-hero__content tb-hero-arrive\">\n\n			<!-- The blueprint headline is a full sentence and the page may only\n			     carry one H1, so the script accent lives inside the heading\n			     rather than as a separate line above it. -->\n			<!-- wp:heading {\"level\":1,\"className\":\"tb-home-hero__title\"} -->\n			<h1 class=\"wp-block-heading tb-home-hero__title\"><span class=\"tb-script-accent\" style=\"text-transform:none\">Helping you</span> love your home<br>and where you live.</h1>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"tb-home-hero__dek\"} -->\n			<p class=\"tb-home-hero__dek\">Serving buyers and sellers in Renton and throughout the Puget Sound region.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:buttons {\"className\":\"tb-home-hero__buttons\",\"style\":{\"spacing\":{\"blockGap\":\"0.75rem\",\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n			<div class=\"wp-block-buttons tb-home-hero__buttons\" style=\"margin-top:var(--wp--preset--spacing--40)\">\n				<!-- wp:button {\"backgroundColor\":\"charcoal\"} -->\n				<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-charcoal-background-color has-background wp-element-button\" href=\"/contact/\">Let’s Talk About Your Next Move</a></div>\n				<!-- /wp:button -->\n\n								<!-- wp:button {\"className\":\"tb-button-outline\",\"textColor\":\"charcoal\"} -->\n				<div class=\"wp-block-button tb-button-outline\"><a class=\"wp-block-button__link has-charcoal-color has-text-color wp-element-button\" href=\"/renton/\">Explore Renton</a></div>\n				<!-- /wp:button -->\n			</div>\n			<!-- /wp:buttons -->\n\n		</div>\n		<!-- /wp:group -->\n\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n	\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-stats-band\",\"backgroundColor\":\"charcoal\",\"textColor\":\"base\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"},\"metadata\":{\"patternName\":\"tanya-barrans/stats\",\"name\":\"Track Record\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-stats-band has-base-color has-charcoal-background-color has-text-color has-background\">\n\n	<!-- wp:heading {\"level\":2,\"className\":\"tb-sr-only\"} -->\n	<h2 class=\"wp-block-heading tb-sr-only\">Tanya\'s track record</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:columns {\"align\":\"wide\",\"className\":\"tb-stats-band__grid\"} -->\n	<div class=\"wp-block-columns alignwide tb-stats-band__grid\">\n\n		<!-- wp:column {\"className\":\"tb-stat-item tb-reveal\"} -->\n		<div class=\"wp-block-column tb-stat-item tb-reveal\">\n			<!-- wp:html -->\n			<div class=\"tb-stat-item__icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"2\"></rect><path d=\"M3 10h18\"></path><path d=\"M8 3v4\"></path><path d=\"M16 3v4\"></path></svg></div>\n			<!-- /wp:html -->\n			<!-- wp:paragraph {\"className\":\"tb-stat\"} -->\n			<p class=\"tb-stat\">7+</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-stat-item__label\"} -->\n			<p class=\"tb-stat-item__label\">Years of Experience</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-stat-item tb-reveal\"} -->\n		<div class=\"wp-block-column tb-stat-item tb-reveal\">\n			<!-- wp:html -->\n			<div class=\"tb-stat-item__icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 11l9-8 9 8\"></path><path d=\"M5 10v10h14V10\"></path><path d=\"M9 20v-6h6v6\"></path></svg></div>\n			<!-- /wp:html -->\n			<!-- wp:paragraph {\"className\":\"tb-stat\"} -->\n			<p class=\"tb-stat\">70+</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-stat-item__label\"} -->\n			<p class=\"tb-stat-item__label\">Homes Sold</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-stat-item tb-reveal\"} -->\n		<div class=\"wp-block-column tb-stat-item tb-reveal\">\n			<!-- wp:html -->\n			<div class=\"tb-stat-item__icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 3l2.6 5.6 6.1.5-4.6 4 1.4 6-5.5-3.3L6.5 19l1.4-6-4.6-4 6.1-.5L12 3z\"></path></svg></div>\n			<!-- /wp:html -->\n			<!-- wp:paragraph {\"className\":\"tb-stat\"} -->\n			<p class=\"tb-stat\">39</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-stat-item__label\"} -->\n			<p class=\"tb-stat-item__label\">5-Star Google Reviews</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-stat-item tb-reveal\"} -->\n		<div class=\"wp-block-column tb-stat-item tb-reveal\">\n			<!-- wp:html -->\n			<div class=\"tb-stat-item__icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 17l6-6 4 4 8-8\"></path><path d=\"M15 7h6v6\"></path></svg></div>\n			<!-- /wp:html -->\n			<!-- wp:paragraph {\"className\":\"tb-stat\"} -->\n			<p class=\"tb-stat\">$65M</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-stat-item__label\"} -->\n			<p class=\"tb-stat-item__label\">In Sales Volume</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n	</div>\n	<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-ways\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1320px\"},\"metadata\":{\"patternName\":\"tanya-barrans/pathways\",\"name\":\"Three Ways Tanya Helps\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-ways has-base-background-color has-background\">\n\n	<!-- wp:heading {\"level\":2,\"textAlign\":\"center\",\"className\":\"tb-ways__title\"} -->\n	<h2 class=\"wp-block-heading has-text-align-center tb-ways__title\">Three ways Tanya helps</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:group {\"align\":\"wide\",\"className\":\"tb-ways__grid\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group alignwide tb-ways__grid\">\n\n		<!-- wp:group {\"className\":\"tb-way tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-way tb-reveal\">\n			<!-- wp:html -->\n			<img class=\"tb-way__photo\" src=\"/wp-content/themes/tanya-barrans/assets/images/lwyl-front-door.jpg\" alt=\"\" width=\"900\" height=\"1125\" loading=\"lazy\" decoding=\"async\" />\n			<!-- /wp:html -->\n			<!-- wp:heading {\"level\":3,\"className\":\"tb-way__title\"} -->\n			<h3 class=\"wp-block-heading tb-way__title\">Buy With Confidence</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"tb-way__copy\"} -->\n			<p class=\"tb-way__copy\">Find the right home, neighborhood, and long-term fit.</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-way__link\"} -->\n			<p class=\"tb-way__link\"><a href=\"/buy/\">Start Your Home Search <span aria-hidden=\"true\">&rarr;</span></a></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:group {\"className\":\"tb-way tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-way tb-reveal\">\n			<!-- wp:html -->\n			<img class=\"tb-way__photo\" src=\"/wp-content/themes/tanya-barrans/assets/images/lwyl-living-room.jpg\" alt=\"\" width=\"900\" height=\"1125\" loading=\"lazy\" decoding=\"async\" />\n			<!-- /wp:html -->\n			<!-- wp:heading {\"level\":3,\"className\":\"tb-way__title\"} -->\n			<h3 class=\"wp-block-heading tb-way__title\">Sell With Strategy</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"tb-way__copy\"} -->\n			<p class=\"tb-way__copy\">Clear pricing, thoughtful preparation, and marketing built to make your home stand out.</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-way__link\"} -->\n			<p class=\"tb-way__link\"><a href=\"/sell/\">Explore My Selling Plan <span aria-hidden=\"true\">&rarr;</span></a></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:group {\"className\":\"tb-way tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-way tb-reveal\">\n			<!-- wp:html -->\n			<img class=\"tb-way__photo\" src=\"/wp-content/themes/tanya-barrans/assets/images/lwyl-kitchen-garden.jpg\" alt=\"\" width=\"900\" height=\"1125\" loading=\"lazy\" decoding=\"async\" />\n			<!-- /wp:html -->\n			<!-- wp:heading {\"level\":3,\"className\":\"tb-way__title\"} -->\n			<h3 class=\"wp-block-heading tb-way__title\">Love Where You Live Now</h3>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"tb-way__copy\"} -->\n			<p class=\"tb-way__copy\">Home projects, garden ideas, local guides, and practical homeowner resources.</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"tb-way__link\"} -->\n			<p class=\"tb-way__link\"><a href=\"/blog/\">Browse the Journal <span aria-hidden=\"true\">&rarr;</span></a></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-editorial-feature tb-editorial-feature\\u002d\\u002dphoto-right tb-real-estate-feature\",\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/listings-placeholder\",\"name\":\"Real Estate Guidance\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-editorial-feature tb-editorial-feature--photo-right tb-real-estate-feature has-alabaster-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-editorial-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-editorial-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-front-door.jpg);background-position:center\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-editorial-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-editorial-feature__content tb-reveal\">\n\n		<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n		<p class=\"tb-eyebrow\">Real Estate</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"xx-large\"} -->\n		<h2 class=\"wp-block-heading has-xx-large-font-size\">Your next move should feel <em style=\"color:var(--wp--preset--color--sage)\">clear.</em></h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Whether you are buying your first home, selling a place filled with memories, or simply wondering whether now is the right time, you deserve a strategy built around your goals—not a one-size-fits-all plan.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:group {\"className\":\"tb-real-estate-links\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n		<div class=\"wp-block-group tb-real-estate-links\">\n			<!-- wp:paragraph -->\n			<p><a href=\"/buy/\">Buying a Home <span aria-hidden=\"true\">→</span></a></p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p><a href=\"/sell/\">Selling a Home <span aria-hidden=\"true\">→</span></a></p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p><a href=\"/listings/\">View Listings <span aria-hidden=\"true\">→</span></a></p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-brand-pillars\",\"backgroundColor\":\"charcoal\",\"textColor\":\"base\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"},\"metadata\":{\"patternName\":\"tanya-barrans/credibility\",\"name\":\"Brand Promise\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-brand-pillars has-base-color has-charcoal-background-color has-text-color has-background\">\n\n	<!-- wp:heading {\"level\":2,\"className\":\"tb-sr-only\"} -->\n	<h2 class=\"wp-block-heading tb-sr-only\">What you can expect from Tanya</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:columns {\"align\":\"wide\",\"className\":\"tb-brand-pillars__grid\"} -->\n	<div class=\"wp-block-columns alignwide tb-brand-pillars__grid\">\n\n		<!-- wp:column {\"className\":\"tb-brand-pillar tb-reveal\"} -->\n		<div class=\"wp-block-column tb-brand-pillar tb-reveal\">\n			<!-- wp:paragraph {\"className\":\"tb-brand-pillar__label\"} -->\n			<p class=\"tb-brand-pillar__label\">Clear Advice</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p>Practical answers that help you make a decision you will still feel good about years from now.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-brand-pillar tb-reveal\"} -->\n		<div class=\"wp-block-column tb-brand-pillar tb-reveal\">\n			<!-- wp:paragraph {\"className\":\"tb-brand-pillar__label\"} -->\n			<p class=\"tb-brand-pillar__label\">Local Knowledge</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p>Neighborhood context, market perspective, and the everyday details that shape where you live.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n		<!-- wp:column {\"className\":\"tb-brand-pillar tb-reveal\"} -->\n		<div class=\"wp-block-column tb-brand-pillar tb-reveal\">\n			<!-- wp:paragraph {\"className\":\"tb-brand-pillar__label\"} -->\n			<p class=\"tb-brand-pillar__label\">Real Relationships</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph -->\n			<p>Responsive, honest guidance built around your family, your goals, and what matters after closing.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n\n	</div>\n	<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-story-quote\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull tb-story-quote has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-story-quote__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-story-quote__content tb-reveal\">\n\n		<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n		<p class=\"tb-eyebrow\">What Clients Remember</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:paragraph {\"className\":\"tb-story-quote__mark\"} -->\n		<p class=\"tb-story-quote__mark\" aria-hidden=\"true\">“</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:quote {\"className\":\"tb-story-quote__quote\"} -->\n		<blockquote class=\"wp-block-quote tb-story-quote__quote\"><p>By the end, you felt like family.</p></blockquote>\n		<!-- /wp:quote -->\n\n				<!-- wp:paragraph {\"textColor\":\"charcoal\"} -->\n		<p class=\"has-charcoal-color has-text-color\">“Tanya did an amazing job selling our home. She made sure it was picture ready for getting the maximum possible price for the market. When we ran into snags she went above and beyond to fix them for us. She was available for any questions or concerns we may have had. When it came time to negotiate, she got the best price for us.”</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:paragraph {\"className\":\"tb-story-quote__attribution\",\"textColor\":\"charcoal\",\"fontSize\":\"small\"} -->\n		<p class=\"tb-story-quote__attribution has-charcoal-color has-text-color has-small-font-size\">Christian Herzberger · Google review</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:paragraph {\"className\":\"tb-text-link\"} -->\n		<p class=\"tb-text-link\"><a href=\"https://g.page/r/CTDpOcL-7SDkEAE\" target=\"_blank\" rel=\"noopener noreferrer\">Read Tanya’s Google reviews <span aria-hidden=\"true\">→</span></a></p>\n		<!-- /wp:paragraph -->\n\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-story-quote__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-story-quote__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-living-room.jpg)\"></div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"tb-quote-row-section tb-home-reviews\",\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull tb-quote-row-section tb-home-reviews has-alabaster-background-color has-background\">\n	<div class=\"tb-page-shell\">\n		<!-- wp:paragraph {\"className\":\"tb-eyebrow\",\"align\":\"center\"} -->\n		<p class=\"tb-eyebrow has-text-align-center\">What Clients Are Saying</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:shortcode -->\n[trustindex data-widget-id=f67a0f279ba6760db346a7f2d42]\n		<!-- /wp:shortcode -->\n	</div>\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-editorial-feature tb-editorial-feature\\u002d\\u002dphoto-left tb-about-feature\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/about-intro\",\"name\":\"About Intro\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-editorial-feature tb-editorial-feature--photo-left tb-about-feature has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-editorial-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-editorial-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/uploads/2026/07/about-main.jpg);background-position:center 20%\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-editorial-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-editorial-feature__content tb-reveal\">\n\n		<!-- wp:paragraph {\"className\":\"tb-eyebrow\",\"textColor\":\"dusty-blush\"} -->\n		<p class=\"tb-eyebrow has-dusty-blush-color has-text-color\">Meet Tanya</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"xx-large\"} -->\n		<h2 class=\"wp-block-heading has-xx-large-font-size\">Real estate is personal.<br><em>Your guidance should be, too.</em></h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Buying or selling a home is exciting, stressful, emotional, and sometimes downright overwhelming. Tanya’s goal is to make sure you never feel like you are navigating it alone.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">You will get honest advice, quick answers, plenty of laughs, and someone who genuinely cares about the outcome—not just the closing date.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n		<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--40)\">\n			<!-- wp:button {\"backgroundColor\":\"charcoal\",\"textColor\":\"base\"} -->\n			<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-base-color has-charcoal-background-color has-text-color has-background wp-element-button\" href=\"/about/\">Meet Tanya</a></div>\n			<!-- /wp:button -->\n		</div>\n		<!-- /wp:buttons -->\n\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"tb-journal-section\",\"backgroundColor\":\"alabaster\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"},\"metadata\":{\"patternName\":\"tanya-barrans/blog-teaser\",\"name\":\"Latest From the Journal\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-journal-section has-alabaster-background-color has-background\">\n\n	<!-- wp:group {\"align\":\"wide\",\"className\":\"tb-journal-section__header\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\",\"verticalAlignment\":\"bottom\"}} -->\n	<div class=\"wp-block-group alignwide tb-journal-section__header\">\n		<!-- wp:group {\"className\":\"tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group tb-reveal\">\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">The Journal</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:heading {\"fontSize\":\"xx-large\"} -->\n			<h2 class=\"wp-block-heading has-xx-large-font-size\">Latest from the Journal</h2>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n			<p class=\"has-graphite-color has-text-color\">The Journal is the blog: practical ideas for real estate, decorating, gardening, food, homeownership, and everyday life. Rooted in Renton is reserved for local stories and neighborhood guides.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:paragraph {\"className\":\"tb-text-link\"} -->\n		<p class=\"tb-text-link\"><a href=\"/blog/\">Explore the Journal <span aria-hidden=\"true\">→</span></a></p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:query {\"queryId\":1,\"query\":{\"perPage\":3,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\"},\"align\":\"wide\",\"className\":\"tb-journal-query\"} -->\n	<div class=\"wp-block-query alignwide tb-journal-query\">\n		<!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n\n			<!-- wp:group {\"className\":\"tb-journal-card tb-reveal\",\"layout\":{\"type\":\"constrained\"}} -->\n			<div class=\"wp-block-group tb-journal-card\">\n				<!-- wp:post-featured-image {\"aspectRatio\":\"4/3\",\"isLink\":true} /-->\n				<!-- wp:group {\"className\":\"tb-journal-card__content\",\"layout\":{\"type\":\"constrained\"}} -->\n				<div class=\"wp-block-group tb-journal-card__content\">\n					<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-journal-card__category\"} /-->\n					<!-- wp:post-title {\"isLink\":true,\"fontSize\":\"large\"} /-->\n					<!-- wp:post-date {\"textColor\":\"graphite\",\"fontSize\":\"small\"} /-->\n				</div>\n				<!-- /wp:group -->\n			</div>\n			<!-- /wp:group -->\n\n		<!-- /wp:post-template -->\n	</div>\n	<!-- /wp:query -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-newsletter-feature\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/newsletter\",\"name\":\"Newsletter Signup\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-newsletter-feature has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg)\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__content tb-reveal\">\n		<!-- wp:paragraph {\"className\":\"tb-script-accent\"} -->\n		<p class=\"tb-script-accent\">Let’s stay in touch</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"x-large\"} -->\n		<h2 class=\"wp-block-heading has-x-large-font-size\">Notes worth opening.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Useful home ideas, local stories, and honest real estate guidance—delivered with no pressure and no polished filler.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:html -->\n		<form class=\"tb-newsletter-form\" novalidate>\n			<div class=\"tb-newsletter-fields\">\n				<label class=\"tb-sr-only\" for=\"tb-nl-name\">First name</label>\n				<input type=\"text\" id=\"tb-nl-name\" name=\"name\" class=\"tb-newsletter-input\" placeholder=\"First name\" autocomplete=\"given-name\" />\n\n				<label class=\"tb-sr-only\" for=\"tb-nl-email\">Email address</label>\n				<input type=\"email\" id=\"tb-nl-email\" name=\"email\" class=\"tb-newsletter-input\" placeholder=\"Email address\" autocomplete=\"email\" required />\n\n				<div class=\"tb-newsletter-hp\" aria-hidden=\"true\">\n					<label for=\"tb-nl-website\">Website</label>\n					<input type=\"text\" id=\"tb-nl-website\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" />\n				</div>\n\n				<button type=\"submit\" class=\"tb-newsletter-submit\">Subscribe</button>\n			</div>\n			<p class=\"tb-newsletter-status\" role=\"status\" aria-live=\"polite\"></p>\n		</form>\n		<!-- /wp:html -->\n\n		<!-- wp:paragraph {\"className\":\"tb-newsletter-feature__privacy\"} -->\n		<p class=\"tb-newsletter-feature__privacy\">No spam. Unsubscribe whenever you like.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-closing-cta\",\"backgroundColor\":\"alabaster\",\"textColor\":\"charcoal\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"920px\"},\"metadata\":{\"patternName\":\"tanya-barrans/cta\",\"name\":\"Contact CTA Band\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-closing-cta has-charcoal-color has-alabaster-background-color has-text-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-closing-cta__inner tb-reveal\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"760px\"}} -->\n	<div class=\"wp-block-group tb-closing-cta__inner tb-reveal\">\n		<!-- wp:paragraph {\"className\":\"tb-script-accent\",\"textColor\":\"charcoal\"} -->\n		<p class=\"tb-script-accent has-charcoal-color has-text-color\">When you’re ready</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"textAlign\":\"center\",\"fontSize\":\"xx-large\",\"textColor\":\"charcoal\"} -->\n		<h2 class=\"wp-block-heading has-text-align-center has-charcoal-color has-text-color has-xx-large-font-size\">Your next move should support the life you want to live.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"charcoal\"} -->\n		<p class=\"has-text-align-center has-charcoal-color has-text-color\">Whether you are three years or three weeks from a move, Tanya will give you an honest look at your options—without pressure.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"flexWrap\":\"wrap\"},\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|40\"}}}} -->\n		<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--40)\">\n			<!-- wp:button {\"backgroundColor\":\"charcoal\",\"textColor\":\"base\"} -->\n			<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-base-color has-charcoal-background-color has-text-color has-background wp-element-button\" href=\"/contact/\">Tell Me What You’re Planning</a></div>\n			<!-- /wp:button -->\n			<!-- wp:button {\"className\":\"tb-button-outline\",\"textColor\":\"charcoal\"} -->\n			<div class=\"wp-block-button tb-button-outline\"><a class=\"wp-block-button__link has-charcoal-color has-text-color wp-element-button\" href=\"https://calendar.app.google/zndHShd1Rm6W6Qb38\" target=\"_blank\" rel=\"noopener noreferrer\">Schedule a Conversation</a></div>\n			<!-- /wp:button -->\n		</div>\n		<!-- /wp:buttons -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n\n\n<!-- wp:html -->\n<script defer async src=\"https://cdn.trustindex.io/loader-cert.js?1c1116f795cd76061386b3bd8ca\"></script>\n<!-- /wp:html -->\n', 'Front Page', 'Displays your site\'s homepage, whether it is set to display latest posts or a static page. The Front Page template takes precedence over all templates.', 'inherit', 'closed', 'closed', '', '95-revision-v1', '', '', '2026-08-21 18:19:55', '2026-08-21 18:19:55', '', 95, 'https://violet-wren-104886.hostingersite.com/?p=90263', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(90264, 2, '2026-08-21 18:22:44', '2026-08-21 18:22:44', '<!-- wp:html -->\n<style>\nbody.page-id-9 .wp-block-post-title{display:none!important}\n.tb-listings-page{width:100vw;max-width:none!important;margin-left:calc(50% - 50vw);margin-top:-1px;overflow:hidden}\n.tb-listings-page-hero{position:relative;min-height:clamp(520px,63vw,720px);display:flex;align-items:flex-end;background:linear-gradient(90deg,rgba(30,50,75,.23),rgba(30,50,75,.02)),url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/renton-pending.jpg\') center 55%/cover no-repeat;overflow:hidden}\n.tb-listings-page-hero:after{content:\"\";position:absolute;inset:50% 0 0;background:linear-gradient(transparent,rgba(26,47,70,.2));pointer-events:none}\n.tb-listings-hero-card{position:relative;z-index:1;width:min(650px,calc(100% - 48px));margin:0 0 -54px max(5vw,24px);padding:clamp(34px,5vw,64px);background:#fbf7f1;color:#344c6a;box-shadow:0 24px 70px rgba(35,52,73,.2)}\n.tb-listings-kicker,.tb-listings-page .tb-eyebrow{font-size:.72rem!important;letter-spacing:.18em;text-transform:uppercase;font-weight:700;color:#b46f88!important}\n.tb-listings-hero-card h2{font-size:clamp(2.7rem,5.4vw,5.2rem);line-height:.92;margin:.5rem 0 1.25rem;letter-spacing:-.03em}\n.tb-listings-hero-card h2 em{color:#c27e98;font-weight:inherit}\n.tb-listings-hero-card p{font-size:clamp(1rem,1.3vw,1.18rem);line-height:1.7;max-width:540px}\n.tb-listings-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:26px}\n.tb-listings-btn{display:inline-block;padding:14px 22px;background:#344c6a;color:white!important;text-decoration:none!important;font-size:.76rem;font-weight:700;letter-spacing:.09em;text-transform:uppercase;border:1px solid #344c6a;transition:.2s}\n.tb-listings-btn.alt{background:transparent;color:#344c6a!important}\n.tb-listings-btn:hover{transform:translateY(-2px);background:#c27e98;border-color:#c27e98;color:white!important}\n.tb-listings-page #current-listings{padding-top:125px!important}\n.tb-listings-page #current-listings .tb-sales-grid{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}\n.tb-listings-page #current-listings .tb-card{padding:0;background:#fff;box-shadow:0 15px 45px rgba(52,76,106,.1);overflow:hidden;transition:.25s}\n.tb-listings-page #current-listings .tb-card:hover{transform:translateY(-7px);box-shadow:0 22px 60px rgba(52,76,106,.17)}\n.tb-listings-page #current-listings .tb-sales-photo{height:clamp(300px,32vw,440px);overflow:hidden}\n.tb-listings-page .tb-sales-photo img{width:100%;height:100%;object-fit:cover;transition:transform .55s}\n.tb-listings-page .tb-card:hover .tb-sales-photo img{transform:scale(1.035)}\n.tb-listings-page #current-listings .tb-card p{padding-left:24px;padding-right:24px}\n.tb-listings-page #current-listings .tb-card p:first-of-type{font-size:1.45rem;margin-top:1.25rem!important}\n.tb-listings-page #current-listings .tb-card p:last-child{padding-bottom:24px;font-size:.88rem!important}\n.tb-listings-page .has-alabaster-background-color .tb-sales-grid{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}\n.tb-listings-page .has-alabaster-background-color .tb-card{padding:0 0 18px;background:#fff;box-shadow:0 10px 35px rgba(52,76,106,.08);overflow:hidden}\n.tb-listings-page .has-alabaster-background-color .tb-sales-photo{height:260px}\n.tb-listings-page .has-alabaster-background-color .tb-card p{padding-left:18px;padding-right:18px}\n.tb-listings-page .has-alabaster-background-color .tb-card strong{font-size:1.15rem}\n.tb-listings-proof{padding:32px 24px;background:#344c6a;color:#fff;display:grid;grid-template-columns:repeat(3,1fr);text-align:center;gap:1px}\n.tb-listings-proof div{padding:10px 20px;border-right:1px solid rgba(255,255,255,.25)}\n.tb-listings-proof div:last-child{border:0}.tb-listings-proof strong{display:block;font-family:Georgia,serif;font-size:1.35rem}.tb-listings-proof span{font-size:.7rem;letter-spacing:.13em;text-transform:uppercase;opacity:.8}\n.tb-listings-final{background:#344c6a;color:#fff;padding:clamp(60px,8vw,110px) 24px;text-align:center}\n.tb-listings-final-inner{max-width:850px;margin:auto}.tb-listings-final .tb-listings-kicker{color:#efb6c8!important}\n.tb-listings-final h2{color:#fff;font-size:clamp(2.4rem,4.8vw,4.7rem);line-height:1.03;margin:12px 0 18px}.tb-listings-final p{max-width:620px;margin:0 auto 28px;font-size:1.08rem;line-height:1.7}\n.tb-listings-final .tb-listings-btn{background:#efb6c8;border-color:#efb6c8;color:#344c6a!important}.tb-listings-final .tb-listings-btn.alt{background:transparent;color:#fff!important;border-color:rgba(255,255,255,.7)}\n@media(max-width:800px){.tb-listings-page-hero{min-height:560px;background-position:center}.tb-listings-hero-card{width:calc(100% - 32px);margin:0 16px -40px;padding:32px 25px}.tb-listings-page #current-listings{padding-top:92px!important}.tb-listings-page #current-listings .tb-sales-grid,.tb-listings-page .has-alabaster-background-color .tb-sales-grid{grid-template-columns:1fr}.tb-listings-page #current-listings .tb-sales-photo{height:360px}.tb-listings-proof{grid-template-columns:1fr}.tb-listings-proof div{border-right:0;border-bottom:1px solid rgba(255,255,255,.25)}}\n\n.tb-listings-page #current-listings .tb-eyebrow,.tb-listings-page .has-alabaster-background-color .tb-eyebrow{color:#6F8A74!important}\n.tb-listings-page #current-listings .tb-card{border-bottom:6px solid #6F8A74}\n.tb-listings-page .has-alabaster-background-color .tb-card:nth-child(3n+2){border-bottom:4px solid #6F8A74}\n.tb-listings-page .tb-listings-btn.alt:hover{background:#6F8A74;border-color:#6F8A74;color:#fff!important}\n.tb-listings-proof{border-top:8px solid #6F8A74}\n\n.tb-listings-page .has-alabaster-background-color .tb-sales-grid{align-items:stretch}\n.tb-listings-page .has-alabaster-background-color .tb-card{height:100%;display:flex;flex-direction:column;border-bottom-width:4px}\n.tb-listings-page .has-alabaster-background-color .tb-sales-photo{height