(90300, 2, '2026-08-23 00:02:41', '2026-08-23 00:02:41', '<!-- wp:html --><style>body .wp-block-post-title{display:none!important}.tb-local-portfolio{width:100vw;max-width:none!important;margin-left:calc(50% - 50vw);margin-top:-96px;background:#fbf8f4;color:#344c6a;overflow:hidden}.tbp-port-hero{padding:clamp(90px,10vw,150px) 28px 70px;background:#344c6a;color:#fff;text-align:center}.tbp-port-inner{max-width:1050px;margin:auto}.tbp-eyebrow{font-size:.7rem;letter-spacing:.18em;text-transform:uppercase;font-weight:700;color:#d6a3b5}.tbp-port-hero h1{font-family:Georgia,serif;font-size:clamp(3rem,6vw,6.2rem);line-height:.96;margin:.5rem 0 1.2rem;color:#fbf8f4}.tbp-port-hero p{max-width:760px;margin:auto;font-size:1.08rem;line-height:1.75;color:rgba(255,255,255,.85)}.tbp-city-nav{display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin-top:30px}.tbp-city-nav a{padding:10px 14px;border:1px solid rgba(255,255,255,.45);color:#fff!important;text-decoration:none!important;font-size:.7rem;letter-spacing:.1em;text-transform:uppercase}.tbp-city-nav a:hover{background:#6f8a74;border-color:#6f8a74}.tbp-summary{display:grid;grid-template-columns:repeat(3,1fr);max-width:1050px;margin:-35px auto 0;position:relative;background:#dbc8b3}.tbp-summary div{text-align:center;padding:25px;border-right:1px solid rgba(52,76,106,.2)}.tbp-summary div:last-child{border:0}.tbp-summary strong{display:block;font-family:Georgia,serif;font-size:1.8rem}.tbp-summary span{font-size:.66rem;letter-spacing:.12em;text-transform:uppercase}.tbp-city-section{max-width:1240px;margin:auto;padding:clamp(70px,8vw,110px) 28px;border-bottom:1px solid #dbc8b3}.tbp-city-heading{display:flex;justify-content:space-between;align-items:end;gap:35px;margin-bottom:42px}.tbp-city-heading h2{font-family:Georgia,serif;font-size:clamp(2.6rem,4.7vw,4.8rem);margin:.4rem 0 0}.tbp-city-heading p{max-width:380px;line-height:1.6;color:#59616b}.tbp-sales-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;align-items:stretch}.tbp-sale-card{background:#fff;box-shadow:0 12px 38px rgba(52,76,106,.09);display:flex;flex-direction:column;overflow:hidden;border-bottom:5px solid #6f8a74}.tbp-sale-photo{height:250px;position:relative;overflow:hidden}.tbp-sale-photo img{width:100%;height:100%;object-fit:cover;transition:.4s}.tbp-sale-card:hover img{transform:scale(1.035)}.tbp-sale-photo span{position:absolute;z-index:2;top:14px;left:14px;background:#d6a3b5;color:#344c6a;padding:8px 11px;font-size:.65rem;letter-spacing:.12em;font-weight:800}.tbp-sale-body{padding:22px;display:flex;flex-direction:column;flex:1}.tbp-sale-city{font-size:.66rem;letter-spacing:.14em;text-transform:uppercase;color:#6f8a74;font-weight:700}.tbp-sale-body h3{font-family:Georgia,serif;font-size:1.45rem;margin:.45rem 0;color:#344c6a}.tbp-sale-price{font-family:Georgia,serif;font-size:1.25rem}.tbp-sale-details{font-size:.78rem;color:#59616b;min-height:1.4rem}.tbp-role-note{background:#f4e8ec;padding:14px;margin:10px 0 18px;border-left:4px solid #d6a3b5}.tbp-role-note strong,.tbp-role-note span{display:block}.tbp-role-note strong{font-size:.7rem;text-transform:uppercase;letter-spacing:.09em}.tbp-role-note span{font-size:.8rem;line-height:1.5;margin-top:4px;color:#59616b}.tbp-sale-body>a{margin-top:auto;color:#344c6a!important;font-size:.68rem;letter-spacing:.08em;text-transform:uppercase;font-weight:700;text-decoration:none!important}.tbp-port-cta{background:#344c6a;color:#fff;text-align:center;padding:90px 28px}.tbp-port-cta h2{font-family:Georgia,serif;font-size:clamp(2.6rem,5vw,5rem);color:#fff;margin:.5rem 0 1rem}.tbp-port-cta p{max-width:650px;margin:0 auto 25px;line-height:1.7}.tbp-btn{display:inline-block;padding:14px 22px;background:#d6a3b5;color:#344c6a!important;text-decoration:none!important;text-transform:uppercase;letter-spacing:.1em;font-size:.7rem;font-weight:700}@media(max-width:850px){.tbp-summary{grid-template-columns:1fr;margin:0}.tbp-summary div{border-right:0;border-bottom:1px solid r