s:center;background:#fbf6eb;color:#10263f;font-size:22px}.tb-renton-series-card strong{display:block;font-family:Cormorant Garamond,serif;font-size:1.55rem;margin-top:12px}.tb-renton-series-card small{color:#b58a08;font-weight:700}.tb-renton-category-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.tb-renton-category{min-height:250px;display:flex;align-items:flex-end;padding:20px;color:#fff!important;text-decoration:none;background-size:cover;background-position:center;border-radius:6px;box-shadow:inset 0 -110px 80px rgba(11,31,59,.78)}.tb-renton-category strong{font-size:1.05rem;letter-spacing:.08em;text-transform:uppercase}.tb-renton-guide-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.tb-renton-guide{display:grid;grid-template-columns:120px 1fr;gap:18px;align-items:center;padding:18px;background:#fff;border:1px solid #e4dccd;color:#10263f!important;text-decoration:none}.tb-renton-guide img{width:120px;height:120px;object-fit:cover}.tb-renton-guide strong{font-family:Cormorant Garamond,serif;font-size:1.45rem;line-height:1.1}.tb-renton-guide span{display:block;margin-top:8px;color:#a97f06;font-size:.78rem;font-weight:700;text-transform:uppercase}.tb-renton-video-wrap{position:relative;max-width:860px;margin:0 auto;aspect-ratio:16/9;border-radius:6px;overflow:hidden;box-shadow:0 20px 60px rgba(16,38,63,.25)}.tb-renton-video-wrap iframe{position:absolute;inset:0;width:100%;height:100%;border:0}.tb-renton-video-caption{text-align:center;color:#6b7280;font-size:.95rem;margin:18px auto 0;max-width:560px}@media(max-width:760px){.tb-renton-series-grid,.tb-renton-category-grid,.tb-renton-guide-grid{grid-template-columns:1fr}.tb-renton-category{min-height:210px}.tb-renton-series,.tb-renton-categories,.tb-renton-guides{padding:52px 20px}.tb-renton-stamp--official{width:118px;height:118px}}.tb-renton-cta-duo{display:grid;grid-template-columns:1fr 1fr}.tb-renton-cta-duo__col{padding:64px 40px}.tb-renton-cta-duo__col--mustard{background:#f7ecd3;border-top:3px solid #d9a441;border-bottom:3px solid #d9a441}.tb-renton-cta-duo__col h2{margin:0 0 16px;font-size:clamp(1.9rem,3vw,2.6rem);line-height:1.1}.tb-renton-cta-duo__col .tb-renton-editorial__intro{font-size:1.05rem;max-width:100%}.tb-renton-cta-duo__secondary{display:inline-flex;align-items:center;font-weight:700;color:#10263f;text-decoration:underline;padding:14px 0;margin-left:6px}@media(max-width:800px){.tb-renton-cta-duo{grid-template-columns:1fr}}\n.tb-renton-hero__links .tb-renton-button{background:#10263f;color:#fff;padding:.9rem 1.9rem;border-radius:2px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;font-size:.8rem;text-decoration:none;display:inline-block;transition:background .2s;border:1px solid #10263f}\n.tb-renton-hero__links .tb-renton-button:hover{background:#0b1c30}\n.tb-renton-hero__links .tb-renton-link{display:inline-flex;align-items:center;gap:.4rem;padding:.9rem 1.6rem;border:1px solid #10263f;color:#10263f;font-weight:600;letter-spacing:.08em;text-transform:uppercase;font-size:.8rem;text-decoration:none;border-radius:2px;transition:background .2s,color .2s}\n.tb-renton-hero__links .tb-renton-link:hover{background:#10263f;color:#fff}\n.tb-renton-editorial--navy h2{font-family:var(--wp--preset--font-family--sans);font-weight:600;font-size:clamp(1.4rem,2.4vw,1.9rem);letter-spacing:.01em;line-height:1.35;color:#fff;text-transform:none}\n@media(max-width:800px){.tb-renton-hero.tb-renton-hero--split{flex-direction:column}.tb-renton-hero--split .tb-renton-hero__inner{max-width:100%;padding:40px 24px}.tb-renton-hero__photo{min-height:260px}.tb-renton-hero__photo::before{background:linear-gradient(180deg,#fbf6eb 0%,rgba(251,246,235,0) 20%)}}\n\n.tb-renton-roots{padding:88px 0;background:#fbf7f0}\n.tb-renton-roots__card{display:grid;grid-template-columns:minmax(280px,.82fr) minmax(0,1.18fr);overflow:hidden;border:1px solid rgba(52,76,106,.13);border-radius:28px;background:#fff;box-shadow:0 24px 60px rgba(1,24,55,.12)}\n.tb-renton-roots__mark{display:flex;flex-direction:column;justify-content:flex-end;min-height:430px;padding:54px;background:linear-gradient(155deg,#001f47,#082c5a);position:relative;overflow:hidden}\n.tb-renton-roots__mark:before{content:\"ROOTS\";position:absolute;left:-8px;top:12px;font-family:Georgia,serif;font-size:clamp(5rem,11vw,9.5rem);line-height:1;color:rgba(255,255,255,.06)}\n.tb-renton-roots__eyebrow{position:relative;margin:0 0 16px;color:#f2b51d;font:800 .78rem/1.2 Montserrat,Arial,sans-serif;letter-spacing:.16em;text-transform:uppercase}\n.tb-renton-roots__mark h2{position:relative;margin:0;color:#fff;font-family:Georgia,serif;font-size:clamp(2.5rem,4.8vw,4.4rem);line-height:1.02}\n.tb-renton-roots__copy{display:flex;flex-direction:column;justify-content:center;padding:clamp(44px,6vw,72px)}\n.tb-renton-roots__copy p{margin:0;color:#26364a;font:400 1.06rem/1.85 Montserrat,Arial,sans-serif}\n.tb-renton-roots__link{display:inline-flex;width:max-content;gap:8px;margin-top:26px;padding-bottom:6px;border-bottom:2px solid #f2b51d;color:#001f47!important;font:800 .78rem/1.2 Montserrat,Arial,sans-serif;letter-spacing:.12em;text-transform:uppercase;text-decoration:none}\n@media(max-width:820px){.tb-renton-roots__card{grid-template-columns:1fr}.tb-renton-roots__mark{min-height:320px;padding:40px 30px}.tb-renton-roots__copy{padding:40px 30px}}\n\n</style>\n	<!-- /wp:html -->\n\n	<!-- The Journal newsletter pattern is deliberately not reused here: it is\n	     styled for the Journal page and renders unreadably in this context.\n	     The blueprint asks for a Renton-specific signup with its own copy,\n	     which is a separate build. -->\n	<!-- wp:group {\"align\":\"full\",\"className\":\"tb-renton\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/renton-hub\",\"name\":\"Renton Hub\",\"categories\":[\"featured\"]}} -->\n<!-- wp:html -->\n	<section class=\"tb-renton-hero tb-renton-hero--split\" aria-labelledby=\"renton-title\">\n		<div class=\"tb-renton-hero__photo\"></div>\n		<div class=\"tb-page-shell tb-renton-hero__inner\">\n						<img class=\"tb-renton-stamp tb-renton-stamp--official\" src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/2.png\" alt=\"Rooted in Renton, established 1901\" width=\"1536\" height=\"1536\">\n			<h1 id=\"renton-title\" class=\"tb-renton-title\">Rooted in Renton</h1>\n			<p class=\"tb-renton-dek\">Local stories, favorite places and the people who make Renton feel like home.</p>\n			<p class=\"tb-renton-hero__links\">\n				<a class=\"tb-renton-button\" href=\"#renton-latest\">Explore the latest stories</a>\n				<a class=\"tb-renton-link\" href=\"#renton-series\">Watch the series <span aria-hidden=\"true\">&rarr;</span></a>\n			</p>\n		</div>\n	</section>\n<section class=\"tb-renton-roots\" aria-labelledby=\"roots-renton\"><div class=\"tb-page-shell\"><div class=\"tb-renton-roots__card\"><div class=\"tb-renton-roots__mark\"><p class=\"tb-renton-roots__eyebrow\">The roots</p><h2 id=\"roots-renton\">A city built where water, work and people meet.</h2></div><div class=\"tb-renton-roots__copy\"><p>Long before Renton had streets or city limits, this was Duwamish homeland at the meeting of the Cedar and Black rivers with Lake Washington. Coal brought miners and new arrivals in the nineteenth century, followed by railroads, brickworks and Pacific Car and Foundry, known today as PACCAR. Renton incorporated in 1901 and kept reinventing itself, from industry and wartime airplane production to the neighborhoods, businesses and cultures that shape the city now. The work changed, but the through line stayed the same. Renton has always been a place where people build things, build community and make a life beside the water.</p><a class=\"tb-renton-roots__link\" href=\"https://www.rentonwa.gov/Activities-Events/Museum/City-of-Renton-Timeline\" target=\"_blank\" rel=\"noopener noreferrer\">Explore Renton\'s history <span aria-hidden=\"true\">→</span></a></div></div></div></section>\n\n	<!-- /wp:html -->\n\n	<!-- wp:group {\"className\":\"tb-renton-featured\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-renton-featured\">\n		<div class=\"tb-page-shell\">\n\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">Featured Story</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:query {\"queryId\":40,\"query\":{\"perPage\":1,\"pages\":0,\"offset\":0,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"include\",\"include\":[59],\"taxQuery\":{\"category\":[23]},\"inherit\":false},\"align\":\"wide\"} -->\n			<div class=\"wp-block-query alignwide\">\n				<!-- wp:post-template -->\n					<!-- wp:group {\"className\":\"tb-renton-feature-card\",\"layout\":{\"type\":\"default\"}} -->\n					<div class=\"wp-block-group tb-renton-feature-card\">\n						<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"16/9\"} /-->\n						<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-renton-kicker\"} /-->\n						<!-- wp:post-title {\"isLink\":true,\"fontSize\":\"x-large\"} /-->\n						<!-- wp:post-excerpt {\"excerptLength\":34} /-->\n						<!-- wp:post-date {\"format\":\"F j, Y\",\"className\":\"tb-renton-date\"} /-->\n					</div>\n					<!-- /wp:group -->\n				<!-- /wp:post-template -->\n\n				<!-- wp:query-no-results -->\n					<!-- wp:paragraph {\"className\":\"tb-renton-empty\"} -->\n					<p class=\"tb-renton-empty\">The first Renton stories are being written now. In the meantime, tell Tanya what you would like to see covered, a favourite restaurant, a park worth knowing about, or a corner of the city that deserves more attention.</p>\n					<!-- /wp:paragraph -->\n\n					<!-- wp:buttons -->\n					<div class=\"wp-block-buttons\">\n						<!-- wp:button {\"backgroundColor\":\"ink\"} -->\n						<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-ink-background-color has-background wp-element-button\" href=\"/contact/\">Suggest a Renton story</a></div>\n						<!-- /wp:button -->\n					</div>\n					<!-- /wp:buttons -->\n				<!-- /wp:query-no-results -->\n			</div>\n			<!-- /wp:query -->\n\n		</div>\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-series\" id=\"renton-series\"><div class=\"tb-page-shell\"><h2 class=\"tb-renton-section-title\">Watch the Series</h2><div class=\"tb-renton-video-wrap\"><iframe src=\"https://www.youtube.com/embed/FcI3-ix5iqE\" title=\"What Community Means to Me | Tanya Barrans, Your Neighborhood Realtor in Renton, WA\" loading=\"lazy\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen></iframe></div><p class=\"tb-renton-video-caption\">From the Beyond the Sale podcast, what community means to Tanya, and why Renton is home.</p><div class=\"tb-renton-actions\" style=\"justify-content:center\"><a class=\"tb-renton-action tb-renton-action--navy\" href=\"https://www.instagram.com/tanyabarrans/\" target=\"_blank\" rel=\"noopener noreferrer\">More Rooted in Renton on Instagram</a></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-categories\"><div class=\"tb-page-shell\"><h2 class=\"tb-renton-section-title\">Explore by Category</h2><div class=\"tb-renton-category-grid\"><a class=\"tb-renton-category\" href=\"/category/renton/eat-drink/\" style=\"background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg\')\"><strong>Eat &amp; Drink →</strong></a><a class=\"tb-renton-category\" href=\"/category/renton/parks-outdoors/\" style=\"background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-kitchen-garden.jpg\')\"><strong>Parks &amp; Outdoors →</strong></a><a class=\"tb-renton-category\" href=\"/category/renton/local-businesses/\" style=\"background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-front-door.jpg\')\"><strong>Local Businesses →</strong></a><a class=\"tb-renton-category\" href=\"/category/renton/community-events/\" style=\"background-image:url(\'https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-living-room.jpg\')\"><strong>Events →</strong></a></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-editorial tb-renton-editorial--navy\"><div class=\"tb-page-shell\"><p class=\"tb-eyebrow\">Tanya\'s Current Renton Favorites</p><h2>A few places worth knowing right now.</h2><p class=\"tb-renton-editorial__intro\">Personal picks from around the city,the places, walks, and small businesses Tanya is genuinely enjoying and recommending.</p><div class=\"tb-renton-favorites\"><article class=\"tb-renton-favorite\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-kitchen-garden.jpg\" alt=\"\"><div><strong>The local plant shop</strong><span>Greenery, good advice, and a reason to linger.</span></div></article><article class=\"tb-renton-favorite\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/i-heart-renton-mural.png\" alt=\"\"><div><strong>Downtown Renton</strong><span>The mural, independent businesses, and neighborhood character.</span></div></article><article class=\"tb-renton-favorite\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg\" alt=\"\"><div><strong>A cozy coffee stop</strong><span>A warm drink, a friendly corner, and time to catch up.</span></div></article><article class=\"tb-renton-favorite\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-hero.jpg\" alt=\"\"><div><strong>Renton Farmers Market</strong><span>Local finds, familiar faces, and a seasonal tradition.</span></div></article></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:group {\"className\":\"tb-renton-latest\",\"layout\":{\"type\":\"default\"},\"anchor\":\"renton-latest\"} -->\n	<div class=\"wp-block-group tb-renton-latest\" id=\"renton-latest\">\n		<div class=\"tb-page-shell\">\n\n			<!-- wp:paragraph {\"className\":\"tb-eyebrow\"} -->\n			<p class=\"tb-eyebrow\">More From Renton</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:query {\"queryId\":41,\"query\":{\"perPage\":6,\"pages\":0,\"offset\":1,\"postType\":\"post\",\"order\":\"desc\",\"orderBy\":\"date\",\"taxQuery\":{\"category\":[23]},\"inherit\":false},\"align\":\"wide\"} -->\n			<div class=\"wp-block-query alignwide\">\n				<!-- wp:post-template {\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n					<!-- wp:group {\"className\":\"tb-card tb-renton-card\",\"layout\":{\"type\":\"default\"}} -->\n					<div class=\"wp-block-group tb-card tb-renton-card\">\n						<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"4/3\"} /-->\n						<!-- wp:group {\"className\":\"tb-renton-card__body\",\"layout\":{\"type\":\"default\"}} -->\n						<div class=\"wp-block-group tb-renton-card__body\">\n							<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-renton-kicker\"} /-->\n							<!-- wp:post-title {\"isLink\":true,\"fontSize\":\"large\"} /-->\n							<!-- wp:post-date {\"format\":\"F j, Y\",\"className\":\"tb-renton-date\"} /-->\n						</div>\n						<!-- /wp:group -->\n					</div>\n					<!-- /wp:group -->\n				<!-- /wp:post-template -->\n\n				<!-- wp:query-no-results -->\n					<!-- wp:paragraph {\"className\":\"tb-renton-empty\"} -->\n					<p class=\"tb-renton-empty\">More Renton stories are on the way.</p>\n					<!-- /wp:paragraph -->\n				<!-- /wp:query-no-results -->\n			</div>\n			<!-- /wp:query -->\n\n		</div>\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-guides\"><div class=\"tb-page-shell\"><h2 class=\"tb-renton-section-title\">Renton Guide Collection</h2><div class=\"tb-renton-guide-grid\"><a class=\"tb-renton-guide\" href=\"/20-things-to-do-in-renton-this-weekend-from-someone-who-lives-here/\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-hero.jpg\" alt=\"\"><div><strong>The Ultimate Renton Weekend Guide</strong><span>Read guide →</span></div></a><a class=\"tb-renton-guide\" href=\"/best-renton-neighborhoods-for-every-lifestyle-a-locals-honest-guide/\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-front-door.jpg\" alt=\"\"><div><strong>A Local\'s Guide to Renton Neighborhoods</strong><span>Read guide →</span></div></a><a class=\"tb-renton-guide\" href=\"/moving-to-renton-wa-a-practical-guide-to-planning-your-move/\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/themes/tanya-barrans/assets/images/lwyl-living-room.jpg\" alt=\"\"><div><strong>Moving to Renton: A Practical Guide</strong><span>Read guide →</span></div></a></div></div></section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-cta-duo\">\n		<div class=\"tb-renton-cta-duo__col tb-renton-cta-duo__col--mustard\">\n			<p class=\"tb-eyebrow\">Neighborhood Connection</p>\n			<h2>Love the place? Explore what it\'s like to live nearby.</h2>\n			<p class=\"tb-renton-editorial__intro\">Connect the restaurants, parks, businesses, and everyday stories you discover here with Renton\'s neighborhoods.</p>\n			<div class=\"tb-renton-actions\">\n				<a class=\"tb-renton-action tb-renton-action--navy\" href=\"/neighborhoods/\">Explore Renton neighborhoods</a>\n				<a class=\"tb-renton-cta-duo__secondary\" href=\"/best-renton-neighborhoods-for-every-lifestyle-a-locals-honest-guide/\">Read the neighborhood guide &rarr;</a>\n			</div>\n		</div>\n		<div class=\"tb-renton-cta-duo__col\">\n			<p class=\"tb-eyebrow\">Community Stories</p>\n			<h2>Know a Renton story we should tell?</h2>\n			<p class=\"tb-renton-editorial__intro\">Share a local business, community event, interesting person, hidden gem, or story idea. Rooted in Renton should be shaped by the people who call the city home.</p>\n			<div class=\"tb-renton-actions\">\n				<a class=\"tb-renton-action\" href=\"/contact/\">Suggest a Renton story</a>\n			</div>\n		</div>\n	</section>\n	<!-- /wp:html -->\n\n	<!-- wp:html -->\n	<section class=\"tb-renton-cta\" aria-labelledby=\"renton-cta-title\">\n		<div class=\"tb-page-shell\">\n			<h2 id=\"renton-cta-title\">Thinking about making Renton home?</h2>\n			<p>Or making a move within the city? Tanya can walk you through the neighbourhoods and the market without the sales pressure.</p>\n			<p class=\"tb-renton-cta__links\">\n				<a class=\"tb-renton-button tb-renton-button--light\" href=\"/contact/\">Ask Tanya a question</a>\n				<a class=\"tb-renton-link tb-renton-link--light\" href=\"/buy/\">Explore buying in Renton <span aria-hidden=\"true\">&rarr;</span></a>\n			</p>\n		</div>\n	</section>\n	<!-- /wp:html -->\n<!-- /wp:group -->\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n', 'page-renton', '', 'inherit', 'closed', 'closed', '', '103-revision-v1', '', '', '2026-08-26 02:54:18', '2026-08-26 02:54:18', '', 103, 'https://violet-wren-104886.hostingersite.com/?p=90375', 0, 'revision', '', 0),
(90376, 4, '2026-08-26 02:54:48', '2026-08-26 02:54:48', '<!-- wp:html -->\n<style>\n.tb-rooted-city{--navy:#344c6a;--pink:#c77798;--green:#718c78;--cream:#fbf7f0;--khaki:#ddcbb8;--ink:#26364a;background:var(--cream);color:var(--ink);font-family:Montserrat,Arial,sans-serif}\n.tb-rooted-city *{box-sizing:border-box}\n.tb-rooted-city a{text-decoration:none}\n.tb-rooted-city h1,.tb-rooted-city h2,.tb-rooted-city h3{font-family:Georgia,\"Times New Roman\",serif;color:var(--navy)}\n.tb-rooted-city__shell{width:min(1180px,calc(100% - 48px));margin:0 auto}\n.tb-rooted-city__hero{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(420px,.92fr);min-height:650px;background:var(--cream)}\n.tb-rooted-city__photo{min-height:650px;background-image:linear-gradient(90deg,rgba(38,54,74,.05),rgba(38,54,74,.18)),var(--city-photo);background-size:cover;background-position:center}\n.tb-rooted-city__hero-copy{display:flex;align-items:center;padding:72px clamp(36px,6vw,84px);position:relative;border-top:none}\n.tb-rooted-city__hero-copy:after{content:\"\";position:absolute;right:0;top:88px;width:0;height:0;background:transparent}\n.tb-rooted-city__eyebrow{margin:0 0 18px;color:var(--pink);font-size:.94rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase}\n.tb-rooted-city__hero h1{margin:0;font-size:clamp(3.4rem,6.3vw,6.7rem);line-height:.86;letter-spacing:-.02em;text-transform:uppercase}\n.tb-rooted-city__hero h1 span{display:block;color:inherit;font-style:normal;font-weight:inherit;display:inline}\n.tb-rooted-city__dek{max-width:590px;margin:28px 0 0;font-size:1.12rem;line-height:1.75}\n.tb-rooted-city__actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:32px}\n.tb-rooted-city__button{display:inline-flex;align-items:center;justify-content:center;min-height:54px;padding:14px 24px;background:var(--navy);color:#fff;font-size:.82rem;font-weight:800;letter-spacing:.11em;text-transform:uppercase}\n.tb-rooted-city__button--outline{background:transparent;color:var(--navy);border:1px solid var(--navy)}\n.tb-rooted-city__credit{margin-top:24px;font-size:.72rem;line-height:1.45;color:#667081}\n.tb-rooted-city__credit a{color:inherit;text-decoration:underline}\n.tb-rooted-city__intro{padding:92px 0}\n.tb-rooted-city__intro-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:64px;align-items:center}\n.tb-rooted-city__intro-card{min-height:430px;padding:54px;background:var(--navy);display:flex;flex-direction:column;justify-content:flex-end;position:relative;overflow:hidden}\n.tb-rooted-city__intro-card:before{content:\"ROOTED\";position:absolute;top:22px;left:34px;color:rgba(255,255,255,.08);font-family:Georgia,serif;font-size:clamp(5rem,12vw,10rem);line-height:1}\n.tb-rooted-city__intro-card .tb-rooted-city__eyebrow{color:#c77798}\n.tb-rooted-city__intro-card h2{position:relative;margin:0;color:#fff;font-size:clamp(2.5rem,5vw,4.5rem);line-height:1.02}\n.tb-rooted-city__intro-copy h2{font-size:clamp(2.7rem,5vw,4.8rem);line-height:1.02;margin:0}\n.tb-rooted-city__intro-copy h2 em{display:block;color:var(--pink);font-weight:500}\n.tb-rooted-city__intro-copy p{font-size:1.08rem;line-height:1.8;margin:24px 0 0}\n.tb-rooted-city__section{padding:88px 0}\n.tb-rooted-city__section--khaki{background:var(--khaki)}\n.tb-rooted-city__section--white{background:#fff}\n.tb-rooted-city__section-head{text-align:center;max-width:760px;margin:0 auto 44px}\n.tb-rooted-city__section-head .tb-rooted-city__eyebrow{margin-bottom:12px}\n.tb-rooted-city__section-head h2{font-size:clamp(2.6rem,5vw,4.6rem);line-height:1;margin:0}\n.tb-rooted-city__section-head h2 em{color:var(--pink);font-weight:500}\n.tb-rooted-city__section-head p{margin:20px auto 0;max-width:650px;line-height:1.7}\n.tb-rooted-city__story-grid{display:grid;grid-template-columns:1.35fr .65fr .65fr;gap:22px}\n.tb-rooted-city__story{min-height:330px;padding:34px;background:#fff;border:1px solid rgba(52,76,106,.18);display:flex;flex-direction:column;justify-content:flex-end}\n.tb-rooted-city__stor