(90382, 1, '2026-08-26 02:59:51', '2026-08-26 02:59:51', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:html -->\n<style>\n.tb-rooted-city{--navy:#344c6a;--pink:#c77798;--green:#718c78;--cream:#fbf7f0;--khaki:#ddcbb8;--ink:#26364a;background:var(--cream);color:var(--ink);font-family:Montserrat,Arial,sans-serif}\n.tb-rooted-city *{box-sizing:border-box}\n.tb-rooted-city a{text-decoration:none}\n.tb-rooted-city h1,.tb-rooted-city h2,.tb-rooted-city h3{font-family:Georgia,\"Times New Roman\",serif;color:var(--navy)}\n.tb-rooted-city__shell{width:min(1180px,calc(100% - 48px));margin:0 auto}\n.tb-rooted-city__hero{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(420px,.92fr);min-height:650px;background:var(--cream)}\n.tb-rooted-city__photo{min-height:650px;background-image:linear-gradient(90deg,rgba(38,54,74,.05),rgba(38,54,74,.18)),var(--city-photo);background-size:cover;background-position:center}\n.tb-rooted-city__hero-copy{display:flex;align-items:center;padding:72px clamp(36px,6vw,84px);position:relative;border-top:8px solid var(--green)}\n.tb-rooted-city__hero-copy:after{content:\"\";position:absolute;right:0;top:88px;width:18px;height:42%;background:var(--pink)}\n.tb-rooted-city__eyebrow{margin:0 0 18px;color:var(--pink);font-size:.94rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase}\n.tb-rooted-city__hero h1{margin:0;font-size:clamp(3.4rem,6.3vw,6.7rem);line-height:.86;letter-spacing:-.045em}\n.tb-rooted-city__hero h1 span{display:block;color:var(--pink);font-style:italic;font-weight:500}\n.tb-rooted-city__dek{max-width:590px;margin:28px 0 0;font-size:1.12rem;line-height:1.75}\n.tb-rooted-city__actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:32px}\n.tb-rooted-city__button{display:inline-flex;align-items:center;justify-content:center;min-height:54px;padding:14px 24px;background:var(--navy);color:#fff;font-size:.82rem;font-weight:800;letter-spacing:.11em;text-transfor