id var(--navy)}.cov .event h3{font-size:1.7rem;margin:.25em 0}.cov .lake{background:var(--wash)}.cov .lake-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:7vw}.cov .lake ul{columns:2;padding-left:20px;line-height:1.8}.cov .lake-map{padding:42px;background:white;border-top:8px solid var(--mustard);box-shadow:0 20px 50px rgba(11,31,58,.1)}.cov .lake-map strong{font-family:Georgia,serif;color:var(--navy);font-size:2rem;font-weight:400}.cov .stats{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:#d8dce0;margin-top:28px}.cov .stat{background:white;padding:25px}.cov .stat b{display:block;font-family:Georgia,serif;color:var(--navy);font-size:2rem}.cov .closing{background:var(--navy);color:white;text-align:center}.cov .closing h2{color:white!important}.cov .closing .logo{position:static;margin:0 auto 36px;width:310px;height:310px;filter:none}.cov .btn{display:inline-block;background:var(--mustard);color:var(--navy)!important;padding:15px 24px;text-decoration:none!important;font-weight:900;text-transform:uppercase;letter-spacing:.08em}.cov .small{font-size:.82rem;color:var(--muted)}\nbody.page-id-90243 header.wp-block-template-part>.wp-block-group,body.page-id-90243 footer.wp-block-template-part>.wp-block-group{background:#0b1f3a!important}body.page-id-90243 footer.wp-block-template-part,body.page-id-90243 footer.wp-block-template-part a{color:#fff!important}.cov .hero .logo{left:76%;right:auto;top:50%;bottom:auto;transform:translate(-50%,-50%);width:760px;height:760px}.cov .story-shell{position:relative;min-height:850px;padding:70px;background:var(--wash);border:1px solid #ded8ca}.cov .story-photo{position:absolute;inset:55px 38% 55px 45px}.cov .story-copy{position:relative;z-index:2;width:54%;margin-left:auto;margin-top:80px;padding:54px;background:#fff;border-top:7px solid var(--mustard);box-shadow:0 24px 55px rgba(11,31,58,.14)}.cov .story-credit{position:absolute;left:55px;bottom:24px;font-size:.68rem}.cov .food-features{display:grid;grid-template-columns:1.15fr .85fr;gap:22px}.cov .food-lead{padding:48px;background:var(--navy);color:#fff}.cov .food-lead h3{color:#fff!important;font-size:2.4rem}.cov .food-stack{display:grid;gap:22px}.cov .food-item{padding:30px;background:var(--wash);border-left:6px solid var(--mustard)}.cov .food-item h3{font-size:1.65rem;margin:.1em 0}.cov .also-row{display:flex;gap:30px;flex-wrap:wrap;margin-top:35px;padding-top:25px;border-top:1px solid #ccd1d7}.cov .mood-list{display:grid;gap:20px}.cov .mood-card{display:grid;grid-template-columns:210px 1fr;align-items:center;border:1px solid #d6dbe0}.cov .mood-label{height:100%;display:grid;place-items:center;padding:28px;background:var(--navy);color:var(--mustard);font-size:.72rem;font-weight:900;letter-spacing:.15em;text-align:center;text-transform:uppercase}.cov .mood-copy{padding:26px 34px}.cov .mood-copy h3{font-size:1.8rem;margin:.1em 0}.cov .outdoors{background:var(--navy);color:#fff}.cov .outdoors h2,.cov .outdoors h3{color:#fff!important}.cov .outdoor-grid{display:grid;grid-template-columns:1.15fr .85fr;grid-template-rows:330px 330px;gap:18px}.cov .outdoor-photo{position:relative;overflow:hidden}.cov .outdoor-photo:first-child{grid-row:1/3}.cov .outdoor-photo .caption{position:absolute;inset:auto 0 0;padding:45px 24px 22px;background:linear-gradient(transparent,rgba(5,19,37,.9))}.cov .outdoor-photo h3{margin:0;font-size:1.8rem}.cov .outdoor-links{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:24px}.cov .outdoor-link{padding:28px;background:#fff;color:var(--ink)}.cov .outdoor-link h3{color:var(--navy)!important}.cov .guide{background:var(--wash)}.cov .guide-mock{position:relative;min-height:520px;background:var(--navy);padding:70px;color:#fff;box-shadow:18px 18px 0 var(--mustard)}.cov .guide-mock .logo{position:static;width:240px;height:240px;margin:0 auto 25px;filter:none}.cov .guide-mock h3{color:#fff!important;text-align:center;font-size:2.4rem}.cov .blog-row{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.cov .blog-card{padding:32px;background:var(--wash);border-top:6px solid var(--mustard)}.cov .blog-card h3{font-size:1.65rem}.cov .closing{padding:58px 0}.cov .closing .logo{width:150px;height:150px;margin-bottom:18px}.cov .closing h2{font-size:clamp(2.2rem,4vw,3.6rem);max-width:850px;margin:.25em auto}.cov .closing p{max-width:650px;margin:0 auto 22px}\n@media(max-width:850px){.cov .intro,.cov .split,.cov .lake-grid,.cov .food-features{grid-template-columns:1fr}.cov .cards{grid-template-columns:1fr 1fr}.cov .hero .logo{left:75%;width:460px;height:460px}.cov .events{grid-template-columns:1fr}.cov .coffee-grid{grid-template-columns:1fr 1fr}.cov .story-shell{padding:30px}.cov .story-photo{position:relative;inset:auto;height:520px}.cov .story-copy{width:90%;margin:-90px auto 0}.cov .story-credit{position:static;margin-top:10px}.cov .blog-row{grid-template-columns:1fr}.cov .outdoor-links{grid-template-columns:1fr}}@media(max-width:560px){.cov section{padding:72px 0}.cov .cards{grid-template-columns:1fr}.cov .hero .logo{display:none}.cov .hero{min-height:650px}.cov .intro-photo,.cov .feature-photo{height:420px}.cov .lake ul{columns:1}.cov .coffee-grid,.cov .outdoor-grid{display:block}.cov .coffee-photo,.cov .outdoor-photo{height:300px;margin-bottom:16px}.cov .story-copy{width:100%;padding:30px;margin-top:-45px}.cov .mood-card{grid-template-columns:1fr}.cov .outdoor-link{padding:24px}}\n</style>\n<main class=\"cov\">\n<header class=\"hero\"><div class=\"hero-copy\"><div class=\"eyebrow\">Rooted In · South King County</div><h1>Living in Covington, Washington</h1><p>Newer neighborhoods, everyday convenience, parks and community events—with Kent, Maple Valley and Black Diamond close enough to borrow whenever the mood strikes.</p></div><img class=\"logo\" src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/19.png\" alt=\"Rooted in Covington logo\"></header>\n<section><div class=\"wrap story-shell\"><div class=\"story-photo\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/Mount_Rainier_as_seen_from_a_Covington_neighborhood.jpg\" alt=\"Mount Rainier beyond a Covington neighborhood\"></div><article class=\"story-copy\"><div class=\"eyebrow\">A Covington story</div><h2>Apparently all my friends figured it out before I did.</h2><p>I lived in Covington years ago, and if I’m being completely honest, two of the biggest selling points were having Costco close by and easy access to Trapper’s Sushi. Priorities.</p><p>Back then, Covington still had a little bit of that “way out there” reputation. It felt more country, a little redneck, and definitely wasn’t the place everyone was rushing to move to.</p><p>Fast forward, and somehow <strong>all</strong> of my best friends now live within about a mile of each other in Covington. And yes, I’m a little jealous.</p><p>The city has grown up right along with the people who moved here. There are more restaurants, shopping, neighborhoods and amenities, but it still has that slightly removed-from-the-city feel that made it appealing in the first place. Covington is booming, and apparently all my friends figured it out before I did.</p><p class=\"lede\">So, what’s all the Covington hype about? Let’s dive in.</p></article><p class=\"story-credit\">Rainier photograph: <a href=\"https://commons.wikimedia.org/w/index.php?curid=90799473\">Yordanpopovbg — Own work, CC BY-SA 4.0</a></p></div></section>\n<section class=\"history\"><div class=\"wrap split\"><div class=\"history-photo\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/kent-area-ca-1920-copy.jpg\" alt=\"Historic South King County mill workers and machinery\"></div><div><div class=\"eyebrow\">The roots</div><h2>Prairie, rail lines and a city of its own.</h2><p>The land around present-day Covington was home to the Stkamish, Smulkamis and Skopamish peoples, whose communities were connected to this region’s waterways and prairies. Later known as Jenkins Prairie, the area became a Northern Pacific Railway stop around the turn of the twentieth century.</p><p>Lumber mills rose near Jenkins and Soos creeks; dairies and berry farms carried the community into its next chapter. Covington grew for decades without city limits of its own before residents chose incorporation, officially forming the city in 1997.</p><p class=\"lede\">Its roots are rural, practical and community-minded—qualities that still show up in the pace of life here.</p><a href=\"https://www.historylink.org/File/10337\">Read Covington’s history →</a></div></div></section>\n<section class=\"ticker\"><div class=\"ticker-track\"><div class=\"ticker-item\"><b>21,496</b><span>Population</span></div><div class=\"ticker-item\"><b>7,377</b><span>Households</span></div><div class=\"ticker-item\"><b>$134,502</b><span>Median household income</span></div><div class=\"ticker-item\"><b>78.9%</b><span>Homeownership rate</span></div><div class=\"ticker-item\"><b>$637,300</b><span>Median home value</span></div><div class=\"ticker-item\"><b>$2,232/mo</b><span>Median rent</span></div><div class=\"ticker-item\"><b>2.87</b><span>Average household size</span></div><div class=\"ticker-item\"><b>23.6%</b><span>Under age 18</span></div><div class=\"ticker-item\"><b>5.93</b><span>Square miles</span></div><div class=\"ticker-item\"><b>3,503</b><span>People per sq. mile</span></div><div class=\"ticker-item\"><b>33.4 min.</b><span>Average commute</span></div><div class=\"ticker-item\"><b>+3.5%</b><span>Growth since 2020</span></div><div class=\"ticker-item\"><b>21,496</b><span>Population</span></div><div class=\"ticker-item\"><b>7,377</b><span>Households</span></div><div class=\"ticker-item\"><b>$134,502</b><span>Median household income</span></div><div class=\"ticker-item\"><b>78.9%</b><span>Homeownership rate</span></div><div class=\"ticker-item\"><b>$637,300</b><span>Median home value</span></div><div class=\"ticker-item\"><b>$2,232/mo</b><span>Median rent</span></div><div class=\"ticker-item\"><b>2.87</b><span>Average household size</span></div><div class=\"ticker-item\"><b>23.6%</b><span>Under age 18</span></div><div class=\"ticker-item\"><b>5.93</b><span>Square miles</span></div><div class=\"ticker-item\"><b>3,503</b><span>People per sq. mile</span></div><div class=\"ticker-item\"><b>33.4 min.</b><span>Average commute</span></div><div class=\"ticker-item\"><b>+3.5%</b><span>Growth since 2020</span></div></div></section>\n<section class=\"rule\"><div class=\"wrap\"><div class=\"eyebrow\">Coffee · before work, after work &amp; on the go</div><h2>Coffee, bagels and absolutely no judgment.</h2><div class=\"coffee-grid\"><article class=\"coffee-photo\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/cafe-elite.jpeg\" alt=\"A sweet drink from Café Elite\"><div class=\"caption\"><h3>Café Elite</h3><p>Is it coffee or dessert? Either way, sign me up.</p><a style=\"color:white\" href=\"https://cafeelite.com/\">Visit Café Elite →</a></div></article><article class=\"coffee-photo\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/image-1.png\" alt=\"Foss Grocery and Deli in Covington\"><div class=\"caption\"><h3>Foss\' Grocery &amp; Espresso</h3><p>Who hasn’t stopped by Foss for a beverage? It gives those small-town vibes you just want to support.</p><a style=\"color:white\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Foss%27+Grocery+%26+Espresso+Covington+WA\">Map it →</a></div></article><article class=\"coffee-photo\" style=\"background:linear-gradient(135deg,#e4a900,#f3cf63)\"><div style=\"height:100%;display:grid;place-items:center;padding:30px;text-align:center;color:#0b1f3a\"><strong style=\"font:italic 2.2rem Georgia,serif\">Bagel first.<br>Coffee second.<br>No regrets.</strong></div><div class=\"caption\"><h3>Bruchelle\'s Bagel Bistro</h3><p>That bagel menu? Drool-worthy. Yum.</p><a style=\"color:white\" href=\"https://bruchelles.com/\">Visit Bruchelle\'s →</a></div></article></div><div class=\"coffee-note\"><strong>Covington definitely understands the quick-coffee lifestyle.</strong> It may not have an abundance of coffeehouses where everyone spends three hours working on a screenplay, but the morning commute is very well covered.</div></div></section>\n<section class=\"feature\"><div class=\"wrap split\"><div class=\"feature-photo\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/Nikkis-Resturant.png\" alt=\"Nikki\'s Restaurant and Lounge in Covington\"></div><div><div class=\"eyebrow\">The local diner</div><h2>Nikki\'s Restaurant &amp; Lounge</h2><p class=\"quote\">This is where you go when drive-through coffee isn\'t enough and you actually want eggs, hash browns, pancakes and a server who keeps the coffee coming.</p><p>Nikki\'s is the classic Covington sit-down breakfast spot and a longtime local gathering place.</p><a class=\"btn\" href=\"https://nikkisrestaurant.com/\">Visit Nikki\'s</a></div></div></section>\n<section><div class=\"wrap\"><div class=\"eyebrow\">Local food favorites</div><h2>Worth putting in the rotation.</h2><div class=\"food-features\"><article class=\"food-lead\"><div class=\"eyebrow\">The longtime favorite</div><h3>Trapper\'s Sushi</h3><p>A familiar South King County sushi favorite with a Covington location—and yes, proximity to Trapper’s once counted as a legitimate housing criterion around here.</p><a class=\"btn\" href=\"https://www.trapperssushi.com/\">Visit Trapper\'s Sushi</a></article><div class=\"food-stack\"><article class=\"food-item\"><h3>Pupusas Locas</h3><p>Salvadoran food, pupusas and dishes you won\'t find at every other restaurant in town.</p><a href=\"https://pupusaslocaswa.com/\">Visit Pupusas Locas →</a></article><article class=\"food-item\"><h3>Iron Grill</h3><p>Build your bowl questionably high and hope your engineering holds up on the walk to the grill.</p><a href=\"https://www.facebook.com/theirongrill/\">Find Iron Grill →</a></article></div></div><div class=\"also-row\"><strong>Also worth a stop:</strong><a href=\"https://www.legendarydoughnuts.com/\">Legendary Doughnuts</a><span>And the burger debate? Covington is perfectly comfortable borrowing Maple Valley’s options.</span></div></div></section>\n<section class=\"rule\"><div class=\"wrap\"><div class=\"eyebrow\">Drinks · pick your mood</div><h2>Local-ish, because city lines are suggestions.</h2><div class=\"mood-list\"><article class=\"mood-card\"><div class=\"mood-label\">Neighborhood dive</div><div class=\"mood-copy\"><h3>Pla-Mor Bar &amp; Grill</h3><p>Casual, unpretentious and the true longtime neighborhood-bar experience.</p><a href=\"https://www.facebook.com/search/top?q=pla-mor%20bar%20%26%20grill\">Find Pla-Mor →</a></div></article><article class=\"mood-card\"><div class=\"mood-label\">Date-night-ish</div><div class=\"mood-copy\"><h3>House &amp; Hazel</h3><p>A modern mercantile, restaurant and bar in Maple Valley when the mood calls for a little more flair.</p><a href=\"https://houseandhazel.com/\">Visit House &amp; Hazel →</a></div></article><article class=\"mood-card\"><div class=\"mood-label\">Brewery run</div><div class=\"mood-copy\"><h3>Big Block Brewery</h3><p>Head toward Black Diamond for a brewpub, restaurant and an easy change of scenery.</p><a href=\"https://www.bigblockbrewery.com/black-diamond\">Visit Big Block Brewery →</a></div></article></div><p class=\"lede\">One of Covington\'s best features is that when you run out of places to go in Covington, Maple Valley and Black Diamond are right there.</p></div></section>\n<section class=\"outdoors\"><div class=\"wrap\"><div class=\"eyebrow\">Covington outdoors</div><h2>Parks, play and pool days.</h2><div class=\"outdoor-grid\"><figure class=\"outdoor-photo\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/covington-park-1.jpeg\" alt=\"Covington Community Park\"><figcaption class=\"caption\"><h3>Covington Community Park</h3><p>Sports, recreation, concerts, movies and some of the city\'s biggest summer activities.</p></figcaption></figure><figure class=\"outdoor-photo\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/covington-park-2-scaled.jpeg\" alt=\"Play area at Covington Community Park\"><figcaption class=\"caption\"><h3>Made for community days</h3></figcaption></figure><figure class=\"outdoor-photo\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/covington-park-3-scaled.jpeg\" alt=\"Recreation at Covington Community Park\"><figcaption class=\"caption\"><h3>Room to move</h3></figcaption></figure></div><div class=\"outdoor-links\"><article class=\"outdoor-link\"><div class=\"eyebrow\">Trail time</div><h3>Jenkins Creek Park</h3><p>A wooded local option for trails, green space and a quieter reset close to home.</p><a href=\"https://www.covingtonwa.gov/city_departments/parks/jenkinscreekpark.php\">Explore Jenkins Creek Park →</a></article><article class=\"outdoor-link\"><div class=\"eyebrow\">Pool days</div><h3>Covington Aquatic Center</h3><p>Swim lessons, open swim and birthday parties—the kind of practical family amenity that earns repeat visits.</p><a href=\"https://www.covingtonwa.gov/cac\">Visit the Aquatic Center →</a></article></div></div></section>\n<section><div class=\"wrap\"><div class=\"eyebrow\">Things to do &amp; annual events</div><h2>Somebody is usually planning something.</h2><p class=\"lede\">Covington may not have 47 places to go on a Saturday night, but the community calendar stays busy.</p><div class=\"events\"><article class=\"event\"><h3><a href=\"https://www.covingtonwa.gov/covingtondays/\">Covington Days</a></h3><p>One of the city\'s biggest annual traditions, with a parade, live entertainment, food, vendors, kids\' activities and community events.</p></article><article class=\"event\"><h3><a href=\"https://www.covingtonwa.gov/events/\">KidsFest</a></h3><p>A free annual event at Covington Community Park focused completely on kids, with activities, entertainment and community organizations.</p></article><article class=\"event\"><h3><a href=\"https://www.covingtonwa.gov/events/\">Summer concerts &amp; outdoor movies</a></h3><p>Outdoor concerts and Movies Under the Stars take over Covington Community Park during summer. Check the city calendar for current dates.</p></article><article class=\"event\"><h3><a href=\"https://www.covingtonchamber.org/\">Covington Makers Market</a></h3><p>Local makers, artists, creators, bakers, crafters and businesses, brought together through the Covington Chamber of Commerce and the City.</p></article></div></div></section>\n<section class=\"lake\"><div class=\"wrap lake-grid\"><div><div class=\"eyebrow\">What\'s coming to Covington</div><h2>LakePointe Urban Village</h2><p class=\"quote\">If you\'ve driven Highway 18 through Covington and wondered, “Are they ever going to do something with that giant gravel pit?”—the answer is yes. Or at least, that\'s the plan.</p><p><a href=\"https://www.covingtonwa.gov/lakepointe/index.php\"><strong>LakePointe Urban Village</strong></a> is the massive mixed-use development planned at Covington\'s northern gateway. The approximately 214-acre master-plan area is envisioned to include:</p><ul><li>Residential neighborhoods</li><li>Commercial and mixed-use development</li><li>Shopping and restaurants</li><li>Public gathering spaces</li><li>Parks and trails</li><li>A central lake/pond feature</li><li>Office space</li><li>Entertainment uses</li></ul><p>The water feature is envisioned as a major public amenity surrounded by places where people can gather, walk, dine, shop and live.</p></div><aside class=\"lake-map\"><div class=\"eyebrow\">Official planning materials</div><strong>Master development plan map &amp; project renderings</strong><p>See the City of Covington\'s official project materials for the detailed plan showing the central water feature, residential and mixed-use areas, gathering spaces, parks, trails and circulation.</p><a class=\"btn\" href=\"https://www.covingtonwa.gov/lakepointe/index.php\">View the official LakePointe plan</a><p class=\"small\">Conceptual plans and renderings only. Final development may differ; buildings, roads, restaurants, trails and amenities are not completed or guaranteed.</p><div class=\"stats\"><div class=\"stat\"><b>~1,750</b>residential units referenced in planning documents</div><div class=\"stat\"><b>~1.3M sq. ft.</b>commercial/retail development referenced in planning documents</div></div><p>Plans have historically included entertainment uses and a movie theater concept—but there is no announced theater operator or confirmed opening date. So don\'t start standing in line for movie tickets just yet.</p></aside></div><div class=\"wrap\"><p class=\"lede\">But if LakePointe ultimately comes together anywhere close to the vision, it could completely change the dining, shopping and entertainment side of Covington.</p></div></section>\n<section><div class=\"wrap split\"><div><div class=\"eyebrow\">Shopping &amp; everyday convenience</div><h2>Life is close to home.</h2><p>One of Covington\'s biggest practical advantages is that you don\'t have to go far for everyday life. Major grocery stores, restaurants, services, medical care and plenty of everyday shopping are right in town.</p><p class=\"quote\">Maybe Costco isn\'t technically a community amenity, but tell that to anyone who lives five minutes from one.</p></div><div class=\"intro-photo\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/Costco_Covington_big.jpg\" alt=\"Costco in Covington, Washington\"></div></div></section>\n<section class=\"guide\"><div class=\"wrap split\"><div><div class=\"eyebrow\">Want the whole Covington cheat sheet?</div><h2>The practical guide is back.</h2><p>Roads, routines, neighborhoods and the details that matter when you\'re comparing Covington with the rest of South King County—without pretending every place is perfect for every person.</p><a class=\"btn\" href=\"https://violet-wren-104886.hostingersite.com/living-in-covington-wa-local-guide/\">Read the complete Covington guide</a></div><div class=\"guide-mock\"><img class=\"logo\" src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/19.png\" alt=\"Rooted in Covington logo\"><div class=\"eyebrow\">Rooted In · Local Guide</div><h3>Living in Covington, Washington</h3></div></div></section>\n<section class=\"rule\"><div class=\"wrap\"><div class=\"eyebrow\">Living in Covington</div><h2>Why buyers put it on the list.</h2><div class=\"split\"><div><p>Covington tends to have newer housing than many established parts of Renton and Kent, with subdivisions, cul-de-sacs, townhomes and homes built primarily during the last several decades.</p><p>It appeals to people looking for suburban neighborhoods, parks, shopping and convenient access to Highway 18 while remaining close to Maple Valley, Kent and Black Diamond.</p></div><div><p class=\"lede\">The useful question isn\'t whether Covington is “affordable.” It\'s what your budget buys here compared with Renton, Kent, Maple Valley and the rest of South King County.</p><p>That comparison—and how the location fits your actual weekly routine—is where local guidance becomes useful.</p></div></div></div></section>\n<section><div class=\"wrap\"><div class=\"eyebrow\">Thinking about making Covington home?</div><h2>Keep reading before you start scrolling listings.</h2><div class=\"blog-row\"><article class=\"blog-card\"><h3>How to Buy a Home in Renton, WA</h3><p>The location is different; the practical buying process and South King County context still travel well.</p><a href=\"https://violet-wren-104886.hostingersite.com/how-to-buy-a-home-in-renton-wa/\">Read the article →</a></article><article class=\"blog-card\"><h3>Moving to Renton: A Practical Guide</h3><p>Timelines, planning and the unglamorous-but-useful details behind a smoother move.</p><a href=\"https://violet-wren-104886.hostingersite.com/moving-to-renton-wa-guide/\">Read the moving guide →</a></article><article class=\"blog-card\"><h3>Best Renton Neighborhoods for Every Lifestyle</h3><p>A helpful comparison when Covington, Renton and nearby South King County communities are all on the table.</p><a href=\"https://violet-wren-104886.hostingersite.com/best-renton-neighborhoods-for-every-lifestyle-a-locals-honest-guide/\">Compare neighborhoods →</a></article></div></div></section>\n<section class=\"closing\"><div class=\"wrap\"><img class=\"logo\" src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/19.png\" alt=\"Rooted in Covington logo\"><div class=\"eyebrow\">Thinking about Covington?</div><h2>Suburban convenience, growing families, and everything you need close to home.</h2><p>Whether you\'re moving in, moving across town or comparing South King County communities, Tanya can help you sort through the options without the pressure.</p><a class=\"btn\" href=\"/contact/\">Ask Tanya about Covington</a></div></section>\n</main>\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"tanya-barrans\",\"tagName\":\"footer\"} /-->', 'Page: Covington', '', 'inherit', 'closed', 'closed', '', '90239-revision-v1', '', '', '2026-08-26 19:31:01', '2026-08-26 19:31:01', '', 90239, 'https://violet-wren-104886.hostingersite.com/?p=90408', 0, 'revision', '', 0),
(90409, 2, '2026-08-26 19:55:04', '2026-08-26 19:55:04', '<!-- wp:paragraph -->\n<p>Covington is one of those places that is incredibly convenient to live in, but maybe not where you are planning Saturday night\'s entertainment. You can get groceries, hit Costco, grab sushi, go to the gym, buy a dishwasher, pick up donuts and somehow still be home five minutes later.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>But want a movie theater, a mall, a bowling alley or a bigger night out? You are probably leaving Covington.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Honestly, that is the tradeoff—and it is exactly why some people love living here.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/covington-rainier-scaled.jpg\" alt=\"Mount Rainier view near Covington, Washington\"/><figcaption class=\"wp-element-caption\">Mount Rainier view near Covington, Washington</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">The short version</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Covington makes everyday life ridiculously easy. The commercial core gives you Costco, Safeway, Fred Meyer, Home Depot, gyms, medical care, coffee, casual restaurants and most of the errands you repeat every week—all packed into a surprisingly small area.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>What it does not give you is a cute, walkable Main Street or much in the way of nightlife and entertainment. You will still drive most places, and Kent-Kangley traffic deserves a real conversation.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">The pros of living in Covington</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Almost everything is five minutes away</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>This was probably my favorite thing about living here. Costco run? Five minutes. Sushi? Five minutes. Forgot something at the grocery store? Five minutes. Home Depot because your “quick little house project” inevitably requires three more trips? Still five minutes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><p><strong>The Target problem:</strong> I genuinely do not understand how Covington has managed to give us basically every store we need except Target. It is my one formal complaint.</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">It is a serious everyday-services hub</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Covington is much more built up than people who have not visited in years may remember. Groceries, restaurants, fitness, home improvement, medical care and everyday services are concentrated around the commercial core. You do not have to leave town for every appointment or errand, and that convenience adds up quickly.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">You are close to more than the shopping centers suggest</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>For a suburban city with a busy commercial center, Covington is also a useful launch point for getting outside. Covington Community Park and Jenkins Creek give you local options, while Lake Wilderness, Black Diamond and the routes east toward North Bend, Snoqualmie Pass and Crystal Mountain make bigger outdoor days feel possible.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I put “quick” in quotation marks when we talk about mountain drives because this is Western Washington. Weather, traffic and the day of the week still get a vote. But you are starting on the right side of the region instead of fighting your way out of Seattle first.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">The cons of living in Covington</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Dinner? Yes. Dinner and a movie? Now we are driving.</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Covington has plenty of casual food, coffee and treat options. What it does not have is much destination entertainment. For movies, bowling, a mall day or a bigger night out, you are usually heading toward Auburn, Kent, Tukwila/Southcenter, Bellevue or Seattle.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>That is not necessarily a dealbreaker. A lot of people would rather have easy weekday errands and drive for occasional entertainment. But it is worth being honest about what kind of lifestyle you want.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">It is not especially walkable</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Covington does have a downtown and commercial core; it just is not a traditional Main Street downtown. The city is working toward a more connected town-center feel, but today most people still drive between neighborhoods, shops, parks and services. Sidewalks and street character can also change quickly from one pocket to the next.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Traffic can erase the “five-minute” magic</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>SR 18 and Kent-Kangley Road shape daily life here. School traffic, commute hours and a backup near a major intersection can change a short trip fast. If you are considering a home, test the route you will actually drive at 8 a.m. and again around 5 p.m. Do not rely on a Sunday-afternoon map estimate.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">The housing changes faster than you might expect</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Covington is not one single housing experience. You will find established subdivisions, newer construction, townhomes and streets with a more semi-rural feel. Lot size, sidewalks, road width, tree coverage, HOA rules and access to services can be different within a short drive.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>This is also why Covington and Maple Valley are not interchangeable, even though buyers often compare them. The day-to-day rhythm, shopping access, commute route and neighborhood feel can be noticeably different. I would compare specific homes and specific routes—not just city names.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">What I would look at before buying here</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item --><li>Drive your real weekday commute during the hours you will actually use it.</li><!-- /wp:list-item -->\n<!-- wp:list-item --><li>Check the street for sidewalks, lighting, parking and the road feel you want.</li><!-- /wp:list-item -->\n<!-- wp:list-item --><li>Look at drainage, slope, retaining walls and tree coverage on the lot.</li><!-- /wp:list-item -->\n<!-- wp:list-item --><li>Confirm utilities, permits and HOA rules for that specific property.</li><!-- /wp:list-item -->\n<!-- wp:list-item --><li>Notice what is planned or being built around the neighborhood.</li><!-- /wp:list-item -->\n<!-- wp:list-item --><li>Time the trip to groceries, schools, medical care and the errands you repeat most.</li><!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><p><strong>Tanya\'s local take:</strong> In Covington, the house and the route around it are one complete package. A home can feel tucked away and still be wonderfully convenient—or add more time to every trip than the map suggests.</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">So, is Covington worth living in?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If you want walkable nightlife and entertainment outside your front door, Covington probably is not your place. If you want a suburban home where almost every annoying errand is ridiculously convenient, you can get outside without crossing the entire metro area, and bigger-city amenities are still within striking distance, Covington makes a whole lot of sense.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I would live here again for the convenience alone. Just know the trade: Covington is very good at everyday life. For the bigger fun stuff, you are getting in the car.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Useful local links</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item --><li><a href=\"https://www.covingtonwa.gov/parks\">City of Covington Parks and Recreation</a></li><!-- /wp:list-item -->\n<!-- wp:list-item --><li><a href=\"https://cms2.revize.com/revize/cityofcovington/Jenkins%20Creek_Report_10.4.2024_LowRes_SPREADS.pdf\">Jenkins Creek Trail planning</a></li><!-- /wp:list-item -->\n<!-- wp:list-item --><li><a href=\"/covington/\">Explore the full Covington neighborhood guide</a></li><!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":2} -->\n<h2 class=\"wp-block-heading\">Thinking about making a move?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If you are comparing homes in Covington, I can help you sort through the location, property and lifestyle details without the pressure. The goal is not simply to find a house. It is to help you love where you live.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"backgroundColor\":\"palette-color-1\"} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-palette-color-1-background-color has-background wp-element-button\" href=\"/contact/\">Ask Tanya about Covington</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->', 'Living in Covington, WA: The Real Pros & Cons From a Local', '', 'inherit', 'closed', 'closed', '', '90333-revision-v1', '', '', '2026-08-26 19:55:04', '2026-08-26 19:55:04', '', 90333, 'https://violet-wren-104886.hostingersite.com/?p=90409', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(90410, 2, '2026-08-26 20:03:44', '2026-08-26 20:03:44', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:html -->\n<style id=\"tb-blog-template-styles\">\n/* Shared Journal article template - applies to every post using Single Posts */\n.tb-article-page {\n  background: #fbf8f2 !important;\n  background-image: none !important;\n  color: #25364a;\n  overflow: hidden;\n}\n.tb-article-header {\n  width: min(860px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: clamp(64px, 8vw, 112px) 0 44px;\n  text-align: center;\n}\n.tb-article-title {\n  max-width: 820px;\n  margin-left: auto !important;\n  margin-right: auto !important;\n  line-height: 1.04 !important;\n}\n.tb-article-dek {\n  max-width: 680px;\n  margin: 22px auto 0 !important;\n  font-size: clamp(18px, 2vw, 23px);\n  line-height: 1.55;\n}\n.tb-article-hero {\n  width: 100%;\n  max-width: none !important;\n  padding: 0 24px clamp(48px, 6vw, 80px);\n  background: #fbf8f2 !important;\n  background-image: none !important;\n  box-sizing: border-box;\n}\n.tb-article-hero:not(:has(.wp-block-post-featured-image img)) { display: none !important; } .tb-article-hero .wp-block-post-featured-image {\n  width: min(1040px, 100%);\n  margin: 0 auto !important;\n}\n.tb-article-hero .wp-block-post-featured-image img {\n  display: block;\n  width: 100%;\n  height: clamp(360px, 52vw, 620px);\n  object-fit: cover;\n  border-radius: 18px;\n  box-shadow: 0 18px 52px rgba(52,76,106,.13);\n}\n.tb-article-body {\n  width: min(720px, calc(100% - 48px));\n  margin: 0 auto;\n  padding-bottom: clamp(72px, 9vw, 120px);\n  font-size: 18px;\n  line-height: 1.78;\n}\n.tb-article-body h2 {\n  margin-top: 2.4em;\n  color: #344c6a;\n}\n.tb-article-body .alignwide {\n  width: min(1040px, calc(100vw - 48px));\n  max-width: none;\n  margin-left: 50% !important;\n  transform: translateX(-50%);\n}\n.tb-article-body figure img {\n  border-radius: 14px;\n}\n.tb-article-explore {\n  padding: clamp(64px, 8vw, 96px) 24px !important;\n  background: #344c6a !important;\n}\n.tb-article-explore .tb-page-shell {\n  width: min(940px, 100%);\n  margin: 0 auto;\n}\n.tb-article-explore__links {\n  max-width: 820px;\n  margin: 34px auto 0;\n}\n.tb-newsletter-feature {\n  width: min(1040px, calc(100% - 48px)) !important;\n  max-width: 1040px !important;\n  min-height: 420px;\n  margin: clamp(72px, 9vw, 112px) auto !important;\n  display: grid !important;\n  grid-template-columns: minmax(300px, .9fr) minmax(420px, 1.25fr);\n  overflow: hidden;\n  border-radius: 18px;\n  box-shadow: 0 18px 55px rgba(52,76,106,.12);\n}\n.tb-newsletter-feature__image {\n  min-height: 420px;\n  background-size: cover !important;\n  background-position: center !important;\n}\n.tb-newsletter-feature__content {\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  padding: clamp(44px, 6vw, 72px) !important;\n}\n.tb-newsletter-fields {\n  display: grid !important;\n  grid-template-columns: 1fr 1fr auto;\n  gap: 12px;\n}\n.tb-article-author {\n  padding: clamp(72px, 9vw, 112px) 24px !important;\n  background: #f1e8dc !important;\n}\n.tb-article-author__inner {\n  width: min(1000px, 100%);\n  margin: 0 auto;\n  display: grid !important;\n  grid-template-columns: minmax(280px, 380px) 1fr;\n  gap: clamp(42px, 7vw, 82px);\n  align-items: center;\n}\n.tb-article-author__inner > img {\n  width: 100%;\n  height: 500px;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 16px;\n  box-shadow: 0 16px 42px rgba(52,76,106,.14);\n}\n.tb-article-author h2 {\n  max-width: 560px;\n  font-size: clamp(36px, 4vw, 54px);\n  line-height: 1.05;\n}\n.tb-article-comments {\n  width: min(820px, calc(100% - 48px));\n  margin: clamp(64px, 8vw, 96px) auto !important;\n  padding: clamp(42px, 6vw, 68px) !important;\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.14);\n  border-radius: 18px;\n  box-shadow: 0 14px 42px rgba(52,76,106,.08);\n  box-sizing: border-box;\n}\n.tb-article-comments textarea,\n.tb-article-comments input:not([type=\"submit\"]) {\n  width: 100%;\n  box-sizing: border-box;\n}\n.tb-article-navigation {\n  width: min(1040px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: 0 0 clamp(72px, 8vw, 104px);\n}\n@media (max-width: 760px) {\n  .tb-article-header { width: min(100% - 32px, 860px); padding-top: 48px; }\n  .tb-article-hero { padding-left: 16px; padding-right: 16px; }\n  .tb-article-hero .wp-block-post-featured-image img { height: 58vw; min-height: 260px; border-radius: 12px; }\n  .tb-article-body { width: min(100% - 36px, 720px); font-size: 17px; }\n  .tb-article-body .alignwide { width: calc(100vw - 32px); }\n  .tb-newsletter-feature { width: calc(100% - 32px) !important; grid-template-columns: 1fr; }\n  .tb-newsletter-feature__image { min-height: 280px; }\n  .tb-newsletter-fields { grid-template-columns: 1fr !important; }\n  .tb-article-author__inner { grid-template-columns: 1fr !important; }\n  .tb-article-author__inner > img { height: 420px; }\n  .tb-article-comments, .tb-article-navigation { width: calc(100% - 32px); }\n}\n\n/* Editorial depth refinement */\n.tb-article-page {\n  background: linear-gradient(180deg, #e8eef2 0, #fbf8f2 720px) !important;\n}\n.tb-article-header {\n  position: relative;\n  z-index: 1;\n  width: min(1040px, calc(100% - 48px));\n  margin: clamp(46px, 6vw, 78px) auto 0;\n  padding: clamp(48px, 6vw, 76px);\n  text-align: left;\n  background: rgba(255,255,255,.96);\n  border: 1px solid rgba(52,76,106,.12);\n  border-radius: 22px;\n  box-shadow: 0 22px 60px rgba(52,76,106,.11);\n  box-sizing: border-box;\n}\n.tb-article-title {\n  max-width: 850px;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n.tb-article-dek {\n  position: relative;\n  max-width: 800px;\n  margin: 36px 0 26px !important;\n  padding: 58px 34px 30px;\n  background: #dfeaed;\n  border-left: 6px solid #d9a21b;\n  border-radius: 12px;\n  box-sizing: border-box;\n  font-size: clamp(17px, 1.7vw, 21px);\n}\n.tb-article-dek::before {\n  content: \"At a glance\";\n  position: absolute;\n  top: 25px;\n  left: 34px;\n  color: #344c6a;\n  font-family: inherit;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: .15em;\n  text-transform: uppercase;\n}\n.tb-article-meta {\n  justify-content: flex-start !important;\n}\n.tb-article-hero {\n  position: relative;\n  z-index: 2;\n  margin-top: -26px;\n}\n.tb-article-body {\n  width: min(860px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: clamp(48px, 6vw, 72px);\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.1);\n  border-radius: 20px;\n  box-shadow: 0 18px 52px rgba(52,76,106,.08);\n  box-sizing: border-box;\n}\n.tb-article-comments {\n  margin-top: 34px !important;\n  margin-bottom: clamp(64px, 8vw, 96px) !important;\n}\n.tb-newsletter-feature {\n  margin-top: 0 !important;\n}\n@media (max-width: 760px) {\n  .tb-article-header {\n    width: calc(100% - 28px);\n    margin-top: 22px;\n    padding: 34px 24px;\n    border-radius: 15px;\n  }\n  .tb-article-dek {\n    padding: 54px 22px 24px;\n  }\n  .tb-article-dek::before {\n    left: 22px;\n  }\n  .tb-article-hero {\n    margin-top: -14px;\n  }\n  .tb-article-body {\n    width: calc(100% - 28px);\n    padding: 36px 22px;\n    border-radius: 15px;\n  }\n}\n\n/* Blog realtor rail and Tanya-color summary */\n.tb-article-dek {\n  background: #f7f1e7 !important;\n  border-left-color: #c77798 !important;\n  color: #344c6a;\n  box-shadow: inset 0 0 0 1px rgba(52,76,106,.08);\n}\n.tb-article-dek::before { color: #344c6a; }\n.tb-blog-layout {\n  width: min(1120px, calc(100% - 48px));\n  margin: 0 auto;\n  display: grid !important;\n  grid-template-columns: minmax(0, 760px) 320px;\n  gap: 42px;\n  align-items: start;\n}\n.tb-blog-main .tb-article-body,\n.tb-blog-main .tb-article-comments {\n  width: 100%;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n.tb-blog-main .tb-article-comments { margin-top: 34px !important; }\n.tb-blog-rail {\n  position: sticky;\n  top: 48px;\n  display: grid;\n  gap: 26px;\n}\n.tb-blog-rail__intro,\n.tb-blog-listings {\n  padding: 26px;\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.12);\n  border-radius: 18px;\n  box-shadow: 0 14px 38px rgba(52,76,106,.08);\n}\n.tb-blog-rail__intro > img {\n  display: block;\n  width: 190px;\n  height: 190px;\n  margin: -4px auto 22px;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 50% 50% 46% 54%;\n  box-shadow: 12px 12px 0 #f2dce4;\n}\n.tb-blog-rail__eyebrow {\n  margin: 0 0 9px;\n  color: #d093aa;\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: .14em;\n  text-transform: uppercase;\n}\n.tb-blog-rail h2 {\n  margin: 0 0 12px;\n  color: #344c6a;\n  font-size: 30px;\n  line-height: 1.05;\n}\n.tb-blog-rail p { line-height: 1.55; }\n.tb-blog-rail__button {\n  display: inline-block;\n  margin-top: 8px;\n  padding: 12px 16px;\n  color: #fff !important;\n  background: #344c6a;\n  border-radius: 4px;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: .08em;\n  text-decoration: none;\n  text-transform: uppercase;\n}\n.tb-listing-grid { display: grid; gap: 18px; margin-top: 20px; }\n.tb-listing-card {\n  display: block;\n  overflow: hidden;\n  color: #25364a !important;\n  background: #fbf8f2;\n  border: 1px solid rgba(52,76,106,.11);\n  border-radius: 12px;\n  text-decoration: none !important;\n  transition: transform .2s ease, box-shadow .2s ease;\n}\n.tb-listing-card:hover {\n  transform: translateY(-3px);\n  box-shadow: 0 12px 26px rgba(52,76,106,.12);\n}\n.tb-listing-card__image {\n  position: relative;\n  display: block;\n  height: 150px;\n}\n.tb-listing-card__image img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n.tb-listing-card__image > span {\n  position: absolute;\n  top: 10px;\n  left: 10px;\n  padding: 6px 9px;\n  color: #344c6a;\n  background: #f7f1e7;\n  border-radius: 999px;\n  font-size: 10px;\n  font-weight: 800;\n  letter-spacing: .1em;\n  text-transform: uppercase;\n}\n.tb-listing-card__body { display: grid; gap: 3px; padding: 15px; }\n.tb-listing-card__body strong { font-family: inherit; font-size: 15px; }\n.tb-listing-card__body b { margin-top: 6px; color: #344c6a; font-size: 18px; }\n.tb-listing-card__body small { color: #6b7580; font-size: 12px; }\n.tb-listing-fallback {\n  display: none;\n  margin-top: 18px;\n  padding: 20px;\n  background: #f7f1e7;\n  border-radius: 12px;\n}\n.tb-listing-grid:not(:has(.tb-listing-card)) + .tb-listing-fallback { display: block; }\n.tb-listing-fallback h3 { margin-top: 0; color: #344c6a; }\n.tb-listing-fallback a,\n.tb-blog-rail__text-link {\n  display: block;\n  margin-top: 12px;\n  color: #344c6a !important;\n  font-weight: 700;\n}\n.tb-blog-rail__text-link { font-size: 13px; }\n@media (max-width: 1020px) {\n  .tb-blog-layout { grid-template-columns: 1fr; }\n  .tb-blog-rail { position: static; grid-template-columns: .8fr 1.2fr; }\n  .tb-listing-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }\n}\n@media (max-width: 700px) {\n  .tb-blog-layout { width: calc(100% - 28px); }\n  .tb-blog-rail { grid-template-columns: 1fr; }\n  .tb-listing-grid { grid-template-columns: 1fr; }\n}\n.tb-article-page{display:grid;grid-template-columns:minmax(0,760px) 320px;column-gap:42px;justify-content:center;} .tb-article-header{grid-column:1 / -1;grid-row:1;} .tb-article-hero{grid-column:1 / -1;grid-row:2;} .tb-article-body{grid-column:1;grid-row:3;width:100%;margin-left:0;margin-right:0;} .tb-blog-rail{grid-column:2;grid-row:3 / span 2;} .tb-article-comments{grid-column:1;grid-row:4;width:100%;margin-left:0!important;margin-right:0!important;} .tb-newsletter-feature{grid-column:1 / -1;grid-row:5;} .tb-article-navigation{grid-column:1 / -1;grid-row:6;} @media(max-width:1020px){.tb-article-page{display:block}.tb-blog-rail{position:static;width:min(860px,calc(100% - 28px));margin:34px auto 72px}.tb-article-body,.tb-article-comments{width:min(860px,calc(100% - 28px));margin-left:auto!important;margin-right:auto!important}.tb-blog-rail{display:grid;grid-template-columns:.8fr 1.2fr}.tb-listing-grid{grid-template-columns:repeat(2,minmax(0,1fr))}} @media(max-width:700px){.tb-blog-rail{grid-template-columns:1fr}.tb-listing-grid{grid-template-columns:1fr}}\n.tb-blog-rail{align-self:start;height:max-content;}\n\n/* Neighborhood Guides automatically use the local-guide layout */\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-hero,\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-blog-rail {\n  display: none !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-page {\n  display: block !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-header {\n  padding-bottom: 30px !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body {\n  width: min(900px, calc(100% - 48px)) !important;\n  margin: 28px auto 0 !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-comments {\n  width: min(900px, calc(100% - 48px)) !important;\n  margin-left: auto !important;\n  margin-right: auto !important;\n}\n@media (max-width: 760px) {\n  body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body,\n  body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-comments {\n    width: calc(100% - 28px) !important;\n  }\n}\n@media (max-width: 760px) { body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body { margin-top: 18px !important; } }\n</style>\n<!-- /wp:html --> <!-- wp:group {\"tagName\":\"main\",\"className\":\"tb-article-page\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group tb-article-page\">\n\n	<!-- wp:group {\"className\":\"tb-article-header\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"920px\"}} -->\n	<header class=\"wp-block-group tb-article-header\">\n		<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-journal-label\"} /-->\n		<!-- wp:post-title {\"level\":1,\"className\":\"tb-article-title\",\"fontSize\":\"x-large\"} /-->\n		<!-- wp:post-excerpt {\"moreText\":\"\",\"excerptLength\":32,\"className\":\"tb-article-dek\"} /-->\n		<!-- wp:group {\"className\":\"tb-article-meta\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"center\"}} -->\n		<div class=\"wp-block-group tb-article-meta\">\n			<!-- wp:paragraph --><p>From Tanya Barrans</p><!-- /wp:paragraph -->\n			<!-- wp:post-date /-->\n		</div>\n		<!-- /wp:group -->\n	</header>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-hero\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-article-hero\">\n		<!-- wp:post-featured-image {\"aspectRatio\":\"16/9\",\"sizeSlug\":\"full\"} /-->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-body\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\",\"wideSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-article-body\">\n		<!-- wp:post-content {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\",\"wideSize\":\"1200px\"}} /-->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-comments\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\"}} -->\n<div class=\"wp-block-group tb-article-comments\">\n<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Join the conversation</h2><!-- /wp:heading -->\n<!-- wp:paragraph --><p>Have a tip, a question, or a story of your own? I’d love to hear it.</p><!-- /wp:paragraph -->\n<!-- wp:comments -->\n<div class=\"wp-block-comments\">\n<!-- wp:comments-title {\"showPostTitle\":false} /-->\n<!-- wp:comment-template -->\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} --><div class=\"wp-block-group\"><!-- wp:avatar {\"size\":48} /--><!-- wp:group --><div class=\"wp-block-group\"><!-- wp:comment-author-name /--><!-- wp:comment-date /--></div><!-- /wp:group --></div><!-- /wp:group -->\n<!-- wp:comment-content /-->\n<!-- wp:comment-reply-link /-->\n<!-- /wp:comment-template -->\n<!-- wp:post-comments-form /-->\n</div>\n<!-- /wp:comments -->\n</div>\n<!-- /wp:group --> <!-- wp:html -->\n<aside class=\"tb-blog-rail\" aria-label=\"About Tanya and current listings\">\n  <section class=\"tb-blog-rail__intro\">\n    <img src=\"/wp-content/uploads/2026/07/about-main.jpg\" alt=\"Tanya Barrans, Puget Sound real estate broker\" loading=\"lazy\">\n    <p class=\"tb-blog-rail__eyebrow\">Your local real estate resource</p>\n    <h2>Hi, I’m Tanya.</h2>\n    <p>I help buyers and sellers make thoughtful moves across Renton and the South Sound—with honest guidance and a little more personality.</p>\n    <a class=\"tb-blog-rail__button\" href=\"/contact/\">Ask Tanya a question</a>\n  </section>\n  <section class=\"tb-blog-listings\">\n    <p class=\"tb-blog-rail__eyebrow\">Currently listed by Tanya</p>\n    <h2>Homes worth a look</h2>\n    <div class=\"tb-listing-grid\">\n      <a class=\"tb-listing-card\" href=\"https://tanyab.johnlscott.com/listing/wa/olympia/5246-yearley-drive-ne-/21476453\" target=\"_blank\" rel=\"noopener\">\n        <span class=\"tb-listing-card__image\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/253/429/2534297.jpg\" alt=\"5246 Yearley Drive NE in Olympia\" loading=\"lazy\"><span>Active</span></span>\n        <span class=\"tb-listing-card__body\"><strong>5246 Yearley Drive NE</strong><small>Olympia, WA</small><b>$389,999</b><small>2 beds · 1.75 baths · 972 sq ft</small></span>\n      </a>\n      <a class=\"tb-listing-card\" href=\"https://tanyab.johnlscott.com/listing/wa/puyallup/18026-75th-avenue-e-/21497093\" target=\"_blank\" rel=\"noopener\">\n        <span class=\"tb-listing-card__image\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/254/658/2546584.jpg\" alt=\"18026 75th Avenue E in Puyallup\" loading=\"lazy\"><span>Active</span></span>\n        <span class=\"tb-listing-card__body\"><strong>18026 75th Avenue E</strong><small>Puyallup, WA</small><b>$545,000</b><small>4 beds · 2.5 baths · 2,201 sq ft</small></span>\n      </a>\n    </div>\n    <div class=\"tb-listing-fallback\">\n      <h3>Nothing active right now—but the search doesn’t stop here.</h3>\n      <p>Browse homes on my John L. Scott site or tell me what you’re hoping to find.</p>\n      <a href=\"https://tanyab.johnlscott.com/search\" target=\"_blank\" rel=\"noopener\">Explore available homes</a>\n      <a href=\"/contact/\">Tell me what you’re looking for</a>\n    </div>\n    <a class=\"tb-blog-rail__text-link\" href=\"https://tanyab.johnlscott.com\" target=\"_blank\" rel=\"noopener\">See all listings on John L. Scott →</a>\n  </section>\n</aside>\n<!-- /wp:html --> <!-- wp:group {\"align\":\"full\",\"className\":\"tb-newsletter-feature\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/newsletter\",\"name\":\"Newsletter Signup\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-newsletter-feature has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg)\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__content tb-reveal\">\n		<!-- wp:paragraph {\"className\":\"tb-script-accent\"} -->\n		<p class=\"tb-script-accent\">Let’s stay in touch</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"x-large\"} -->\n		<h2 class=\"wp-block-heading has-x-large-font-size\">Notes worth opening.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Useful home ideas, local stories, and honest real estate guidance—delivered with no pressure and no polished filler.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:html -->\n		<form class=\"tb-newsletter-form\" novalidate>\n			<div class=\"tb-newsletter-fields\">\n				<label class=\"tb-sr-only\" for=\"tb-nl-name\">First name</label>\n				<input type=\"text\" id=\"tb-nl-name\" name=\"name\" class=\"tb-newsletter-input\" placeholder=\"First name\" autocomplete=\"given-name\" />\n\n				<label class=\"tb-sr-only\" for=\"tb-nl-email\">Email address</label>\n				<input type=\"email\" id=\"tb-nl-email\" name=\"email\" class=\"tb-newsletter-input\" placeholder=\"Email address\" autocomplete=\"email\" required />\n\n				<div class=\"tb-newsletter-hp\" aria-hidden=\"true\">\n					<label for=\"tb-nl-website\">Website</label>\n					<input type=\"text\" id=\"tb-nl-website\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" />\n				</div>\n\n				<button type=\"submit\" class=\"tb-newsletter-submit\">Subscribe</button>\n			</div>\n			<p class=\"tb-newsletter-status\" role=\"status\" aria-live=\"polite\"></p>\n		</form>\n		<!-- /wp:html -->\n\n		<!-- wp:paragraph {\"className\":\"tb-newsletter-feature__privacy\"} -->\n		<p class=\"tb-newsletter-feature__privacy\">No spam. Unsubscribe whenever you like.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-navigation\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<nav class=\"wp-block-group tb-article-navigation\" aria-label=\"Article navigation\">\n		<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\"}} -->\n		<div class=\"wp-block-group\">\n			<!-- wp:post-navigation-link {\"type\":\"previous\",\"label\":\"Previous story\",\"showTitle\":true,\"linkLabel\":true} /-->\n			<!-- wp:post-navigation-link {\"type\":\"next\",\"label\":\"Next story\",\"showTitle\":true,\"linkLabel\":true} /-->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-journal-back-link\"} --><p class=\"has-text-align-center tb-journal-back-link\"><a href=\"/blog/\">Back to the Journal</a></p><!-- /wp:paragraph -->\n	</nav>\n	<!-- /wp:group -->\n\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n', 'Blog Posts', 'Displays a single post on your website unless a custom template has been applied to that post or a dedicated template exists.', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-08-26 20:03:44', '2026-08-26 20:03:44', '', 99, 'https://violet-wren-104886.hostingersite.com/?p=90410', 0, 'revision', '', 0),
(90411, 2, '2026-08-26 20:11:09', '0000-00-00 00:00:00', '', 'Auto Draft', '', 'auto-draft', 'closed', 'closed', '', '', '', '', '2026-08-26 20:11:09', '0000-00-00 00:00:00', '', 0, 'https://violet-wren-104886.hostingersite.com/?page_id=90411', 0, 'page', '', 0),
(90412, 2, '2026-08-26 20:14:46', '2026-08-26 20:14:46', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:html -->\n<style id=\"tb-blog-template-styles\">\n/* Shared Journal article template - applies to every post using Single Posts */\n.tb-article-page {\n  background: #fbf8f2 !important;\n  background-image: none !important;\n  color: #25364a;\n  overflow: hidden;\n}\n.tb-article-header {\n  width: min(860px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: clamp(64px, 8vw, 112px) 0 44px;\n  text-align: center;\n}\n.tb-article-title {\n  max-width: 820px;\n  margin-left: auto !important;\n  margin-right: auto !important;\n  line-height: 1.04 !important;\n}\n.tb-article-dek {\n  max-width: 680px;\n  margin: 22px auto 0 !important;\n  font-size: clamp(18px, 2vw, 23px);\n  line-height: 1.55;\n}\n.tb-article-hero {\n  width: 100%;\n  max-width: none !important;\n  padding: 0 24px clamp(48px, 6vw, 80px);\n  background: #fbf8f2 !important;\n  background-image: none !important;\n  box-sizing: border-box;\n}\n.tb-article-hero:not(:has(.wp-block-post-featured-image img)) { display: none !important; } .tb-article-hero .wp-block-post-featured-image {\n  width: min(1040px, 100%);\n  margin: 0 auto !important;\n}\n.tb-article-hero .wp-block-post-featured-image img {\n  display: block;\n  width: 100%;\n  height: clamp(360px, 52vw, 620px);\n  object-fit: cover;\n  border-radius: 18px;\n  box-shadow: 0 18px 52px rgba(52,76,106,.13);\n}\n.tb-article-body {\n  width: min(720px, calc(100% - 48px));\n  margin: 0 auto;\n  padding-bottom: clamp(72px, 9vw, 120px);\n  font-size: 18px;\n  line-height: 1.78;\n}\n.tb-article-body h2 {\n  margin-top: 2.4em;\n  color: #344c6a;\n}\n.tb-article-body .alignwide {\n  width: min(1040px, calc(100vw - 48px));\n  max-width: none;\n  margin-left: 50% !important;\n  transform: translateX(-50%);\n}\n.tb-article-body figure img {\n  border-radius: 14px;\n}\n.tb-article-explore {\n  padding: clamp(64px, 8vw, 96px) 24px !important;\n  background: #344c6a !important;\n}\n.tb-article-explore .tb-page-shell {\n  width: min(940px, 100%);\n  margin: 0 auto;\n}\n.tb-article-explore__links {\n  max-width: 820px;\n  margin: 34px auto 0;\n}\n.tb-newsletter-feature {\n  width: min(1040px, calc(100% - 48px)) !important;\n  max-width: 1040px !important;\n  min-height: 420px;\n  margin: clamp(72px, 9vw, 112px) auto !important;\n  display: grid !important;\n  grid-template-columns: minmax(300px, .9fr) minmax(420px, 1.25fr);\n  overflow: hidden;\n  border-radius: 18px;\n  box-shadow: 0 18px 55px rgba(52,76,106,.12);\n}\n.tb-newsletter-feature__image {\n  min-height: 420px;\n  background-size: cover !important;\n  background-position: center !important;\n}\n.tb-newsletter-feature__content {\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  padding: clamp(44px, 6vw, 72px) !important;\n}\n.tb-newsletter-fields {\n  display: grid !important;\n  grid-template-columns: 1fr 1fr auto;\n  gap: 12px;\n}\n.tb-article-author {\n  padding: clamp(72px, 9vw, 112px) 24px !important;\n  background: #f1e8dc !important;\n}\n.tb-article-author__inner {\n  width: min(1000px, 100%);\n  margin: 0 auto;\n  display: grid !important;\n  grid-template-columns: minmax(280px, 380px) 1fr;\n  gap: clamp(42px, 7vw, 82px);\n  align-items: center;\n}\n.tb-article-author__inner > img {\n  width: 100%;\n  height: 500px;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 16px;\n  box-shadow: 0 16px 42px rgba(52,76,106,.14);\n}\n.tb-article-author h2 {\n  max-width: 560px;\n  font-size: clamp(36px, 4vw, 54px);\n  line-height: 1.05;\n}\n.tb-article-comments {\n  width: min(820px, calc(100% - 48px));\n  margin: clamp(64px, 8vw, 96px) auto !important;\n  padding: clamp(42px, 6vw, 68px) !important;\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.14);\n  border-radius: 18px;\n  box-shadow: 0 14px 42px rgba(52,76,106,.08);\n  box-sizing: border-box;\n}\n.tb-article-comments textarea,\n.tb-article-comments input:not([type=\"submit\"]) {\n  width: 100%;\n  box-sizing: border-box;\n}\n.tb-article-navigation {\n  width: min(1040px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: 0 0 clamp(72px, 8vw, 104px);\n}\n@media (max-width: 760px) {\n  .tb-article-header { width: min(100% - 32px, 860px); padding-top: 48px; }\n  .tb-article-hero { padding-left: 16px; padding-right: 16px; }\n  .tb-article-hero .wp-block-post-featured-image img { height: 58vw; min-height: 260px; border-radius: 12px; }\n  .tb-article-body { width: min(100% - 36px, 720px); font-size: 17px; }\n  .tb-article-body .alignwide { width: calc(100vw - 32px); }\n  .tb-newsletter-feature { width: calc(100% - 32px) !important; grid-template-columns: 1fr; }\n  .tb-newsletter-feature__image { min-height: 280px; }\n  .tb-newsletter-fields { grid-template-columns: 1fr !important; }\n  .tb-article-author__inner { grid-template-columns: 1fr !important; }\n  .tb-article-author__inner > img { height: 420px; }\n  .tb-article-comments, .tb-article-navigation { width: calc(100% - 32px); }\n}\n\n/* Editorial depth refinement */\n.tb-article-page {\n  background: linear-gradient(180deg, #e8eef2 0, #fbf8f2 720px) !important;\n}\n.tb-article-header {\n  position: relative;\n  z-index: 1;\n  width: min(1040px, calc(100% - 48px));\n  margin: clamp(46px, 6vw, 78px) auto 0;\n  padding: clamp(48px, 6vw, 76px);\n  text-align: left;\n  background: rgba(255,255,255,.96);\n  border: 1px solid rgba(52,76,106,.12);\n  border-radius: 22px;\n  box-shadow: 0 22px 60px rgba(52,76,106,.11);\n  box-sizing: border-box;\n}\n.tb-article-title {\n  max-width: 850px;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n.tb-article-dek {\n  position: relative;\n  max-width: 800px;\n  margin: 36px 0 26px !important;\n  padding: 58px 34px 30px;\n  background: #dfeaed;\n  border-left: 6px solid #d9a21b;\n  border-radius: 12px;\n  box-sizing: border-box;\n  font-size: clamp(17px, 1.7vw, 21px);\n}\n.tb-article-dek::before {\n  content: \"At a glance\";\n  position: absolute;\n  top: 25px;\n  left: 34px;\n  color: #344c6a;\n  font-family: inherit;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: .15em;\n  text-transform: uppercase;\n}\n.tb-article-meta {\n  justify-content: flex-start !important;\n}\n.tb-article-hero {\n  position: relative;\n  z-index: 2;\n  margin-top: -26px;\n}\n.tb-article-body {\n  width: min(860px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: clamp(48px, 6vw, 72px);\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.1);\n  border-radius: 20px;\n  box-shadow: 0 18px 52px rgba(52,76,106,.08);\n  box-sizing: border-box;\n}\n.tb-article-comments {\n  margin-top: 34px !important;\n  margin-bottom: clamp(64px, 8vw, 96px) !important;\n}\n.tb-newsletter-feature {\n  margin-top: 0 !important;\n}\n@media (max-width: 760px) {\n  .tb-article-header {\n    width: calc(100% - 28px);\n    margin-top: 22px;\n    padding: 34px 24px;\n    border-radius: 15px;\n  }\n  .tb-article-dek {\n    padding: 54px 22px 24px;\n  }\n  .tb-article-dek::before {\n    left: 22px;\n  }\n  .tb-article-hero {\n    margin-top: -14px;\n  }\n  .tb-article-body {\n    width: calc(100% - 28px);\n    padding: 36px 22px;\n    border-radius: 15px;\n  }\n}\n\n/* Blog realtor rail and Tanya-color summary */\n.tb-article-dek {\n  background: #f7f1e7 !important;\n  border-left-color: #c77798 !important;\n  color: #344c6a;\n  box-shadow: inset 0 0 0 1px rgba(52,76,106,.08);\n}\n.tb-article-dek::before { color: #344c6a; }\n.tb-blog-layout {\n  width: min(1120px, calc(100% - 48px));\n  margin: 0 auto;\n  display: grid !important;\n  grid-template-columns: minmax(0, 760px) 320px;\n  gap: 42px;\n  align-items: start;\n}\n.tb-blog-main .tb-article-body,\n.tb-blog-main .tb-article-comments {\n  width: 100%;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n.tb-blog-main .tb-article-comments { margin-top: 34px !important; }\n.tb-blog-rail {\n  position: sticky;\n  top: 48px;\n  display: grid;\n  gap: 26px;\n}\n.tb-blog-rail__intro,\n.tb-blog-listings {\n  padding: 26px;\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.12);\n  border-radius: 18px;\n  box-shadow: 0 14px 38px rgba(52,76,106,.08);\n}\n.tb-blog-rail__intro > img {\n  display: block;\n  width: 190px;\n  height: 190px;\n  margin: -4px auto 22px;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 50%;\n  box-shadow: 12px 12px 0 #f2dce4;\n}\n.tb-blog-rail__eyebrow {\n  margin: 0 0 9px;\n  color: #d093aa;\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: .14em;\n  text-transform: uppercase;\n}\n.tb-blog-rail h2 {\n  margin: 0 0 12px;\n  color: #344c6a;\n  font-size: 30px;\n  line-height: 1.05;\n}\n.tb-blog-rail p { line-height: 1.55; }\n.tb-blog-rail__button {\n  display: inline-block;\n  margin-top: 8px;\n  padding: 12px 16px;\n  color: #fff !important;\n  background: #344c6a;\n  border-radius: 4px;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: .08em;\n  text-decoration: none;\n  text-transform: uppercase;\n}\n.tb-listing-grid { display: grid; gap: 18px; margin-top: 20px; }\n.tb-listing-card {\n  display: block;\n  overflow: hidden;\n  color: #25364a !important;\n  background: #fbf8f2;\n  border: 1px solid rgba(52,76,106,.11);\n  border-radius: 12px;\n  text-decoration: none !important;\n  transition: transform .2s ease, box-shadow .2s ease;\n}\n.tb-listing-card:hover {\n  transform: translateY(-3px);\n  box-shadow: 0 12px 26px rgba(52,76,106,.12);\n}\n.tb-listing-card__image {\n  position: relative;\n  display: block;\n  height: 150px;\n}\n.tb-listing-card__image img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n.tb-listing-card__image > span {\n  position: absolute;\n  top: 10px;\n  left: 10px;\n  padding: 6px 9px;\n  color: #344c6a;\n  background: #f7f1e7;\n  border-radius: 999px;\n  font-size: 10px;\n  font-weight: 800;\n  letter-spacing: .1em;\n  text-transform: uppercase;\n}\n.tb-listing-card__body { display: grid; gap: 3px; padding: 15px; }\n.tb-listing-card__body strong { font-family: inherit; font-size: 15px; }\n.tb-listing-card__body b { margin-top: 6px; color: #344c6a; font-size: 18px; }\n.tb-listing-card__body small { color: #6b7580; font-size: 12px; }\n.tb-listing-fallback {\n  display: none;\n  margin-top: 18px;\n  padding: 20px;\n  background: #f7f1e7;\n  border-radius: 12px;\n}\n.tb-listing-grid:not(:has(.tb-listing-card)) + .tb-listing-fallback { display: block; }\n.tb-listing-fallback h3 { margin-top: 0; color: #344c6a; }\n.tb-listing-fallback a,\n.tb-blog-rail__text-link {\n  display: block;\n  margin-top: 12px;\n  color: #344c6a !important;\n  font-weight: 700;\n}\n.tb-blog-rail__text-link { font-size: 13px; }\n@media (max-width: 1020px) {\n  .tb-blog-layout { grid-template-columns: 1fr; }\n  .tb-blog-rail { position: static; grid-template-columns: .8fr 1.2fr; }\n  .tb-listing-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }\n}\n@media (max-width: 700px) {\n  .tb-blog-layout { width: calc(100% - 28px); }\n  .tb-blog-rail { grid-template-columns: 1fr; }\n  .tb-listing-grid { grid-template-columns: 1fr; }\n}\n.tb-article-page{display:grid;grid-template-columns:minmax(0,760px) 320px;column-gap:42px;justify-content:center;} .tb-article-header{grid-column:1 / -1;grid-row:1;} .tb-article-hero{grid-column:1 / -1;grid-row:2;} .tb-article-body{grid-column:1;grid-row:3;width:100%;margin-left:0;margin-right:0;} .tb-blog-rail{grid-column:2;grid-row:3 / span 2;} .tb-article-comments{grid-column:1;grid-row:4;width:100%;margin-left:0!important;margin-right:0!important;} .tb-newsletter-feature{grid-column:1 / -1;grid-row:5;} .tb-article-navigation{grid-column:1 / -1;grid-row:6;} @media(max-width:1020px){.tb-article-page{display:block}.tb-blog-rail{position:static;width:min(860px,calc(100% - 28px));margin:34px auto 72px}.tb-article-body,.tb-article-comments{width:min(860px,calc(100% - 28px));margin-left:auto!important;margin-right:auto!important}.tb-blog-rail{display:grid;grid-template-columns:.8fr 1.2fr}.tb-listing-grid{grid-template-columns:repeat(2,minmax(0,1fr))}} @media(max-width:700px){.tb-blog-rail{grid-template-columns:1fr}.tb-listing-grid{grid-template-columns:1fr}}\n.tb-blog-rail{align-self:start;height:max-content;}\n\n/* Neighborhood Guides automatically use the local-guide layout */\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-hero,\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-blog-rail {\n  display: none !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-page {\n  display: block !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-header {\n  padding-bottom: 30px !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body {\n  width: min(900px, calc(100% - 48px)) !important;\n  margin: 28px auto 0 !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-comments {\n  width: min(900px, calc(100% - 48px)) !important;\n  margin-left: auto !important;\n  margin-right: auto !important;\n}\n@media (max-width: 760px) {\n  body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body,\n  body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-comments {\n    width: calc(100% - 28px) !important;\n  }\n}\n@media (max-width: 760px) { body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body { margin-top: 18px !important; } }\n</style>\n<!-- /wp:html --> <!-- wp:group {\"tagName\":\"main\",\"className\":\"tb-article-page\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group tb-article-page\">\n\n	<!-- wp:group {\"className\":\"tb-article-header\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"920px\"}} -->\n	<header class=\"wp-block-group tb-article-header\">\n		<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-journal-label\"} /-->\n		<!-- wp:post-title {\"level\":1,\"className\":\"tb-article-title\",\"fontSize\":\"x-large\"} /-->\n		<!-- wp:post-excerpt {\"moreText\":\"\",\"excerptLength\":32,\"className\":\"tb-article-dek\"} /-->\n		<!-- wp:group {\"className\":\"tb-article-meta\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"center\"}} -->\n		<div class=\"wp-block-group tb-article-meta\">\n			<!-- wp:paragraph --><p>From Tanya Barrans</p><!-- /wp:paragraph -->\n			<!-- wp:post-date /-->\n		</div>\n		<!-- /wp:group -->\n	</header>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-hero\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-article-hero\">\n		<!-- wp:post-featured-image {\"aspectRatio\":\"16/9\",\"sizeSlug\":\"full\"} /-->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-body\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\",\"wideSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-article-body\">\n		<!-- wp:post-content {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\",\"wideSize\":\"1200px\"}} /-->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-comments\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\"}} -->\n<div class=\"wp-block-group tb-article-comments\">\n<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Join the conversation</h2><!-- /wp:heading -->\n<!-- wp:paragraph --><p>Have a tip, a question, or a story of your own? I’d love to hear it.</p><!-- /wp:paragraph -->\n<!-- wp:comments -->\n<div class=\"wp-block-comments\">\n<!-- wp:comments-title {\"showPostTitle\":false} /-->\n<!-- wp:comment-template -->\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} --><div class=\"wp-block-group\"><!-- wp:avatar {\"size\":48} /--><!-- wp:group --><div class=\"wp-block-group\"><!-- wp:comment-author-name /--><!-- wp:comment-date /--></div><!-- /wp:group --></div><!-- /wp:group -->\n<!-- wp:comment-content /-->\n<!-- wp:comment-reply-link /-->\n<!-- /wp:comment-template -->\n<!-- wp:post-comments-form /-->\n</div>\n<!-- /wp:comments -->\n</div>\n<!-- /wp:group --> <!-- wp:html -->\n<aside class=\"tb-blog-rail\" aria-label=\"About Tanya and current listings\">\n  <section class=\"tb-blog-rail__intro\">\n    <img src=\"/wp-content/uploads/2026/07/about-main.jpg\" alt=\"Tanya Barrans, Puget Sound real estate broker\" loading=\"lazy\">\n    <p class=\"tb-blog-rail__eyebrow\">Your local real estate resource</p>\n    <h2>Hi, I’m Tanya.</h2>\n    <p>I help buyers and sellers make thoughtful moves across Renton and the South Sound—with honest guidance and a little more personality.</p>\n    <a class=\"tb-blog-rail__button\" href=\"/contact/\">Ask Tanya a question</a>\n  </section>\n  <section class=\"tb-blog-listings\">\n    <p class=\"tb-blog-rail__eyebrow\">Currently listed by Tanya</p>\n    <h2>Homes worth a look</h2>\n    <div class=\"tb-listing-grid\">\n      <a class=\"tb-listing-card\" href=\"https://tanyab.johnlscott.com/listing/wa/olympia/5246-yearley-drive-ne-/21476453\" target=\"_blank\" rel=\"noopener\">\n        <span class=\"tb-listing-card__image\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/253/429/2534297.jpg\" alt=\"5246 Yearley Drive NE in Olympia\" loading=\"lazy\"><span>Active</span></span>\n        <span class=\"tb-listing-card__body\"><strong>5246 Yearley Drive NE</strong><small>Olympia, WA</small><b>$389,999</b><small>2 beds · 1.75 baths · 972 sq ft</small></span>\n      </a>\n      <a class=\"tb-listing-card\" href=\"https://tanyab.johnlscott.com/listing/wa/puyallup/18026-75th-avenue-e-/21497093\" target=\"_blank\" rel=\"noopener\">\n        <span class=\"tb-listing-card__image\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/254/658/2546584.jpg\" alt=\"18026 75th Avenue E in Puyallup\" loading=\"lazy\"><span>Active</span></span>\n        <span class=\"tb-listing-card__body\"><strong>18026 75th Avenue E</strong><small>Puyallup, WA</small><b>$545,000</b><small>4 beds · 2.5 baths · 2,201 sq ft</small></span>\n      </a>\n    </div>\n    <div class=\"tb-listing-fallback\">\n      <h3>Nothing active right now—but the search doesn’t stop here.</h3>\n      <p>Browse homes on my John L. Scott site or tell me what you’re hoping to find.</p>\n      <a href=\"https://tanyab.johnlscott.com/search\" target=\"_blank\" rel=\"noopener\">Explore available homes</a>\n      <a href=\"/contact/\">Tell me what you’re looking for</a>\n    </div>\n    <a class=\"tb-blog-rail__text-link\" href=\"https://tanyab.johnlscott.com\" target=\"_blank\" rel=\"noopener\">See all listings on John L. Scott →</a>\n  </section>\n</aside>\n<!-- /wp:html --> <!-- wp:group {\"align\":\"full\",\"className\":\"tb-newsletter-feature\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/newsletter\",\"name\":\"Newsletter Signup\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-newsletter-feature has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg)\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__content tb-reveal\">\n		<!-- wp:paragraph {\"className\":\"tb-script-accent\"} -->\n		<p class=\"tb-script-accent\">Let’s stay in touch</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"x-large\"} -->\n		<h2 class=\"wp-block-heading has-x-large-font-size\">Notes worth opening.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Useful home ideas, local stories, and honest real estate guidance—delivered with no pressure and no polished filler.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:html -->\n		<form class=\"tb-newsletter-form\" novalidate>\n			<div class=\"tb-newsletter-fields\">\n				<label class=\"tb-sr-only\" for=\"tb-nl-name\">First name</label>\n				<input type=\"text\" id=\"tb-nl-name\" name=\"name\" class=\"tb-newsletter-input\" placeholder=\"First name\" autocomplete=\"given-name\" />\n\n				<label class=\"tb-sr-only\" for=\"tb-nl-email\">Email address</label>\n				<input type=\"email\" id=\"tb-nl-email\" name=\"email\" class=\"tb-newsletter-input\" placeholder=\"Email address\" autocomplete=\"email\" required />\n\n				<div class=\"tb-newsletter-hp\" aria-hidden=\"true\">\n					<label for=\"tb-nl-website\">Website</label>\n					<input type=\"text\" id=\"tb-nl-website\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" />\n				</div>\n\n				<button type=\"submit\" class=\"tb-newsletter-submit\">Subscribe</button>\n			</div>\n			<p class=\"tb-newsletter-status\" role=\"status\" aria-live=\"polite\"></p>\n		</form>\n		<!-- /wp:html -->\n\n		<!-- wp:paragraph {\"className\":\"tb-newsletter-feature__privacy\"} -->\n		<p class=\"tb-newsletter-feature__privacy\">No spam. Unsubscribe whenever you like.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-navigation\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<nav class=\"wp-block-group tb-article-navigation\" aria-label=\"Article navigation\">\n		<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\"}} -->\n		<div class=\"wp-block-group\">\n			<!-- wp:post-navigation-link {\"type\":\"previous\",\"label\":\"Previous story\",\"showTitle\":true,\"linkLabel\":true} /-->\n			<!-- wp:post-navigation-link {\"type\":\"next\",\"label\":\"Next story\",\"showTitle\":true,\"linkLabel\":true} /-->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-journal-back-link\"} --><p class=\"has-text-align-center tb-journal-back-link\"><a href=\"/blog/\">Back to the Journal</a></p><!-- /wp:paragraph -->\n	</nav>\n	<!-- /wp:group -->\n\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n', 'Blog Posts', 'Displays a single post on your website unless a custom template has been applied to that post or a dedicated template exists.', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-08-26 20:14:46', '2026-08-26 20:14:46', '', 99, 'https://violet-wren-104886.hostingersite.com/?p=90412', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(90413, 2, '2026-08-26 20:19:29', '2026-08-26 20:19:29', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:html -->\n<style id=\"tb-blog-template-styles\">\n/* Shared Journal article template - applies to every post using Single Posts */\n.tb-article-page {\n  background: #fbf8f2 !important;\n  background-image: none !important;\n  color: #25364a;\n  overflow: hidden;\n}\n.tb-article-header {\n  width: min(860px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: clamp(64px, 8vw, 112px) 0 44px;\n  text-align: center;\n}\n.tb-article-title {\n  max-width: 820px;\n  margin-left: auto !important;\n  margin-right: auto !important;\n  line-height: 1.04 !important;\n}\n.tb-article-dek {\n  max-width: 680px;\n  margin: 22px auto 0 !important;\n  font-size: clamp(18px, 2vw, 23px);\n  line-height: 1.55;\n}\n.tb-article-hero {\n  width: 100%;\n  max-width: none !important;\n  padding: 0 24px clamp(48px, 6vw, 80px);\n  background: #fbf8f2 !important;\n  background-image: none !important;\n  box-sizing: border-box;\n}\n.tb-article-hero:not(:has(.wp-block-post-featured-image img)) { display: none !important; } .tb-article-hero .wp-block-post-featured-image {\n  width: min(1040px, 100%);\n  margin: 0 auto !important;\n}\n.tb-article-hero .wp-block-post-featured-image img {\n  display: block;\n  width: 100%;\n  height: clamp(360px, 52vw, 620px);\n  object-fit: cover;\n  border-radius: 18px;\n  box-shadow: 0 18px 52px rgba(52,76,106,.13);\n}\n.tb-article-body {\n  width: min(720px, calc(100% - 48px));\n  margin: 0 auto;\n  padding-bottom: clamp(72px, 9vw, 120px);\n  font-size: 18px;\n  line-height: 1.78;\n}\n.tb-article-body h2 {\n  margin-top: 2.4em;\n  color: #344c6a;\n}\n.tb-article-body .alignwide {\n  width: min(1040px, calc(100vw - 48px));\n  max-width: none;\n  margin-left: 50% !important;\n  transform: translateX(-50%);\n}\n.tb-article-body figure img {\n  border-radius: 14px;\n}\n.tb-article-explore {\n  padding: clamp(64px, 8vw, 96px) 24px !important;\n  background: #344c6a !important;\n}\n.tb-article-explore .tb-page-shell {\n  width: min(940px, 100%);\n  margin: 0 auto;\n}\n.tb-article-explore__links {\n  max-width: 820px;\n  margin: 34px auto 0;\n}\n.tb-newsletter-feature {\n  width: min(1040px, calc(100% - 48px)) !important;\n  max-width: 1040px !important;\n  min-height: 420px;\n  margin: clamp(72px, 9vw, 112px) auto !important;\n  display: grid !important;\n  grid-template-columns: minmax(300px, .9fr) minmax(420px, 1.25fr);\n  overflow: hidden;\n  border-radius: 18px;\n  box-shadow: 0 18px 55px rgba(52,76,106,.12);\n}\n.tb-newsletter-feature__image {\n  min-height: 420px;\n  background-size: cover !important;\n  background-position: center !important;\n}\n.tb-newsletter-feature__content {\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  padding: clamp(44px, 6vw, 72px) !important;\n}\n.tb-newsletter-fields {\n  display: grid !important;\n  grid-template-columns: 1fr 1fr auto;\n  gap: 12px;\n}\n.tb-article-author {\n  padding: clamp(72px, 9vw, 112px) 24px !important;\n  background: #f1e8dc !important;\n}\n.tb-article-author__inner {\n  width: min(1000px, 100%);\n  margin: 0 auto;\n  display: grid !important;\n  grid-template-columns: minmax(280px, 380px) 1fr;\n  gap: clamp(42px, 7vw, 82px);\n  align-items: center;\n}\n.tb-article-author__inner > img {\n  width: 100%;\n  height: 500px;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 16px;\n  box-shadow: 0 16px 42px rgba(52,76,106,.14);\n}\n.tb-article-author h2 {\n  max-width: 560px;\n  font-size: clamp(36px, 4vw, 54px);\n  line-height: 1.05;\n}\n.tb-article-comments {\n  width: min(820px, calc(100% - 48px));\n  margin: clamp(64px, 8vw, 96px) auto !important;\n  padding: clamp(42px, 6vw, 68px) !important;\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.14);\n  border-radius: 18px;\n  box-shadow: 0 14px 42px rgba(52,76,106,.08);\n  box-sizing: border-box;\n}\n.tb-article-comments textarea,\n.tb-article-comments input:not([type=\"submit\"]) {\n  width: 100%;\n  box-sizing: border-box;\n}\n.tb-article-navigation {\n  width: min(1040px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: 0 0 clamp(72px, 8vw, 104px);\n}\n@media (max-width: 760px) {\n  .tb-article-header { width: min(100% - 32px, 860px); padding-top: 48px; }\n  .tb-article-hero { padding-left: 16px; padding-right: 16px; }\n  .tb-article-hero .wp-block-post-featured-image img { height: 58vw; min-height: 260px; border-radius: 12px; }\n  .tb-article-body { width: min(100% - 36px, 720px); font-size: 17px; }\n  .tb-article-body .alignwide { width: calc(100vw - 32px); }\n  .tb-newsletter-feature { width: calc(100% - 32px) !important; grid-template-columns: 1fr; }\n  .tb-newsletter-feature__image { min-height: 280px; }\n  .tb-newsletter-fields { grid-template-columns: 1fr !important; }\n  .tb-article-author__inner { grid-template-columns: 1fr !important; }\n  .tb-article-author__inner > img { height: 420px; }\n  .tb-article-comments, .tb-article-navigation { width: calc(100% - 32px); }\n}\n\n/* Editorial depth refinement */\n.tb-article-page {\n  background: linear-gradient(180deg, #e8eef2 0, #fbf8f2 720px) !important;\n}\n.tb-article-header {\n  position: relative;\n  z-index: 1;\n  width: min(1040px, calc(100% - 48px));\n  margin: clamp(46px, 6vw, 78px) auto 0;\n  padding: clamp(48px, 6vw, 76px);\n  text-align: left;\n  background: rgba(255,255,255,.96);\n  border: 1px solid rgba(52,76,106,.12);\n  border-radius: 22px;\n  box-shadow: 0 22px 60px rgba(52,76,106,.11);\n  box-sizing: border-box;\n}\n.tb-article-title {\n  max-width: 850px;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n.tb-article-dek {\n  position: relative;\n  max-width: 800px;\n  margin: 36px 0 26px !important;\n  padding: 58px 34px 30px;\n  background: #dfeaed;\n  border-left: 6px solid #d9a21b;\n  border-radius: 12px;\n  box-sizing: border-box;\n  font-size: clamp(17px, 1.7vw, 21px);\n}\n.tb-article-dek::before {\n  content: \"At a glance\";\n  position: absolute;\n  top: 25px;\n  left: 34px;\n  color: #344c6a;\n  font-family: inherit;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: .15em;\n  text-transform: uppercase;\n}\n.tb-article-meta {\n  justify-content: flex-start !important;\n}\n.tb-article-hero {\n  position: relative;\n  z-index: 2;\n  margin-top: -26px;\n}\n.tb-article-body {\n  width: min(860px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: clamp(48px, 6vw, 72px);\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.1);\n  border-radius: 20px;\n  box-shadow: 0 18px 52px rgba(52,76,106,.08);\n  box-sizing: border-box;\n}\n.tb-article-comments {\n  margin-top: 34px !important;\n  margin-bottom: clamp(64px, 8vw, 96px) !important;\n}\n.tb-newsletter-feature {\n  margin-top: 0 !important;\n}\n@media (max-width: 760px) {\n  .tb-article-header {\n    width: calc(100% - 28px);\n    margin-top: 22px;\n    padding: 34px 24px;\n    border-radius: 15px;\n  }\n  .tb-article-dek {\n    padding: 54px 22px 24px;\n  }\n  .tb-article-dek::before {\n    left: 22px;\n  }\n  .tb-article-hero {\n    margin-top: -14px;\n  }\n  .tb-article-body {\n    width: calc(100% - 28px);\n    padding: 36px 22px;\n    border-radius: 15px;\n  }\n}\n\n/* Blog realtor rail and Tanya-color summary */\n.tb-article-dek {\n  background: #f7f1e7 !important;\n  border-left-color: #c77798 !important;\n  color: #344c6a;\n  box-shadow: inset 0 0 0 1px rgba(52,76,106,.08);\n}\n.tb-article-dek::before { color: #344c6a; }\n.tb-blog-layout {\n  width: min(1120px, calc(100% - 48px));\n  margin: 0 auto;\n  display: grid !important;\n  grid-template-columns: minmax(0, 760px) 320px;\n  gap: 42px;\n  align-items: start;\n}\n.tb-blog-main .tb-article-body,\n.tb-blog-main .tb-article-comments {\n  width: 100%;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n.tb-blog-main .tb-article-comments { margin-top: 34px !important; }\n.tb-blog-rail {\n  position: sticky;\n  top: 48px;\n  display: grid;\n  gap: 26px;\n}\n.tb-blog-rail__intro,\n.tb-blog-listings {\n  padding: 26px;\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.12);\n  border-radius: 18px;\n  box-shadow: 0 14px 38px rgba(52,76,106,.08);\n}\n.tb-blog-rail__intro > img {\n  display: block;\n  width: 190px;\n  height: 190px;\n  margin: -4px auto 22px;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 50% 50% 46% 54%;\n  box-shadow: 0 0 0 8px #f2dce4;\n}\n.tb-blog-rail__eyebrow {\n  margin: 0 0 9px;\n  color: #d093aa;\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: .14em;\n  text-transform: uppercase;\n}\n.tb-blog-rail h2 {\n  margin: 0 0 12px;\n  color: #344c6a;\n  font-size: 30px;\n  line-height: 1.05;\n}\n.tb-blog-rail p { line-height: 1.55; }\n.tb-blog-rail__button {\n  display: inline-block;\n  margin-top: 8px;\n  padding: 12px 16px;\n  color: #fff !important;\n  background: #344c6a;\n  border-radius: 4px;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: .08em;\n  text-decoration: none;\n  text-transform: uppercase;\n}\n.tb-listing-grid { display: grid; gap: 18px; margin-top: 20px; }\n.tb-listing-card {\n  display: block;\n  overflow: hidden;\n  color: #25364a !important;\n  background: #fbf8f2;\n  border: 1px solid rgba(52,76,106,.11);\n  border-radius: 12px;\n  text-decoration: none !important;\n  transition: transform .2s ease, box-shadow .2s ease;\n}\n.tb-listing-card:hover {\n  transform: translateY(-3px);\n  box-shadow: 0 12px 26px rgba(52,76,106,.12);\n}\n.tb-listing-card__image {\n  position: relative;\n  display: block;\n  height: 150px;\n}\n.tb-listing-card__image img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n.tb-listing-card__image > span {\n  position: absolute;\n  top: 10px;\n  left: 10px;\n  padding: 6px 9px;\n  color: #344c6a;\n  background: #f7f1e7;\n  border-radius: 999px;\n  font-size: 10px;\n  font-weight: 800;\n  letter-spacing: .1em;\n  text-transform: uppercase;\n}\n.tb-listing-card__body { display: grid; gap: 3px; padding: 15px; }\n.tb-listing-card__body strong { font-family: inherit; font-size: 15px; }\n.tb-listing-card__body b { margin-top: 6px; color: #344c6a; font-size: 18px; }\n.tb-listing-card__body small { color: #6b7580; font-size: 12px; }\n.tb-listing-fallback {\n  display: none;\n  margin-top: 18px;\n  padding: 20px;\n  background: #f7f1e7;\n  border-radius: 12px;\n}\n.tb-listing-grid:not(:has(.tb-listing-card)) + .tb-listing-fallback { display: block; }\n.tb-listing-fallback h3 { margin-top: 0; color: #344c6a; }\n.tb-listing-fallback a,\n.tb-blog-rail__text-link {\n  display: block;\n  margin-top: 12px;\n  color: #344c6a !important;\n  font-weight: 700;\n}\n.tb-blog-rail__text-link { font-size: 13px; }\n@media (max-width: 1020px) {\n  .tb-blog-layout { grid-template-columns: 1fr; }\n  .tb-blog-rail { position: static; grid-template-columns: .8fr 1.2fr; }\n  .tb-listing-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }\n}\n@media (max-width: 700px) {\n  .tb-blog-layout { width: calc(100% - 28px); }\n  .tb-blog-rail { grid-template-columns: 1fr; }\n  .tb-listing-grid { grid-template-columns: 1fr; }\n}\n.tb-article-page{display:grid;grid-template-columns:minmax(0,760px) 320px;column-gap:42px;justify-content:center;} .tb-article-header{grid-column:1 / -1;grid-row:1;} .tb-article-hero{grid-column:1 / -1;grid-row:2;} .tb-article-body{grid-column:1;grid-row:3;width:100%;margin-left:0;margin-right:0;} .tb-blog-rail{grid-column:2;grid-row:3 / span 2;} .tb-article-comments{grid-column:1;grid-row:4;width:100%;margin-left:0!important;margin-right:0!important;} .tb-newsletter-feature{grid-column:1 / -1;grid-row:5;} .tb-article-navigation{grid-column:1 / -1;grid-row:6;} @media(max-width:1020px){.tb-article-page{display:block}.tb-blog-rail{position:static;width:min(860px,calc(100% - 28px));margin:34px auto 72px}.tb-article-body,.tb-article-comments{width:min(860px,calc(100% - 28px));margin-left:auto!important;margin-right:auto!important}.tb-blog-rail{display:grid;grid-template-columns:.8fr 1.2fr}.tb-listing-grid{grid-template-columns:repeat(2,minmax(0,1fr))}} @media(max-width:700px){.tb-blog-rail{grid-template-columns:1fr}.tb-listing-grid{grid-template-columns:1fr}}\n.tb-blog-rail{align-self:start;height:max-content;}\n\n/* Neighborhood Guides automatically use the local-guide layout */\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-hero,\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-blog-rail {\n  display: none !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-page {\n  display: block !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-header {\n  padding-bottom: 30px !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body {\n  width: min(900px, calc(100% - 48px)) !important;\n  margin: 28px auto 0 !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-comments {\n  width: min(900px, calc(100% - 48px)) !important;\n  margin-left: auto !important;\n  margin-right: auto !important;\n}\n@media (max-width: 760px) {\n  body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body,\n  body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-comments {\n    width: calc(100% - 28px) !important;\n  }\n}\n@media (max-width: 760px) { body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body { margin-top: 18px !important; } }\n</style>\n<!-- /wp:html --> <!-- wp:group {\"tagName\":\"main\",\"className\":\"tb-article-page\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group tb-article-page\">\n\n	<!-- wp:group {\"className\":\"tb-article-header\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"920px\"}} -->\n	<header class=\"wp-block-group tb-article-header\">\n		<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-journal-label\"} /-->\n		<!-- wp:post-title {\"level\":1,\"className\":\"tb-article-title\",\"fontSize\":\"x-large\"} /-->\n		<!-- wp:post-excerpt {\"moreText\":\"\",\"excerptLength\":32,\"className\":\"tb-article-dek\"} /-->\n		<!-- wp:group {\"className\":\"tb-article-meta\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"center\"}} -->\n		<div class=\"wp-block-group tb-article-meta\">\n			<!-- wp:paragraph --><p>From Tanya Barrans</p><!-- /wp:paragraph -->\n			<!-- wp:post-date /-->\n		</div>\n		<!-- /wp:group -->\n	</header>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-hero\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-article-hero\">\n		<!-- wp:post-featured-image {\"aspectRatio\":\"16/9\",\"sizeSlug\":\"full\"} /-->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-body\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\",\"wideSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-article-body\">\n		<!-- wp:post-content {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\",\"wideSize\":\"1200px\"}} /-->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-comments\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\"}} -->\n<div class=\"wp-block-group tb-article-comments\">\n<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Join the conversation</h2><!-- /wp:heading -->\n<!-- wp:paragraph --><p>Have a tip, a question, or a story of your own? I’d love to hear it.</p><!-- /wp:paragraph -->\n<!-- wp:comments -->\n<div class=\"wp-block-comments\">\n<!-- wp:comments-title {\"showPostTitle\":false} /-->\n<!-- wp:comment-template -->\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} --><div class=\"wp-block-group\"><!-- wp:avatar {\"size\":48} /--><!-- wp:group --><div class=\"wp-block-group\"><!-- wp:comment-author-name /--><!-- wp:comment-date /--></div><!-- /wp:group --></div><!-- /wp:group -->\n<!-- wp:comment-content /-->\n<!-- wp:comment-reply-link /-->\n<!-- /wp:comment-template -->\n<!-- wp:post-comments-form /-->\n</div>\n<!-- /wp:comments -->\n</div>\n<!-- /wp:group --> <!-- wp:html -->\n<aside class=\"tb-blog-rail\" aria-label=\"About Tanya and current listings\">\n  <section class=\"tb-blog-rail__intro\">\n    <img src=\"/wp-content/uploads/2026/07/about-main.jpg\" alt=\"Tanya Barrans, Puget Sound real estate broker\" loading=\"lazy\">\n    <p class=\"tb-blog-rail__eyebrow\">Your local real estate resource</p>\n    <h2>Hi, I’m Tanya.</h2>\n    <p>I help buyers and sellers make thoughtful moves across Renton and the South Sound—with honest guidance and a little more personality.</p>\n    <a class=\"tb-blog-rail__button\" href=\"/contact/\">Ask Tanya a question</a>\n  </section>\n  <section class=\"tb-blog-listings\">\n    <p class=\"tb-blog-rail__eyebrow\">Currently listed by Tanya</p>\n    <h2>Homes worth a look</h2>\n    <div class=\"tb-listing-grid\">\n      <a class=\"tb-listing-card\" href=\"https://tanyab.johnlscott.com/listing/wa/olympia/5246-yearley-drive-ne-/21476453\" target=\"_blank\" rel=\"noopener\">\n        <span class=\"tb-listing-card__image\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/253/429/2534297.jpg\" alt=\"5246 Yearley Drive NE in Olympia\" loading=\"lazy\"><span>Active</span></span>\n        <span class=\"tb-listing-card__body\"><strong>5246 Yearley Drive NE</strong><small>Olympia, WA</small><b>$389,999</b><small>2 beds · 1.75 baths · 972 sq ft</small></span>\n      </a>\n      <a class=\"tb-listing-card\" href=\"https://tanyab.johnlscott.com/listing/wa/puyallup/18026-75th-avenue-e-/21497093\" target=\"_blank\" rel=\"noopener\">\n        <span class=\"tb-listing-card__image\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/254/658/2546584.jpg\" alt=\"18026 75th Avenue E in Puyallup\" loading=\"lazy\"><span>Active</span></span>\n        <span class=\"tb-listing-card__body\"><strong>18026 75th Avenue E</strong><small>Puyallup, WA</small><b>$545,000</b><small>4 beds · 2.5 baths · 2,201 sq ft</small></span>\n      </a>\n    </div>\n    <div class=\"tb-listing-fallback\">\n      <h3>Nothing active right now—but the search doesn’t stop here.</h3>\n      <p>Browse homes on my John L. Scott site or tell me what you’re hoping to find.</p>\n      <a href=\"https://tanyab.johnlscott.com/search\" target=\"_blank\" rel=\"noopener\">Explore available homes</a>\n      <a href=\"/contact/\">Tell me what you’re looking for</a>\n    </div>\n    <a class=\"tb-blog-rail__text-link\" href=\"https://tanyab.johnlscott.com\" target=\"_blank\" rel=\"noopener\">See all listings on John L. Scott →</a>\n  </section>\n</aside>\n<!-- /wp:html --> <!-- wp:group {\"align\":\"full\",\"className\":\"tb-newsletter-feature\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/newsletter\",\"name\":\"Newsletter Signup\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-newsletter-feature has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg)\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__content tb-reveal\">\n		<!-- wp:paragraph {\"className\":\"tb-script-accent\"} -->\n		<p class=\"tb-script-accent\">Let’s stay in touch</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"x-large\"} -->\n		<h2 class=\"wp-block-heading has-x-large-font-size\">Notes worth opening.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Useful home ideas, local stories, and honest real estate guidance—delivered with no pressure and no polished filler.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:html -->\n		<form class=\"tb-newsletter-form\" novalidate>\n			<div class=\"tb-newsletter-fields\">\n				<label class=\"tb-sr-only\" for=\"tb-nl-name\">First name</label>\n				<input type=\"text\" id=\"tb-nl-name\" name=\"name\" class=\"tb-newsletter-input\" placeholder=\"First name\" autocomplete=\"given-name\" />\n\n				<label class=\"tb-sr-only\" for=\"tb-nl-email\">Email address</label>\n				<input type=\"email\" id=\"tb-nl-email\" name=\"email\" class=\"tb-newsletter-input\" placeholder=\"Email address\" autocomplete=\"email\" required />\n\n				<div class=\"tb-newsletter-hp\" aria-hidden=\"true\">\n					<label for=\"tb-nl-website\">Website</label>\n					<input type=\"text\" id=\"tb-nl-website\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" />\n				</div>\n\n				<button type=\"submit\" class=\"tb-newsletter-submit\">Subscribe</button>\n			</div>\n			<p class=\"tb-newsletter-status\" role=\"status\" aria-live=\"polite\"></p>\n		</form>\n		<!-- /wp:html -->\n\n		<!-- wp:paragraph {\"className\":\"tb-newsletter-feature__privacy\"} -->\n		<p class=\"tb-newsletter-feature__privacy\">No spam. Unsubscribe whenever you like.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-navigation\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<nav class=\"wp-block-group tb-article-navigation\" aria-label=\"Article navigation\">\n		<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\"}} -->\n		<div class=\"wp-block-group\">\n			<!-- wp:post-navigation-link {\"type\":\"previous\",\"label\":\"Previous story\",\"showTitle\":true,\"linkLabel\":true} /-->\n			<!-- wp:post-navigation-link {\"type\":\"next\",\"label\":\"Next story\",\"showTitle\":true,\"linkLabel\":true} /-->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-journal-back-link\"} --><p class=\"has-text-align-center tb-journal-back-link\"><a href=\"/blog/\">Back to the Journal</a></p><!-- /wp:paragraph -->\n	</nav>\n	<!-- /wp:group -->\n\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n', 'Blog Posts', 'Displays a single post on your website unless a custom template has been applied to that post or a dedicated template exists.', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-08-26 20:19:29', '2026-08-26 20:19:29', '', 99, 'https://violet-wren-104886.hostingersite.com/?p=90413', 0, 'revision', '', 0),
(90414, 2, '2026-08-26 20:22:13', '2026-08-26 20:22:13', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:html -->\n<style id=\"tb-blog-template-styles\">\n/* Shared Journal article template - applies to every post using Single Posts */\n.tb-article-page {\n  background: #fbf8f2 !important;\n  background-image: none !important;\n  color: #25364a;\n  overflow: hidden;\n} /* Add breathing room when a post has no hero image */\n.tb-article-hero:not(:has(.wp-block-post-featured-image img))\n  + .tb-article-body {\n  margin-top: clamp(32px, 4vw, 56px) !important;\n}\n.tb-article-header {\n  width: min(860px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: clamp(64px, 8vw, 112px) 0 44px;\n  text-align: center;\n}\n.tb-article-title {\n  max-width: 820px;\n  margin-left: auto !important;\n  margin-right: auto !important;\n  line-height: 1.04 !important;\n}\n.tb-article-dek {\n  max-width: 680px;\n  margin: 22px auto 0 !important;\n  font-size: clamp(18px, 2vw, 23px);\n  line-height: 1.55;\n}\n.tb-article-hero {\n  width: 100%;\n  max-width: none !important;\n  padding: 0 24px clamp(48px, 6vw, 80px);\n  background: #fbf8f2 !important;\n  background-image: none !important;\n  box-sizing: border-box;\n}\n.tb-article-hero:not(:has(.wp-block-post-featured-image img)) { display: none !important; } .tb-article-hero .wp-block-post-featured-image {\n  width: min(1040px, 100%);\n  margin: 0 auto !important;\n}\n.tb-article-hero .wp-block-post-featured-image img {\n  display: block;\n  width: 100%;\n  height: clamp(360px, 52vw, 620px);\n  object-fit: cover;\n  border-radius: 18px;\n  box-shadow: 0 18px 52px rgba(52,76,106,.13);\n}\n.tb-article-body {\n  width: min(720px, calc(100% - 48px));\n  margin: 0 auto;\n  padding-bottom: clamp(72px, 9vw, 120px);\n  font-size: 18px;\n  line-height: 1.78;\n}\n.tb-article-body h2 {\n  margin-top: 2.4em;\n  color: #344c6a;\n}\n.tb-article-body .alignwide {\n  width: min(1040px, calc(100vw - 48px));\n  max-width: none;\n  margin-left: 50% !important;\n  transform: translateX(-50%);\n}\n.tb-article-body figure img {\n  border-radius: 14px;\n}\n.tb-article-explore {\n  padding: clamp(64px, 8vw, 96px) 24px !important;\n  background: #344c6a !important;\n}\n.tb-article-explore .tb-page-shell {\n  width: min(940px, 100%);\n  margin: 0 auto;\n}\n.tb-article-explore__links {\n  max-width: 820px;\n  margin: 34px auto 0;\n}\n.tb-newsletter-feature {\n  width: min(1040px, calc(100% - 48px)) !important;\n  max-width: 1040px !important;\n  min-height: 420px;\n  margin: clamp(72px, 9vw, 112px) auto !important;\n  display: grid !important;\n  grid-template-columns: minmax(300px, .9fr) minmax(420px, 1.25fr);\n  overflow: hidden;\n  border-radius: 18px;\n  box-shadow: 0 18px 55px rgba(52,76,106,.12);\n}\n.tb-newsletter-feature__image {\n  min-height: 420px;\n  background-size: cover !important;\n  background-position: center !important;\n}\n.tb-newsletter-feature__content {\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  padding: clamp(44px, 6vw, 72px) !important;\n}\n.tb-newsletter-fields {\n  display: grid !important;\n  grid-template-columns: 1fr 1fr auto;\n  gap: 12px;\n}\n.tb-article-author {\n  padding: clamp(72px, 9vw, 112px) 24px !important;\n  background: #f1e8dc !important;\n}\n.tb-article-author__inner {\n  width: min(1000px, 100%);\n  margin: 0 auto;\n  display: grid !important;\n  grid-template-columns: minmax(280px, 380px) 1fr;\n  gap: clamp(42px, 7vw, 82px);\n  align-items: center;\n}\n.tb-article-author__inner > img {\n  width: 100%;\n  height: 500px;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 16px;\n  box-shadow: 0 16px 42px rgba(52,76,106,.14);\n}\n.tb-article-author h2 {\n  max-width: 560px;\n  font-size: clamp(36px, 4vw, 54px);\n  line-height: 1.05;\n}\n.tb-article-comments {\n  width: min(820px, calc(100% - 48px));\n  margin: clamp(64px, 8vw, 96px) auto !important;\n  padding: clamp(42px, 6vw, 68px) !important;\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.14);\n  border-radius: 18px;\n  box-shadow: 0 14px 42px rgba(52,76,106,.08);\n  box-sizing: border-box;\n}\n.tb-article-comments textarea,\n.tb-article-comments input:not([type=\"submit\"]) {\n  width: 100%;\n  box-sizing: border-box;\n}\n.tb-article-navigation {\n  width: min(1040px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: 0 0 clamp(72px, 8vw, 104px);\n}\n@media (max-width: 760px) {\n  .tb-article-header { width: min(100% - 32px, 860px); padding-top: 48px; }\n  .tb-article-hero { padding-left: 16px; padding-right: 16px; }\n  .tb-article-hero .wp-block-post-featured-image img { height: 58vw; min-height: 260px; border-radius: 12px; }\n  .tb-article-body { width: min(100% - 36px, 720px); font-size: 17px; }\n  .tb-article-body .alignwide { width: calc(100vw - 32px); }\n  .tb-newsletter-feature { width: calc(100% - 32px) !important; grid-template-columns: 1fr; }\n  .tb-newsletter-feature__image { min-height: 280px; }\n  .tb-newsletter-fields { grid-template-columns: 1fr !important; }\n  .tb-article-author__inner { grid-template-columns: 1fr !important; }\n  .tb-article-author__inner > img { height: 420px; }\n  .tb-article-comments, .tb-article-navigation { width: calc(100% - 32px); }\n}\n\n/* Editorial depth refinement */\n.tb-article-page {\n  background: linear-gradient(180deg, #e8eef2 0, #fbf8f2 720px) !important;\n}\n.tb-article-header {\n  position: relative;\n  z-index: 1;\n  width: min(1040px, calc(100% - 48px));\n  margin: clamp(46px, 6vw, 78px) auto 0;\n  padding: clamp(48px, 6vw, 76px);\n  text-align: left;\n  background: rgba(255,255,255,.96);\n  border: 1px solid rgba(52,76,106,.12);\n  border-radius: 22px;\n  box-shadow: 0 22px 60px rgba(52,76,106,.11);\n  box-sizing: border-box;\n}\n.tb-article-title {\n  max-width: 850px;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n.tb-article-dek {\n  position: relative;\n  max-width: 800px;\n  margin: 36px 0 26px !important;\n  padding: 58px 34px 30px;\n  background: #dfeaed;\n  border-left: 6px solid #d9a21b;\n  border-radius: 12px;\n  box-sizing: border-box;\n  font-size: clamp(17px, 1.7vw, 21px);\n}\n.tb-article-dek::before {\n  content: \"At a glance\";\n  position: absolute;\n  top: 25px;\n  left: 34px;\n  color: #344c6a;\n  font-family: inherit;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: .15em;\n  text-transform: uppercase;\n}\n.tb-article-meta {\n  justify-content: flex-start !important;\n}\n.tb-article-hero {\n  position: relative;\n  z-index: 2;\n  margin-top: -26px;\n}\n.tb-article-body {\n  width: min(860px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: clamp(48px, 6vw, 72px);\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.1);\n  border-radius: 20px;\n  box-shadow: 0 18px 52px rgba(52,76,106,.08);\n  box-sizing: border-box;\n}\n.tb-article-comments {\n  margin-top: 34px !important;\n  margin-bottom: clamp(64px, 8vw, 96px) !important;\n}\n.tb-newsletter-feature {\n  margin-top: 0 !important;\n}\n@media (max-width: 760px) {\n  .tb-article-header {\n    width: calc(100% - 28px);\n    margin-top: 22px;\n    padding: 34px 24px;\n    border-radius: 15px;\n  }\n  .tb-article-dek {\n    padding: 54px 22px 24px;\n  }\n  .tb-article-dek::before {\n    left: 22px;\n  }\n  .tb-article-hero {\n    margin-top: -14px;\n  }\n  .tb-article-body {\n    width: calc(100% - 28px);\n    padding: 36px 22px;\n    border-radius: 15px;\n  }\n}\n\n/* Blog realtor rail and Tanya-color summary */\n.tb-article-dek {\n  background: #f7f1e7 !important;\n  border-left-color: #c77798 !important;\n  color: #344c6a;\n  box-shadow: inset 0 0 0 1px rgba(52,76,106,.08);\n}\n.tb-article-dek::before { color: #344c6a; }\n.tb-blog-layout {\n  width: min(1120px, calc(100% - 48px));\n  margin: 0 auto;\n  display: grid !important;\n  grid-template-columns: minmax(0, 760px) 320px;\n  gap: 42px;\n  align-items: start;\n}\n.tb-blog-main .tb-article-body,\n.tb-blog-main .tb-article-comments {\n  width: 100%;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n.tb-blog-main .tb-article-comments { margin-top: 34px !important; }\n.tb-blog-rail {\n  position: sticky;\n  top: 48px;\n  display: grid;\n  gap: 26px;\n}\n.tb-blog-rail__intro,\n.tb-blog-listings {\n  padding: 26px;\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.12);\n  border-radius: 18px;\n  box-shadow: 0 14px 38px rgba(52,76,106,.08);\n}\n.tb-blog-rail__intro > img {\n  display: block;\n  width: 190px;\n  height: 190px;\n  margin: -4px auto 22px;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 50% 50% 46% 54%;\n  box-shadow: 0 0 0 8px #f2dce4;\n}\n.tb-blog-rail__eyebrow {\n  margin: 0 0 9px;\n  color: #d093aa;\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: .14em;\n  text-transform: uppercase;\n}\n.tb-blog-rail h2 {\n  margin: 0 0 12px;\n  color: #344c6a;\n  font-size: 30px;\n  line-height: 1.05;\n}\n.tb-blog-rail p { line-height: 1.55; }\n.tb-blog-rail__button {\n  display: inline-block;\n  margin-top: 8px;\n  padding: 12px 16px;\n  color: #fff !important;\n  background: #344c6a;\n  border-radius: 4px;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: .08em;\n  text-decoration: none;\n  text-transform: uppercase;\n}\n.tb-listing-grid { display: grid; gap: 18px; margin-top: 20px; }\n.tb-listing-card {\n  display: block;\n  overflow: hidden;\n  color: #25364a !important;\n  background: #fbf8f2;\n  border: 1px solid rgba(52,76,106,.11);\n  border-radius: 12px;\n  text-decoration: none !important;\n  transition: transform .2s ease, box-shadow .2s ease;\n}\n.tb-listing-card:hover {\n  transform: translateY(-3px);\n  box-shadow: 0 12px 26px rgba(52,76,106,.12);\n}\n.tb-listing-card__image {\n  position: relative;\n  display: block;\n  height: 150px;\n}\n.tb-listing-card__image img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n.tb-listing-card__image > span {\n  position: absolute;\n  top: 10px;\n  left: 10px;\n  padding: 6px 9px;\n  color: #344c6a;\n  background: #f7f1e7;\n  border-radius: 999px;\n  font-size: 10px;\n  font-weight: 800;\n  letter-spacing: .1em;\n  text-transform: uppercase;\n}\n.tb-listing-card__body { display: grid; gap: 3px; padding: 15px; }\n.tb-listing-card__body strong { font-family: inherit; font-size: 15px; }\n.tb-listing-card__body b { margin-top: 6px; color: #344c6a; font-size: 18px; }\n.tb-listing-card__body small { color: #6b7580; font-size: 12px; }\n.tb-listing-fallback {\n  display: none;\n  margin-top: 18px;\n  padding: 20px;\n  background: #f7f1e7;\n  border-radius: 12px;\n}\n.tb-listing-grid:not(:has(.tb-listing-card)) + .tb-listing-fallback { display: block; }\n.tb-listing-fallback h3 { margin-top: 0; color: #344c6a; }\n.tb-listing-fallback a,\n.tb-blog-rail__text-link {\n  display: block;\n  margin-top: 12px;\n  color: #344c6a !important;\n  font-weight: 700;\n}\n.tb-blog-rail__text-link { font-size: 13px; }\n@media (max-width: 1020px) {\n  .tb-blog-layout { grid-template-columns: 1fr; }\n  .tb-blog-rail { position: static; grid-template-columns: .8fr 1.2fr; }\n  .tb-listing-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }\n}\n@media (max-width: 700px) {\n  .tb-blog-layout { width: calc(100% - 28px); }\n  .tb-blog-rail { grid-template-columns: 1fr; }\n  .tb-listing-grid { grid-template-columns: 1fr; }\n}\n.tb-article-page{display:grid;grid-template-columns:minmax(0,760px) 320px;column-gap:42px;justify-content:center;} .tb-article-header{grid-column:1 / -1;grid-row:1;} .tb-article-hero{grid-column:1 / -1;grid-row:2;} .tb-article-body{grid-column:1;grid-row:3;width:100%;margin-left:0;margin-right:0;} .tb-blog-rail{grid-column:2;grid-row:3 / span 2;} .tb-article-comments{grid-column:1;grid-row:4;width:100%;margin-left:0!important;margin-right:0!important;} .tb-newsletter-feature{grid-column:1 / -1;grid-row:5;} .tb-article-navigation{grid-column:1 / -1;grid-row:6;} @media(max-width:1020px){.tb-article-page{display:block}.tb-blog-rail{position:static;width:min(860px,calc(100% - 28px));margin:34px auto 72px}.tb-article-body,.tb-article-comments{width:min(860px,calc(100% - 28px));margin-left:auto!important;margin-right:auto!important}.tb-blog-rail{display:grid;grid-template-columns:.8fr 1.2fr}.tb-listing-grid{grid-template-columns:repeat(2,minmax(0,1fr))}} @media(max-width:700px){.tb-blog-rail{grid-template-columns:1fr}.tb-listing-grid{grid-template-columns:1fr}}\n.tb-blog-rail{align-self:start;height:max-content;}\n\n/* Neighborhood Guides automatically use the local-guide layout */\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-hero,\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-blog-rail {\n  display: none !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-page {\n  display: block !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-header {\n  padding-bottom: 30px !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body {\n  width: min(900px, calc(100% - 48px)) !important;\n  margin: 28px auto 0 !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-comments {\n  width: min(900px, calc(100% - 48px)) !important;\n  margin-left: auto !important;\n  margin-right: auto !important;\n}\n@media (max-width: 760px) {\n  body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body,\n  body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-comments {\n    width: calc(100% - 28px) !important;\n  }\n}\n@media (max-width: 760px) { body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body { margin-top: 18px !important; } }\n</style>\n<!-- /wp:html --> <!-- wp:group {\"tagName\":\"main\",\"className\":\"tb-article-page\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group tb-article-page\">\n\n	<!-- wp:group {\"className\":\"tb-article-header\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"920px\"}} -->\n	<header class=\"wp-block-group tb-article-header\">\n		<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-journal-label\"} /-->\n		<!-- wp:post-title {\"level\":1,\"className\":\"tb-article-title\",\"fontSize\":\"x-large\"} /-->\n		<!-- wp:post-excerpt {\"moreText\":\"\",\"excerptLength\":32,\"className\":\"tb-article-dek\"} /-->\n		<!-- wp:group {\"className\":\"tb-article-meta\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"center\"}} -->\n		<div class=\"wp-block-group tb-article-meta\">\n			<!-- wp:paragraph --><p>From Tanya Barrans</p><!-- /wp:paragraph -->\n			<!-- wp:post-date /-->\n		</div>\n		<!-- /wp:group -->\n	</header>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-hero\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-article-hero\">\n		<!-- wp:post-featured-image {\"aspectRatio\":\"16/9\",\"sizeSlug\":\"full\"} /-->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-body\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\",\"wideSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-article-body\">\n		<!-- wp:post-content {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\",\"wideSize\":\"1200px\"}} /-->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-comments\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\"}} -->\n<div class=\"wp-block-group tb-article-comments\">\n<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Join the conversation</h2><!-- /wp:heading -->\n<!-- wp:paragraph --><p>Have a tip, a question, or a story of your own? I’d love to hear it.</p><!-- /wp:paragraph -->\n<!-- wp:comments -->\n<div class=\"wp-block-comments\">\n<!-- wp:comments-title {\"showPostTitle\":false} /-->\n<!-- wp:comment-template -->\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} --><div class=\"wp-block-group\"><!-- wp:avatar {\"size\":48} /--><!-- wp:group --><div class=\"wp-block-group\"><!-- wp:comment-author-name /--><!-- wp:comment-date /--></div><!-- /wp:group --></div><!-- /wp:group -->\n<!-- wp:comment-content /-->\n<!-- wp:comment-reply-link /-->\n<!-- /wp:comment-template -->\n<!-- wp:post-comments-form /-->\n</div>\n<!-- /wp:comments -->\n</div>\n<!-- /wp:group --> <!-- wp:html -->\n<aside class=\"tb-blog-rail\" aria-label=\"About Tanya and current listings\">\n  <section class=\"tb-blog-rail__intro\">\n    <img src=\"/wp-content/uploads/2026/07/about-main.jpg\" alt=\"Tanya Barrans, Puget Sound real estate broker\" loading=\"lazy\">\n    <p class=\"tb-blog-rail__eyebrow\">Your local real estate resource</p>\n    <h2>Hi, I’m Tanya.</h2>\n    <p>I help buyers and sellers make thoughtful moves across Renton and the South Sound—with honest guidance and a little more personality.</p>\n    <a class=\"tb-blog-rail__button\" href=\"/contact/\">Ask Tanya a question</a>\n  </section>\n  <section class=\"tb-blog-listings\">\n    <p class=\"tb-blog-rail__eyebrow\">Currently listed by Tanya</p>\n    <h2>Homes worth a look</h2>\n    <div class=\"tb-listing-grid\">\n      <a class=\"tb-listing-card\" href=\"https://tanyab.johnlscott.com/listing/wa/olympia/5246-yearley-drive-ne-/21476453\" target=\"_blank\" rel=\"noopener\">\n        <span class=\"tb-listing-card__image\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/253/429/2534297.jpg\" alt=\"5246 Yearley Drive NE in Olympia\" loading=\"lazy\"><span>Active</span></span>\n        <span class=\"tb-listing-card__body\"><strong>5246 Yearley Drive NE</strong><small>Olympia, WA</small><b>$389,999</b><small>2 beds · 1.75 baths · 972 sq ft</small></span>\n      </a>\n      <a class=\"tb-listing-card\" href=\"https://tanyab.johnlscott.com/listing/wa/puyallup/18026-75th-avenue-e-/21497093\" target=\"_blank\" rel=\"noopener\">\n        <span class=\"tb-listing-card__image\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/254/658/2546584.jpg\" alt=\"18026 75th Avenue E in Puyallup\" loading=\"lazy\"><span>Active</span></span>\n        <span class=\"tb-listing-card__body\"><strong>18026 75th Avenue E</strong><small>Puyallup, WA</small><b>$545,000</b><small>4 beds · 2.5 baths · 2,201 sq ft</small></span>\n      </a>\n    </div>\n    <div class=\"tb-listing-fallback\">\n      <h3>Nothing active right now—but the search doesn’t stop here.</h3>\n      <p>Browse homes on my John L. Scott site or tell me what you’re hoping to find.</p>\n      <a href=\"https://tanyab.johnlscott.com/search\" target=\"_blank\" rel=\"noopener\">Explore available homes</a>\n      <a href=\"/contact/\">Tell me what you’re looking for</a>\n    </div>\n    <a class=\"tb-blog-rail__text-link\" href=\"https://tanyab.johnlscott.com\" target=\"_blank\" rel=\"noopener\">See all listings on John L. Scott →</a>\n  </section>\n</aside>\n<!-- /wp:html --> <!-- wp:group {\"align\":\"full\",\"className\":\"tb-newsletter-feature\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/newsletter\",\"name\":\"Newsletter Signup\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-newsletter-feature has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg)\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__content tb-reveal\">\n		<!-- wp:paragraph {\"className\":\"tb-script-accent\"} -->\n		<p class=\"tb-script-accent\">Let’s stay in touch</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"x-large\"} -->\n		<h2 class=\"wp-block-heading has-x-large-font-size\">Notes worth opening.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Useful home ideas, local stories, and honest real estate guidance—delivered with no pressure and no polished filler.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:html -->\n		<form class=\"tb-newsletter-form\" novalidate>\n			<div class=\"tb-newsletter-fields\">\n				<label class=\"tb-sr-only\" for=\"tb-nl-name\">First name</label>\n				<input type=\"text\" id=\"tb-nl-name\" name=\"name\" class=\"tb-newsletter-input\" placeholder=\"First name\" autocomplete=\"given-name\" />\n\n				<label class=\"tb-sr-only\" for=\"tb-nl-email\">Email address</label>\n				<input type=\"email\" id=\"tb-nl-email\" name=\"email\" class=\"tb-newsletter-input\" placeholder=\"Email address\" autocomplete=\"email\" required />\n\n				<div class=\"tb-newsletter-hp\" aria-hidden=\"true\">\n					<label for=\"tb-nl-website\">Website</label>\n					<input type=\"text\" id=\"tb-nl-website\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" />\n				</div>\n\n				<button type=\"submit\" class=\"tb-newsletter-submit\">Subscribe</button>\n			</div>\n			<p class=\"tb-newsletter-status\" role=\"status\" aria-live=\"polite\"></p>\n		</form>\n		<!-- /wp:html -->\n\n		<!-- wp:paragraph {\"className\":\"tb-newsletter-feature__privacy\"} -->\n		<p class=\"tb-newsletter-feature__privacy\">No spam. Unsubscribe whenever you like.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-navigation\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<nav class=\"wp-block-group tb-article-navigation\" aria-label=\"Article navigation\">\n		<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\"}} -->\n		<div class=\"wp-block-group\">\n			<!-- wp:post-navigation-link {\"type\":\"previous\",\"label\":\"Previous story\",\"showTitle\":true,\"linkLabel\":true} /-->\n			<!-- wp:post-navigation-link {\"type\":\"next\",\"label\":\"Next story\",\"showTitle\":true,\"linkLabel\":true} /-->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-journal-back-link\"} --><p class=\"has-text-align-center tb-journal-back-link\"><a href=\"/blog/\">Back to the Journal</a></p><!-- /wp:paragraph -->\n	</nav>\n	<!-- /wp:group -->\n\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n', 'Blog Posts', 'Displays a single post on your website unless a custom template has been applied to that post or a dedicated template exists.', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-08-26 20:22:13', '2026-08-26 20:22:13', '', 99, 'https://violet-wren-104886.hostingersite.com/?p=90414', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(90415, 2, '2026-08-26 20:23:32', '2026-08-26 20:23:32', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:html -->\n<style id=\"tb-blog-template-styles\">\n/* Shared Journal article template - applies to every post using Single Posts */\n.tb-article-page {\n  background: #fbf8f2 !important;\n  background-image: none !important;\n  color: #25364a;\n  overflow: hidden;\n} /* Equal spacing below the header when there is no hero image */\n.tb-article-hero:not(:has(.wp-block-post-featured-image img))\n  + .tb-article-body,\n.tb-article-page:has(\n  > .tb-article-hero:not(:has(.wp-block-post-featured-image img))\n) > .tb-blog-rail {\n  margin-top: clamp(32px, 4vw, 56px) !important;\n}\n}\n.tb-article-header {\n  width: min(860px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: clamp(64px, 8vw, 112px) 0 44px;\n  text-align: center;\n}\n.tb-article-title {\n  max-width: 820px;\n  margin-left: auto !important;\n  margin-right: auto !important;\n  line-height: 1.04 !important;\n}\n.tb-article-dek {\n  max-width: 680px;\n  margin: 22px auto 0 !important;\n  font-size: clamp(18px, 2vw, 23px);\n  line-height: 1.55;\n}\n.tb-article-hero {\n  width: 100%;\n  max-width: none !important;\n  padding: 0 24px clamp(48px, 6vw, 80px);\n  background: #fbf8f2 !important;\n  background-image: none !important;\n  box-sizing: border-box;\n}\n.tb-article-hero:not(:has(.wp-block-post-featured-image img)) { display: none !important; } .tb-article-hero .wp-block-post-featured-image {\n  width: min(1040px, 100%);\n  margin: 0 auto !important;\n}\n.tb-article-hero .wp-block-post-featured-image img {\n  display: block;\n  width: 100%;\n  height: clamp(360px, 52vw, 620px);\n  object-fit: cover;\n  border-radius: 18px;\n  box-shadow: 0 18px 52px rgba(52,76,106,.13);\n}\n.tb-article-body {\n  width: min(720px, calc(100% - 48px));\n  margin: 0 auto;\n  padding-bottom: clamp(72px, 9vw, 120px);\n  font-size: 18px;\n  line-height: 1.78;\n}\n.tb-article-body h2 {\n  margin-top: 2.4em;\n  color: #344c6a;\n}\n.tb-article-body .alignwide {\n  width: min(1040px, calc(100vw - 48px));\n  max-width: none;\n  margin-left: 50% !important;\n  transform: translateX(-50%);\n}\n.tb-article-body figure img {\n  border-radius: 14px;\n}\n.tb-article-explore {\n  padding: clamp(64px, 8vw, 96px) 24px !important;\n  background: #344c6a !important;\n}\n.tb-article-explore .tb-page-shell {\n  width: min(940px, 100%);\n  margin: 0 auto;\n}\n.tb-article-explore__links {\n  max-width: 820px;\n  margin: 34px auto 0;\n}\n.tb-newsletter-feature {\n  width: min(1040px, calc(100% - 48px)) !important;\n  max-width: 1040px !important;\n  min-height: 420px;\n  margin: clamp(72px, 9vw, 112px) auto !important;\n  display: grid !important;\n  grid-template-columns: minmax(300px, .9fr) minmax(420px, 1.25fr);\n  overflow: hidden;\n  border-radius: 18px;\n  box-shadow: 0 18px 55px rgba(52,76,106,.12);\n}\n.tb-newsletter-feature__image {\n  min-height: 420px;\n  background-size: cover !important;\n  background-position: center !important;\n}\n.tb-newsletter-feature__content {\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  padding: clamp(44px, 6vw, 72px) !important;\n}\n.tb-newsletter-fields {\n  display: grid !important;\n  grid-template-columns: 1fr 1fr auto;\n  gap: 12px;\n}\n.tb-article-author {\n  padding: clamp(72px, 9vw, 112px) 24px !important;\n  background: #f1e8dc !important;\n}\n.tb-article-author__inner {\n  width: min(1000px, 100%);\n  margin: 0 auto;\n  display: grid !important;\n  grid-template-columns: minmax(280px, 380px) 1fr;\n  gap: clamp(42px, 7vw, 82px);\n  align-items: center;\n}\n.tb-article-author__inner > img {\n  width: 100%;\n  height: 500px;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 16px;\n  box-shadow: 0 16px 42px rgba(52,76,106,.14);\n}\n.tb-article-author h2 {\n  max-width: 560px;\n  font-size: clamp(36px, 4vw, 54px);\n  line-height: 1.05;\n}\n.tb-article-comments {\n  width: min(820px, calc(100% - 48px));\n  margin: clamp(64px, 8vw, 96px) auto !important;\n  padding: clamp(42px, 6vw, 68px) !important;\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.14);\n  border-radius: 18px;\n  box-shadow: 0 14px 42px rgba(52,76,106,.08);\n  box-sizing: border-box;\n}\n.tb-article-comments textarea,\n.tb-article-comments input:not([type=\"submit\"]) {\n  width: 100%;\n  box-sizing: border-box;\n}\n.tb-article-navigation {\n  width: min(1040px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: 0 0 clamp(72px, 8vw, 104px);\n}\n@media (max-width: 760px) {\n  .tb-article-header { width: min(100% - 32px, 860px); padding-top: 48px; }\n  .tb-article-hero { padding-left: 16px; padding-right: 16px; }\n  .tb-article-hero .wp-block-post-featured-image img { height: 58vw; min-height: 260px; border-radius: 12px; }\n  .tb-article-body { width: min(100% - 36px, 720px); font-size: 17px; }\n  .tb-article-body .alignwide { width: calc(100vw - 32px); }\n  .tb-newsletter-feature { width: calc(100% - 32px) !important; grid-template-columns: 1fr; }\n  .tb-newsletter-feature__image { min-height: 280px; }\n  .tb-newsletter-fields { grid-template-columns: 1fr !important; }\n  .tb-article-author__inner { grid-template-columns: 1fr !important; }\n  .tb-article-author__inner > img { height: 420px; }\n  .tb-article-comments, .tb-article-navigation { width: calc(100% - 32px); }\n}\n\n/* Editorial depth refinement */\n.tb-article-page {\n  background: linear-gradient(180deg, #e8eef2 0, #fbf8f2 720px) !important;\n}\n.tb-article-header {\n  position: relative;\n  z-index: 1;\n  width: min(1040px, calc(100% - 48px));\n  margin: clamp(46px, 6vw, 78px) auto 0;\n  padding: clamp(48px, 6vw, 76px);\n  text-align: left;\n  background: rgba(255,255,255,.96);\n  border: 1px solid rgba(52,76,106,.12);\n  border-radius: 22px;\n  box-shadow: 0 22px 60px rgba(52,76,106,.11);\n  box-sizing: border-box;\n}\n.tb-article-title {\n  max-width: 850px;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n.tb-article-dek {\n  position: relative;\n  max-width: 800px;\n  margin: 36px 0 26px !important;\n  padding: 58px 34px 30px;\n  background: #dfeaed;\n  border-left: 6px solid #d9a21b;\n  border-radius: 12px;\n  box-sizing: border-box;\n  font-size: clamp(17px, 1.7vw, 21px);\n}\n.tb-article-dek::before {\n  content: \"At a glance\";\n  position: absolute;\n  top: 25px;\n  left: 34px;\n  color: #344c6a;\n  font-family: inherit;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: .15em;\n  text-transform: uppercase;\n}\n.tb-article-meta {\n  justify-content: flex-start !important;\n}\n.tb-article-hero {\n  position: relative;\n  z-index: 2;\n  margin-top: -26px;\n}\n.tb-article-body {\n  width: min(860px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: clamp(48px, 6vw, 72px);\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.1);\n  border-radius: 20px;\n  box-shadow: 0 18px 52px rgba(52,76,106,.08);\n  box-sizing: border-box;\n}\n.tb-article-comments {\n  margin-top: 34px !important;\n  margin-bottom: clamp(64px, 8vw, 96px) !important;\n}\n.tb-newsletter-feature {\n  margin-top: 0 !important;\n}\n@media (max-width: 760px) {\n  .tb-article-header {\n    width: calc(100% - 28px);\n    margin-top: 22px;\n    padding: 34px 24px;\n    border-radius: 15px;\n  }\n  .tb-article-dek {\n    padding: 54px 22px 24px;\n  }\n  .tb-article-dek::before {\n    left: 22px;\n  }\n  .tb-article-hero {\n    margin-top: -14px;\n  }\n  .tb-article-body {\n    width: calc(100% - 28px);\n    padding: 36px 22px;\n    border-radius: 15px;\n  }\n}\n\n/* Blog realtor rail and Tanya-color summary */\n.tb-article-dek {\n  background: #f7f1e7 !important;\n  border-left-color: #c77798 !important;\n  color: #344c6a;\n  box-shadow: inset 0 0 0 1px rgba(52,76,106,.08);\n}\n.tb-article-dek::before { color: #344c6a; }\n.tb-blog-layout {\n  width: min(1120px, calc(100% - 48px));\n  margin: 0 auto;\n  display: grid !important;\n  grid-template-columns: minmax(0, 760px) 320px;\n  gap: 42px;\n  align-items: start;\n}\n.tb-blog-main .tb-article-body,\n.tb-blog-main .tb-article-comments {\n  width: 100%;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n.tb-blog-main .tb-article-comments { margin-top: 34px !important; }\n.tb-blog-rail {\n  position: sticky;\n  top: 48px;\n  display: grid;\n  gap: 26px;\n}\n.tb-blog-rail__intro,\n.tb-blog-listings {\n  padding: 26px;\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.12);\n  border-radius: 18px;\n  box-shadow: 0 14px 38px rgba(52,76,106,.08);\n}\n.tb-blog-rail__intro > img {\n  display: block;\n  width: 190px;\n  height: 190px;\n  margin: -4px auto 22px;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 50% 50% 46% 54%;\n  box-shadow: 0 0 0 8px #f2dce4;\n}\n.tb-blog-rail__eyebrow {\n  margin: 0 0 9px;\n  color: #d093aa;\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: .14em;\n  text-transform: uppercase;\n}\n.tb-blog-rail h2 {\n  margin: 0 0 12px;\n  color: #344c6a;\n  font-size: 30px;\n  line-height: 1.05;\n}\n.tb-blog-rail p { line-height: 1.55; }\n.tb-blog-rail__button {\n  display: inline-block;\n  margin-top: 8px;\n  padding: 12px 16px;\n  color: #fff !important;\n  background: #344c6a;\n  border-radius: 4px;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: .08em;\n  text-decoration: none;\n  text-transform: uppercase;\n}\n.tb-listing-grid { display: grid; gap: 18px; margin-top: 20px; }\n.tb-listing-card {\n  display: block;\n  overflow: hidden;\n  color: #25364a !important;\n  background: #fbf8f2;\n  border: 1px solid rgba(52,76,106,.11);\n  border-radius: 12px;\n  text-decoration: none !important;\n  transition: transform .2s ease, box-shadow .2s ease;\n}\n.tb-listing-card:hover {\n  transform: translateY(-3px);\n  box-shadow: 0 12px 26px rgba(52,76,106,.12);\n}\n.tb-listing-card__image {\n  position: relative;\n  display: block;\n  height: 150px;\n}\n.tb-listing-card__image img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n.tb-listing-card__image > span {\n  position: absolute;\n  top: 10px;\n  left: 10px;\n  padding: 6px 9px;\n  color: #344c6a;\n  background: #f7f1e7;\n  border-radius: 999px;\n  font-size: 10px;\n  font-weight: 800;\n  letter-spacing: .1em;\n  text-transform: uppercase;\n}\n.tb-listing-card__body { display: grid; gap: 3px; padding: 15px; }\n.tb-listing-card__body strong { font-family: inherit; font-size: 15px; }\n.tb-listing-card__body b { margin-top: 6px; color: #344c6a; font-size: 18px; }\n.tb-listing-card__body small { color: #6b7580; font-size: 12px; }\n.tb-listing-fallback {\n  display: none;\n  margin-top: 18px;\n  padding: 20px;\n  background: #f7f1e7;\n  border-radius: 12px;\n}\n.tb-listing-grid:not(:has(.tb-listing-card)) + .tb-listing-fallback { display: block; }\n.tb-listing-fallback h3 { margin-top: 0; color: #344c6a; }\n.tb-listing-fallback a,\n.tb-blog-rail__text-link {\n  display: block;\n  margin-top: 12px;\n  color: #344c6a !important;\n  font-weight: 700;\n}\n.tb-blog-rail__text-link { font-size: 13px; }\n@media (max-width: 1020px) {\n  .tb-blog-layout { grid-template-columns: 1fr; }\n  .tb-blog-rail { position: static; grid-template-columns: .8fr 1.2fr; }\n  .tb-listing-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }\n}\n@media (max-width: 700px) {\n  .tb-blog-layout { width: calc(100% - 28px); }\n  .tb-blog-rail { grid-template-columns: 1fr; }\n  .tb-listing-grid { grid-template-columns: 1fr; }\n}\n.tb-article-page{display:grid;grid-template-columns:minmax(0,760px) 320px;column-gap:42px;justify-content:center;} .tb-article-header{grid-column:1 / -1;grid-row:1;} .tb-article-hero{grid-column:1 / -1;grid-row:2;} .tb-article-body{grid-column:1;grid-row:3;width:100%;margin-left:0;margin-right:0;} .tb-blog-rail{grid-column:2;grid-row:3 / span 2;} .tb-article-comments{grid-column:1;grid-row:4;width:100%;margin-left:0!important;margin-right:0!important;} .tb-newsletter-feature{grid-column:1 / -1;grid-row:5;} .tb-article-navigation{grid-column:1 / -1;grid-row:6;} @media(max-width:1020px){.tb-article-page{display:block}.tb-blog-rail{position:static;width:min(860px,calc(100% - 28px));margin:34px auto 72px}.tb-article-body,.tb-article-comments{width:min(860px,calc(100% - 28px));margin-left:auto!important;margin-right:auto!important}.tb-blog-rail{display:grid;grid-template-columns:.8fr 1.2fr}.tb-listing-grid{grid-template-columns:repeat(2,minmax(0,1fr))}} @media(max-width:700px){.tb-blog-rail{grid-template-columns:1fr}.tb-listing-grid{grid-template-columns:1fr}}\n.tb-blog-rail{align-self:start;height:max-content;}\n\n/* Neighborhood Guides automatically use the local-guide layout */\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-hero,\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-blog-rail {\n  display: none !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-page {\n  display: block !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-header {\n  padding-bottom: 30px !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body {\n  width: min(900px, calc(100% - 48px)) !important;\n  margin: 28px auto 0 !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-comments {\n  width: min(900px, calc(100% - 48px)) !important;\n  margin-left: auto !important;\n  margin-right: auto !important;\n}\n@media (max-width: 760px) {\n  body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body,\n  body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-comments {\n    width: calc(100% - 28px) !important;\n  }\n}\n@media (max-width: 760px) { body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body { margin-top: 18px !important; } }\n</style>\n<!-- /wp:html --> <!-- wp:group {\"tagName\":\"main\",\"className\":\"tb-article-page\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group tb-article-page\">\n\n	<!-- wp:group {\"className\":\"tb-article-header\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"920px\"}} -->\n	<header class=\"wp-block-group tb-article-header\">\n		<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-journal-label\"} /-->\n		<!-- wp:post-title {\"level\":1,\"className\":\"tb-article-title\",\"fontSize\":\"x-large\"} /-->\n		<!-- wp:post-excerpt {\"moreText\":\"\",\"excerptLength\":32,\"className\":\"tb-article-dek\"} /-->\n		<!-- wp:group {\"className\":\"tb-article-meta\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"center\"}} -->\n		<div class=\"wp-block-group tb-article-meta\">\n			<!-- wp:paragraph --><p>From Tanya Barrans</p><!-- /wp:paragraph -->\n			<!-- wp:post-date /-->\n		</div>\n		<!-- /wp:group -->\n	</header>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-hero\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-article-hero\">\n		<!-- wp:post-featured-image {\"aspectRatio\":\"16/9\",\"sizeSlug\":\"full\"} /-->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-body\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\",\"wideSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-article-body\">\n		<!-- wp:post-content {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\",\"wideSize\":\"1200px\"}} /-->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-comments\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\"}} -->\n<div class=\"wp-block-group tb-article-comments\">\n<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Join the conversation</h2><!-- /wp:heading -->\n<!-- wp:paragraph --><p>Have a tip, a question, or a story of your own? I’d love to hear it.</p><!-- /wp:paragraph -->\n<!-- wp:comments -->\n<div class=\"wp-block-comments\">\n<!-- wp:comments-title {\"showPostTitle\":false} /-->\n<!-- wp:comment-template -->\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} --><div class=\"wp-block-group\"><!-- wp:avatar {\"size\":48} /--><!-- wp:group --><div class=\"wp-block-group\"><!-- wp:comment-author-name /--><!-- wp:comment-date /--></div><!-- /wp:group --></div><!-- /wp:group -->\n<!-- wp:comment-content /-->\n<!-- wp:comment-reply-link /-->\n<!-- /wp:comment-template -->\n<!-- wp:post-comments-form /-->\n</div>\n<!-- /wp:comments -->\n</div>\n<!-- /wp:group --> <!-- wp:html -->\n<aside class=\"tb-blog-rail\" aria-label=\"About Tanya and current listings\">\n  <section class=\"tb-blog-rail__intro\">\n    <img src=\"/wp-content/uploads/2026/07/about-main.jpg\" alt=\"Tanya Barrans, Puget Sound real estate broker\" loading=\"lazy\">\n    <p class=\"tb-blog-rail__eyebrow\">Your local real estate resource</p>\n    <h2>Hi, I’m Tanya.</h2>\n    <p>I help buyers and sellers make thoughtful moves across Renton and the South Sound—with honest guidance and a little more personality.</p>\n    <a class=\"tb-blog-rail__button\" href=\"/contact/\">Ask Tanya a question</a>\n  </section>\n  <section class=\"tb-blog-listings\">\n    <p class=\"tb-blog-rail__eyebrow\">Currently listed by Tanya</p>\n    <h2>Homes worth a look</h2>\n    <div class=\"tb-listing-grid\">\n      <a class=\"tb-listing-card\" href=\"https://tanyab.johnlscott.com/listing/wa/olympia/5246-yearley-drive-ne-/21476453\" target=\"_blank\" rel=\"noopener\">\n        <span class=\"tb-listing-card__image\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/253/429/2534297.jpg\" alt=\"5246 Yearley Drive NE in Olympia\" loading=\"lazy\"><span>Active</span></span>\n        <span class=\"tb-listing-card__body\"><strong>5246 Yearley Drive NE</strong><small>Olympia, WA</small><b>$389,999</b><small>2 beds · 1.75 baths · 972 sq ft</small></span>\n      </a>\n      <a class=\"tb-listing-card\" href=\"https://tanyab.johnlscott.com/listing/wa/puyallup/18026-75th-avenue-e-/21497093\" target=\"_blank\" rel=\"noopener\">\n        <span class=\"tb-listing-card__image\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/254/658/2546584.jpg\" alt=\"18026 75th Avenue E in Puyallup\" loading=\"lazy\"><span>Active</span></span>\n        <span class=\"tb-listing-card__body\"><strong>18026 75th Avenue E</strong><small>Puyallup, WA</small><b>$545,000</b><small>4 beds · 2.5 baths · 2,201 sq ft</small></span>\n      </a>\n    </div>\n    <div class=\"tb-listing-fallback\">\n      <h3>Nothing active right now—but the search doesn’t stop here.</h3>\n      <p>Browse homes on my John L. Scott site or tell me what you’re hoping to find.</p>\n      <a href=\"https://tanyab.johnlscott.com/search\" target=\"_blank\" rel=\"noopener\">Explore available homes</a>\n      <a href=\"/contact/\">Tell me what you’re looking for</a>\n    </div>\n    <a class=\"tb-blog-rail__text-link\" href=\"https://tanyab.johnlscott.com\" target=\"_blank\" rel=\"noopener\">See all listings on John L. Scott →</a>\n  </section>\n</aside>\n<!-- /wp:html --> <!-- wp:group {\"align\":\"full\",\"className\":\"tb-newsletter-feature\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/newsletter\",\"name\":\"Newsletter Signup\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-newsletter-feature has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg)\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__content tb-reveal\">\n		<!-- wp:paragraph {\"className\":\"tb-script-accent\"} -->\n		<p class=\"tb-script-accent\">Let’s stay in touch</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"x-large\"} -->\n		<h2 class=\"wp-block-heading has-x-large-font-size\">Notes worth opening.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Useful home ideas, local stories, and honest real estate guidance—delivered with no pressure and no polished filler.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:html -->\n		<form class=\"tb-newsletter-form\" novalidate>\n			<div class=\"tb-newsletter-fields\">\n				<label class=\"tb-sr-only\" for=\"tb-nl-name\">First name</label>\n				<input type=\"text\" id=\"tb-nl-name\" name=\"name\" class=\"tb-newsletter-input\" placeholder=\"First name\" autocomplete=\"given-name\" />\n\n				<label class=\"tb-sr-only\" for=\"tb-nl-email\">Email address</label>\n				<input type=\"email\" id=\"tb-nl-email\" name=\"email\" class=\"tb-newsletter-input\" placeholder=\"Email address\" autocomplete=\"email\" required />\n\n				<div class=\"tb-newsletter-hp\" aria-hidden=\"true\">\n					<label for=\"tb-nl-website\">Website</label>\n					<input type=\"text\" id=\"tb-nl-website\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" />\n				</div>\n\n				<button type=\"submit\" class=\"tb-newsletter-submit\">Subscribe</button>\n			</div>\n			<p class=\"tb-newsletter-status\" role=\"status\" aria-live=\"polite\"></p>\n		</form>\n		<!-- /wp:html -->\n\n		<!-- wp:paragraph {\"className\":\"tb-newsletter-feature__privacy\"} -->\n		<p class=\"tb-newsletter-feature__privacy\">No spam. Unsubscribe whenever you like.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-navigation\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<nav class=\"wp-block-group tb-article-navigation\" aria-label=\"Article navigation\">\n		<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\"}} -->\n		<div class=\"wp-block-group\">\n			<!-- wp:post-navigation-link {\"type\":\"previous\",\"label\":\"Previous story\",\"showTitle\":true,\"linkLabel\":true} /-->\n			<!-- wp:post-navigation-link {\"type\":\"next\",\"label\":\"Next story\",\"showTitle\":true,\"linkLabel\":true} /-->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-journal-back-link\"} --><p class=\"has-text-align-center tb-journal-back-link\"><a href=\"/blog/\">Back to the Journal</a></p><!-- /wp:paragraph -->\n	</nav>\n	<!-- /wp:group -->\n\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n', 'Blog Posts', 'Displays a single post on your website unless a custom template has been applied to that post or a dedicated template exists.', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-08-26 20:23:32', '2026-08-26 20:23:32', '', 99, 'https://violet-wren-104886.hostingersite.com/?p=90415', 0, 'revision', '', 0),
(90416, 2, '2026-08-26 20:26:04', '2026-08-26 20:26:04', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:html -->\n<style id=\"tb-blog-template-styles\">\n/* Shared Journal article template - applies to every post using Single Posts */\n.tb-article-page {\n  background: #fbf8f2 !important;\n  background-image: none !important;\n  color: #25364a;\n  overflow: hidden;\n}\n\n.tb-article-header {\n  width: min(860px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: clamp(64px, 8vw, 112px) 0 44px;\n  text-align: center;\n}\n.tb-article-title {\n  max-width: 820px;\n  margin-left: auto !important;\n  margin-right: auto !important;\n  line-height: 1.04 !important;\n}\n.tb-article-dek {\n  max-width: 680px;\n  margin: 22px auto 0 !important;\n  font-size: clamp(18px, 2vw, 23px);\n  line-height: 1.55;\n}\n.tb-article-hero {\n  width: 100%;\n  max-width: none !important;\n  padding: 0 24px clamp(48px, 6vw, 80px);\n  background: #fbf8f2 !important;\n  background-image: none !important;\n  box-sizing: border-box;\n}\n.tb-article-hero:not(:has(.wp-block-post-featured-image img)) { display: none !important; } .tb-article-hero .wp-block-post-featured-image {\n  width: min(1040px, 100%);\n  margin: 0 auto !important;\n}\n.tb-article-hero .wp-block-post-featured-image img {\n  display: block;\n  width: 100%;\n  height: clamp(360px, 52vw, 620px);\n  object-fit: cover;\n  border-radius: 18px;\n  box-shadow: 0 18px 52px rgba(52,76,106,.13);\n}\n.tb-article-body {\n  width: min(720px, calc(100% - 48px));\n  margin: 0 auto;\n  padding-bottom: clamp(72px, 9vw, 120px);\n  font-size: 18px;\n  line-height: 1.78;\n}\n.tb-article-body h2 {\n  margin-top: 2.4em;\n  color: #344c6a;\n}\n.tb-article-body .alignwide {\n  width: min(1040px, calc(100vw - 48px));\n  max-width: none;\n  margin-left: 50% !important;\n  transform: translateX(-50%);\n}\n.tb-article-body figure img {\n  border-radius: 14px;\n}\n.tb-article-explore {\n  padding: clamp(64px, 8vw, 96px) 24px !important;\n  background: #344c6a !important;\n}\n.tb-article-explore .tb-page-shell {\n  width: min(940px, 100%);\n  margin: 0 auto;\n}\n.tb-article-explore__links {\n  max-width: 820px;\n  margin: 34px auto 0;\n}\n.tb-newsletter-feature {\n  width: min(1040px, calc(100% - 48px)) !important;\n  max-width: 1040px !important;\n  min-height: 420px;\n  margin: clamp(72px, 9vw, 112px) auto !important;\n  display: grid !important;\n  grid-template-columns: minmax(300px, .9fr) minmax(420px, 1.25fr);\n  overflow: hidden;\n  border-radius: 18px;\n  box-shadow: 0 18px 55px rgba(52,76,106,.12);\n}\n.tb-newsletter-feature__image {\n  min-height: 420px;\n  background-size: cover !important;\n  background-position: center !important;\n}\n.tb-newsletter-feature__content {\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  padding: clamp(44px, 6vw, 72px) !important;\n}\n.tb-newsletter-fields {\n  display: grid !important;\n  grid-template-columns: 1fr 1fr auto;\n  gap: 12px;\n}\n.tb-article-author {\n  padding: clamp(72px, 9vw, 112px) 24px !important;\n  background: #f1e8dc !important;\n}\n.tb-article-author__inner {\n  width: min(1000px, 100%);\n  margin: 0 auto;\n  display: grid !important;\n  grid-template-columns: minmax(280px, 380px) 1fr;\n  gap: clamp(42px, 7vw, 82px);\n  align-items: center;\n}\n.tb-article-author__inner > img {\n  width: 100%;\n  height: 500px;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 16px;\n  box-shadow: 0 16px 42px rgba(52,76,106,.14);\n}\n.tb-article-author h2 {\n  max-width: 560px;\n  font-size: clamp(36px, 4vw, 54px);\n  line-height: 1.05;\n}\n.tb-article-comments {\n  width: min(820px, calc(100% - 48px));\n  margin: clamp(64px, 8vw, 96px) auto !important;\n  padding: clamp(42px, 6vw, 68px) !important;\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.14);\n  border-radius: 18px;\n  box-shadow: 0 14px 42px rgba(52,76,106,.08);\n  box-sizing: border-box;\n}\n.tb-article-comments textarea,\n.tb-article-comments input:not([type=\"submit\"]) {\n  width: 100%;\n  box-sizing: border-box;\n}\n.tb-article-navigation {\n  width: min(1040px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: 0 0 clamp(72px, 8vw, 104px);\n}\n@media (max-width: 760px) {\n  .tb-article-header { width: min(100% - 32px, 860px); padding-top: 48px; }\n  .tb-article-hero { padding-left: 16px; padding-right: 16px; }\n  .tb-article-hero .wp-block-post-featured-image img { height: 58vw; min-height: 260px; border-radius: 12px; }\n  .tb-article-body { width: min(100% - 36px, 720px); font-size: 17px; }\n  .tb-article-body .alignwide { width: calc(100vw - 32px); }\n  .tb-newsletter-feature { width: calc(100% - 32px) !important; grid-template-columns: 1fr; }\n  .tb-newsletter-feature__image { min-height: 280px; }\n  .tb-newsletter-fields { grid-template-columns: 1fr !important; }\n  .tb-article-author__inner { grid-template-columns: 1fr !important; }\n  .tb-article-author__inner > img { height: 420px; }\n  .tb-article-comments, .tb-article-navigation { width: calc(100% - 32px); }\n}\n\n/* Editorial depth refinement */\n.tb-article-page {\n  background: linear-gradient(180deg, #e8eef2 0, #fbf8f2 720px) !important;\n}\n.tb-article-header {\n  position: relative;\n  z-index: 1;\n  width: min(1040px, calc(100% - 48px));\n  margin: clamp(46px, 6vw, 78px) auto 0;\n  padding: clamp(48px, 6vw, 76px);\n  text-align: left;\n  background: rgba(255,255,255,.96);\n  border: 1px solid rgba(52,76,106,.12);\n  border-radius: 22px;\n  box-shadow: 0 22px 60px rgba(52,76,106,.11);\n  box-sizing: border-box;\n}\n.tb-article-title {\n  max-width: 850px;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n.tb-article-dek {\n  position: relative;\n  max-width: 800px;\n  margin: 36px 0 26px !important;\n  padding: 58px 34px 30px;\n  background: #dfeaed;\n  border-left: 6px solid #d9a21b;\n  border-radius: 12px;\n  box-sizing: border-box;\n  font-size: clamp(17px, 1.7vw, 21px);\n}\n.tb-article-dek::before {\n  content: \"At a glance\";\n  position: absolute;\n  top: 25px;\n  left: 34px;\n  color: #344c6a;\n  font-family: inherit;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: .15em;\n  text-transform: uppercase;\n}\n.tb-article-meta {\n  justify-content: flex-start !important;\n}\n.tb-article-hero {\n  position: relative;\n  z-index: 2;\n  margin-top: -26px;\n}\n.tb-article-body {\n  width: min(860px, calc(100% - 48px));\n  margin: 0 auto;\n  padding: clamp(48px, 6vw, 72px);\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.1);\n  border-radius: 20px;\n  box-shadow: 0 18px 52px rgba(52,76,106,.08);\n  box-sizing: border-box;\n}\n.tb-article-comments {\n  margin-top: 34px !important;\n  margin-bottom: clamp(64px, 8vw, 96px) !important;\n}\n.tb-newsletter-feature {\n  margin-top: 0 !important;\n}\n@media (max-width: 760px) {\n  .tb-article-header {\n    width: calc(100% - 28px);\n    margin-top: 22px;\n    padding: 34px 24px;\n    border-radius: 15px;\n  }\n  .tb-article-dek {\n    padding: 54px 22px 24px;\n  }\n  .tb-article-dek::before {\n    left: 22px;\n  }\n  .tb-article-hero {\n    margin-top: -14px;\n  }\n  .tb-article-body {\n    width: calc(100% - 28px);\n    padding: 36px 22px;\n    border-radius: 15px;\n  }\n}\n\n/* Blog realtor rail and Tanya-color summary */\n.tb-article-dek {\n  background: #f7f1e7 !important;\n  border-left-color: #c77798 !important;\n  color: #344c6a;\n  box-shadow: inset 0 0 0 1px rgba(52,76,106,.08);\n}\n.tb-article-dek::before { color: #344c6a; }\n.tb-blog-layout {\n  width: min(1120px, calc(100% - 48px));\n  margin: 0 auto;\n  display: grid !important;\n  grid-template-columns: minmax(0, 760px) 320px;\n  gap: 42px;\n  align-items: start;\n}\n.tb-blog-main .tb-article-body,\n.tb-blog-main .tb-article-comments {\n  width: 100%;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n.tb-blog-main .tb-article-comments { margin-top: 34px !important; }\n.tb-blog-rail {\n  position: sticky;\n  top: 48px;\n  display: grid;\n  gap: 26px;\n}\n.tb-blog-rail__intro,\n.tb-blog-listings {\n  padding: 26px;\n  background: #fff;\n  border: 1px solid rgba(52,76,106,.12);\n  border-radius: 18px;\n  box-shadow: 0 14px 38px rgba(52,76,106,.08);\n}\n.tb-blog-rail__intro > img {\n  display: block;\n  width: 190px;\n  height: 190px;\n  margin: -4px auto 22px;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 50% 50% 46% 54%;\n  box-shadow: 0 0 0 8px #344c6a;\n}\n.tb-blog-rail__eyebrow {\n  margin: 0 0 9px;\n  color: #d093aa;\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: .14em;\n  text-transform: uppercase;\n}\n.tb-blog-rail h2 {\n  margin: 0 0 12px;\n  color: #344c6a;\n  font-size: 30px;\n  line-height: 1.05;\n}\n.tb-blog-rail p { line-height: 1.55; }\n.tb-blog-rail__button {\n  display: inline-block;\n  margin-top: 8px;\n  padding: 12px 16px;\n  color: #fff !important;\n  background: #344c6a;\n  border-radius: 4px;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: .08em;\n  text-decoration: none;\n  text-transform: uppercase;\n}\n.tb-listing-grid { display: grid; gap: 18px; margin-top: 20px; }\n.tb-listing-card {\n  display: block;\n  overflow: hidden;\n  color: #25364a !important;\n  background: #fbf8f2;\n  border: 1px solid rgba(52,76,106,.11);\n  border-radius: 12px;\n  text-decoration: none !important;\n  transition: transform .2s ease, box-shadow .2s ease;\n}\n.tb-listing-card:hover {\n  transform: translateY(-3px);\n  box-shadow: 0 12px 26px rgba(52,76,106,.12);\n}\n.tb-listing-card__image {\n  position: relative;\n  display: block;\n  height: 150px;\n}\n.tb-listing-card__image img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n.tb-listing-card__image > span {\n  position: absolute;\n  top: 10px;\n  left: 10px;\n  padding: 6px 9px;\n  color: #344c6a;\n  background: #f7f1e7;\n  border-radius: 999px;\n  font-size: 10px;\n  font-weight: 800;\n  letter-spacing: .1em;\n  text-transform: uppercase;\n}\n.tb-listing-card__body { display: grid; gap: 3px; padding: 15px; }\n.tb-listing-card__body strong { font-family: inherit; font-size: 15px; }\n.tb-listing-card__body b { margin-top: 6px; color: #344c6a; font-size: 18px; }\n.tb-listing-card__body small { color: #6b7580; font-size: 12px; }\n.tb-listing-fallback {\n  display: none;\n  margin-top: 18px;\n  padding: 20px;\n  background: #f7f1e7;\n  border-radius: 12px;\n}\n.tb-listing-grid:not(:has(.tb-listing-card)) + .tb-listing-fallback { display: block; }\n.tb-listing-fallback h3 { margin-top: 0; color: #344c6a; }\n.tb-listing-fallback a,\n.tb-blog-rail__text-link {\n  display: block;\n  margin-top: 12px;\n  color: #344c6a !important;\n  font-weight: 700;\n}\n.tb-blog-rail__text-link { font-size: 13px; }\n@media (max-width: 1020px) {\n  .tb-blog-layout { grid-template-columns: 1fr; }\n  .tb-blog-rail { position: static; grid-template-columns: .8fr 1.2fr; }\n  .tb-listing-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }\n}\n@media (max-width: 700px) {\n  .tb-blog-layout { width: calc(100% - 28px); }\n  .tb-blog-rail { grid-template-columns: 1fr; }\n  .tb-listing-grid { grid-template-columns: 1fr; }\n}\n.tb-article-page{display:grid;grid-template-columns:minmax(0,760px) 320px;column-gap:42px;justify-content:center;} .tb-article-header{grid-column:1 / -1;grid-row:1;} .tb-article-hero{grid-column:1 / -1;grid-row:2;} .tb-article-body{grid-column:1;grid-row:3;width:100%;margin-left:0;margin-right:0;} .tb-blog-rail{grid-column:2;grid-row:3 / span 2;} .tb-article-comments{grid-column:1;grid-row:4;width:100%;margin-left:0!important;margin-right:0!important;} .tb-newsletter-feature{grid-column:1 / -1;grid-row:5;} .tb-article-navigation{grid-column:1 / -1;grid-row:6;} @media(max-width:1020px){.tb-article-page{display:block}.tb-blog-rail{position:static;width:min(860px,calc(100% - 28px));margin:34px auto 72px}.tb-article-body,.tb-article-comments{width:min(860px,calc(100% - 28px));margin-left:auto!important;margin-right:auto!important}.tb-blog-rail{display:grid;grid-template-columns:.8fr 1.2fr}.tb-listing-grid{grid-template-columns:repeat(2,minmax(0,1fr))}} @media(max-width:700px){.tb-blog-rail{grid-template-columns:1fr}.tb-listing-grid{grid-template-columns:1fr}}\n.tb-blog-rail{align-self:start;height:max-content;}\n\n/* Neighborhood Guides automatically use the local-guide layout */\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-hero,\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-blog-rail {\n  display: none !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-page {\n  display: block !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-header {\n  padding-bottom: 30px !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body {\n  width: min(900px, calc(100% - 48px)) !important;\n  margin: 28px auto 0 !important;\n}\nbody:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-comments {\n  width: min(900px, calc(100% - 48px)) !important;\n  margin-left: auto !important;\n  margin-right: auto !important;\n}\n@media (max-width: 760px) {\n  body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body,\n  body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-comments {\n    width: calc(100% - 28px) !important;\n  }\n}\n@media (max-width: 760px) { body:has(.tb-article-header a[href*=\"/category/neighborhood-guides/\"]) .tb-article-body { margin-top: 18px !important; } }\n\n/* Equal spacing when there is no hero image */\n.tb-article-page:not(:has(> .tb-article-hero img))\n  > .tb-article-body,\n.tb-article-page:not(:has(> .tb-article-hero img))\n  > .tb-blog-rail {\n  margin-top: clamp(32px, 4vw, 56px) !important;\n}\n</style>\n<!-- /wp:html --> <!-- wp:group {\"tagName\":\"main\",\"className\":\"tb-article-page\",\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<main class=\"wp-block-group tb-article-page\">\n\n	<!-- wp:group {\"className\":\"tb-article-header\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"920px\"}} -->\n	<header class=\"wp-block-group tb-article-header\">\n		<!-- wp:post-terms {\"term\":\"category\",\"className\":\"tb-journal-label\"} /-->\n		<!-- wp:post-title {\"level\":1,\"className\":\"tb-article-title\",\"fontSize\":\"x-large\"} /-->\n		<!-- wp:post-excerpt {\"moreText\":\"\",\"excerptLength\":32,\"className\":\"tb-article-dek\"} /-->\n		<!-- wp:group {\"className\":\"tb-article-meta\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"center\"}} -->\n		<div class=\"wp-block-group tb-article-meta\">\n			<!-- wp:paragraph --><p>From Tanya Barrans</p><!-- /wp:paragraph -->\n			<!-- wp:post-date /-->\n		</div>\n		<!-- /wp:group -->\n	</header>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-hero\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-article-hero\">\n		<!-- wp:post-featured-image {\"aspectRatio\":\"16/9\",\"sizeSlug\":\"full\"} /-->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-body\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\",\"wideSize\":\"1200px\"}} -->\n	<div class=\"wp-block-group tb-article-body\">\n		<!-- wp:post-content {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\",\"wideSize\":\"1200px\"}} /-->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-comments\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"740px\"}} -->\n<div class=\"wp-block-group tb-article-comments\">\n<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Join the conversation</h2><!-- /wp:heading -->\n<!-- wp:paragraph --><p>Have a tip, a question, or a story of your own? I’d love to hear it.</p><!-- /wp:paragraph -->\n<!-- wp:comments -->\n<div class=\"wp-block-comments\">\n<!-- wp:comments-title {\"showPostTitle\":false} /-->\n<!-- wp:comment-template -->\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} --><div class=\"wp-block-group\"><!-- wp:avatar {\"size\":48} /--><!-- wp:group --><div class=\"wp-block-group\"><!-- wp:comment-author-name /--><!-- wp:comment-date /--></div><!-- /wp:group --></div><!-- /wp:group -->\n<!-- wp:comment-content /-->\n<!-- wp:comment-reply-link /-->\n<!-- /wp:comment-template -->\n<!-- wp:post-comments-form /-->\n</div>\n<!-- /wp:comments -->\n</div>\n<!-- /wp:group --> <!-- wp:html -->\n<aside class=\"tb-blog-rail\" aria-label=\"About Tanya and current listings\">\n  <section class=\"tb-blog-rail__intro\">\n    <img src=\"/wp-content/uploads/2026/07/about-main.jpg\" alt=\"Tanya Barrans, Puget Sound real estate broker\" loading=\"lazy\">\n    <p class=\"tb-blog-rail__eyebrow\">Your local real estate resource</p>\n    <h2>Hi, I’m Tanya.</h2>\n    <p>I help buyers and sellers make thoughtful moves across Renton and the South Sound—with honest guidance and a little more personality.</p>\n    <a class=\"tb-blog-rail__button\" href=\"/contact/\">Ask Tanya a question</a>\n  </section>\n  <section class=\"tb-blog-listings\">\n    <p class=\"tb-blog-rail__eyebrow\">Currently listed by Tanya</p>\n    <h2>Homes worth a look</h2>\n    <div class=\"tb-listing-grid\">\n      <a class=\"tb-listing-card\" href=\"https://tanyab.johnlscott.com/listing/wa/olympia/5246-yearley-drive-ne-/21476453\" target=\"_blank\" rel=\"noopener\">\n        <span class=\"tb-listing-card__image\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/253/429/2534297.jpg\" alt=\"5246 Yearley Drive NE in Olympia\" loading=\"lazy\"><span>Active</span></span>\n        <span class=\"tb-listing-card__body\"><strong>5246 Yearley Drive NE</strong><small>Olympia, WA</small><b>$389,999</b><small>2 beds · 1.75 baths · 972 sq ft</small></span>\n      </a>\n      <a class=\"tb-listing-card\" href=\"https://tanyab.johnlscott.com/listing/wa/puyallup/18026-75th-avenue-e-/21497093\" target=\"_blank\" rel=\"noopener\">\n        <span class=\"tb-listing-card__image\"><img src=\"https://assets.jlscontent.com/photos/wanwmls/254/658/2546584.jpg\" alt=\"18026 75th Avenue E in Puyallup\" loading=\"lazy\"><span>Active</span></span>\n        <span class=\"tb-listing-card__body\"><strong>18026 75th Avenue E</strong><small>Puyallup, WA</small><b>$545,000</b><small>4 beds · 2.5 baths · 2,201 sq ft</small></span>\n      </a>\n    </div>\n    <div class=\"tb-listing-fallback\">\n      <h3>Nothing active right now—but the search doesn’t stop here.</h3>\n      <p>Browse homes on my John L. Scott site or tell me what you’re hoping to find.</p>\n      <a href=\"https://tanyab.johnlscott.com/search\" target=\"_blank\" rel=\"noopener\">Explore available homes</a>\n      <a href=\"/contact/\">Tell me what you’re looking for</a>\n    </div>\n    <a class=\"tb-blog-rail__text-link\" href=\"https://tanyab.johnlscott.com\" target=\"_blank\" rel=\"noopener\">See all listings on John L. Scott →</a>\n  </section>\n</aside>\n<!-- /wp:html --> <!-- wp:group {\"align\":\"full\",\"className\":\"tb-newsletter-feature\",\"backgroundColor\":\"base\",\"layout\":{\"type\":\"default\"},\"metadata\":{\"patternName\":\"tanya-barrans/newsletter\",\"name\":\"Newsletter Signup\",\"categories\":[\"featured\"]}} -->\n<div class=\"wp-block-group alignfull tb-newsletter-feature has-base-background-color has-background\">\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__image\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__image\" aria-hidden=\"true\" style=\"background-image:url(/wp-content/themes/tanya-barrans/assets/images/lwyl-coffee.jpg)\"></div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-newsletter-feature__content tb-reveal\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group tb-newsletter-feature__content tb-reveal\">\n		<!-- wp:paragraph {\"className\":\"tb-script-accent\"} -->\n		<p class=\"tb-script-accent\">Let’s stay in touch</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:heading {\"fontSize\":\"x-large\"} -->\n		<h2 class=\"wp-block-heading has-x-large-font-size\">Notes worth opening.</h2>\n		<!-- /wp:heading -->\n\n		<!-- wp:paragraph {\"textColor\":\"graphite\"} -->\n		<p class=\"has-graphite-color has-text-color\">Useful home ideas, local stories, and honest real estate guidance—delivered with no pressure and no polished filler.</p>\n		<!-- /wp:paragraph -->\n\n		<!-- wp:html -->\n		<form class=\"tb-newsletter-form\" novalidate>\n			<div class=\"tb-newsletter-fields\">\n				<label class=\"tb-sr-only\" for=\"tb-nl-name\">First name</label>\n				<input type=\"text\" id=\"tb-nl-name\" name=\"name\" class=\"tb-newsletter-input\" placeholder=\"First name\" autocomplete=\"given-name\" />\n\n				<label class=\"tb-sr-only\" for=\"tb-nl-email\">Email address</label>\n				<input type=\"email\" id=\"tb-nl-email\" name=\"email\" class=\"tb-newsletter-input\" placeholder=\"Email address\" autocomplete=\"email\" required />\n\n				<div class=\"tb-newsletter-hp\" aria-hidden=\"true\">\n					<label for=\"tb-nl-website\">Website</label>\n					<input type=\"text\" id=\"tb-nl-website\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\" />\n				</div>\n\n				<button type=\"submit\" class=\"tb-newsletter-submit\">Subscribe</button>\n			</div>\n			<p class=\"tb-newsletter-status\" role=\"status\" aria-live=\"polite\"></p>\n		</form>\n		<!-- /wp:html -->\n\n		<!-- wp:paragraph {\"className\":\"tb-newsletter-feature__privacy\"} -->\n		<p class=\"tb-newsletter-feature__privacy\">No spam. Unsubscribe whenever you like.</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"tb-article-navigation\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1200px\"}} -->\n	<nav class=\"wp-block-group tb-article-navigation\" aria-label=\"Article navigation\">\n		<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"space-between\"}} -->\n		<div class=\"wp-block-group\">\n			<!-- wp:post-navigation-link {\"type\":\"previous\",\"label\":\"Previous story\",\"showTitle\":true,\"linkLabel\":true} /-->\n			<!-- wp:post-navigation-link {\"type\":\"next\",\"label\":\"Next story\",\"showTitle\":true,\"linkLabel\":true} /-->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:paragraph {\"align\":\"center\",\"className\":\"tb-journal-back-link\"} --><p class=\"has-text-align-center tb-journal-back-link\"><a href=\"/blog/\">Back to the Journal</a></p><!-- /wp:paragraph -->\n	</nav>\n	<!-- /wp:group -->\n\n</main>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->\n', 'Blog Posts', 'Displays a single post on your website unless a custom template has been applied to that post or a dedicated template exists.', 'inherit', 'closed', 'closed', '', '99-revision-v1', '', '', '2026-08-26 20:26:04', '2026-08-26 20:26:04', '', 99, 'https://violet-wren-104886.hostingersite.com/?p=90416', 0, 'revision', '', 0),
(90417, 2, '2026-08-26 21:10:13', '2026-08-26 21:10:13', '', 'Rooted in Covington Logo (fixed ring gap)', '', 'inherit', 'open', 'closed', '', 'rooted-in-covington-logo-fixed-ring-gap', '', '', '2026-08-26 21:10:13', '2026-08-26 21:10:13', '', 0, 'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/rooted-in-covington-logo-fixed.png', 0, 'attachment', 'image/png', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(90418, 2, '2026-08-26 21:10:33', '2026-08-26 21:10:33', '<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"tanya-barrans\",\"tagName\":\"header\"} /-->\n\n<style>\n.cov{--navy:#0b1f3a;--mustard:#e4a900;--ink:#202a35;--muted:#637080;--paper:#fff;--wash:#f7f4ed;background:var(--paper);color:var(--ink);font-family:Arial,sans-serif;overflow:hidden}.cov *{box-sizing:border-box}.cov a{color:var(--navy);text-decoration-thickness:1px;text-underline-offset:4px}.cov img{display:block;width:100%;height:100%;object-fit:cover}.cov .wrap{width:min(1160px,calc(100% - 44px));margin:auto}.cov .eyebrow{color:var(--mustard);font-size:.72rem;font-weight:800;letter-spacing:.18em;text-transform:uppercase}.cov h1,.cov h2,.cov h3{font-family:Georgia,serif;color:var(--navy)!important;font-weight:400;letter-spacing:-.025em}.cov h2{font-size:clamp(2.5rem,5vw,4.6rem);line-height:1;margin:.15em 0 .45em}.cov p{line-height:1.75}.cov .hero{min-height:720px;position:relative;background:url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/city_of_covingtonwa_cover-scaled.jpeg\') center/cover}.cov .hero:after{content:\"\";position:absolute;inset:0;background:linear-gradient(90deg,rgba(7,20,39,.72),rgba(7,20,39,.05) 70%)}.cov .hero-copy{position:absolute;z-index:2;left:max(5vw,calc((100vw - 1160px)/2));bottom:72px;width:min(720px,calc(100% - 44px));color:white}.cov .hero h1{color:white!important;font-size:clamp(3.8rem,8vw,7rem);line-height:.9;margin:.15em 0}.cov .hero p{max-width:680px;font-size:1.15rem}.cov .logo{position:absolute;z-index:3;right:max(3vw,calc((100vw - 1160px)/2));bottom:34px;width:290px;height:290px;object-fit:contain;filter:drop-shadow(0 12px 25px rgba(0,0,0,.28))}.cov section{padding:105px 0}.cov .intro{display:grid;grid-template-columns:1.12fr .88fr;gap:7vw;align-items:center}.cov .intro-photo{height:640px}.cov .photo-credit{font-size:.7rem;color:var(--muted);margin-top:8px}.cov .lede{font-family:Georgia,serif;font-size:1.5rem;line-height:1.55;color: