{\"source\":\"core/post-data\",\"args\":{\"field\":\"link\"}}}}} /-->\n<!-- /wp:navigation-submenu -->\n\n<!-- wp:navigation-link {\"label\":\"The Journal\",\"url\":\"/blog/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"About Tanya\",\"url\":\"/about/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->\n\n<!-- wp:navigation-link {\"label\":\"Contact\",\"url\":\"/contact/\",\"kind\":\"custom\",\"isTopLevelLink\":true} /-->', 'Navigation', '', 'inherit', 'closed', 'closed', '', '4-revision-v1', '', '', '2026-08-27 03:37:39', '2026-08-27 03:37:39', '', 4, 'https://violet-wren-104886.hostingersite.com/?p=90444', 0, 'revision', '', 0),
