INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(90459, 2, '2026-08-27 03:59:19', '2026-08-27 03:59:19', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:html -->\n<style>\n.tb-rooted-city{--navy:#344c6a;--pink:#c77798;--green:#718c78;--cream:#fbf7f0;--khaki:#ddcbb8;--ink:#26364a;background:var(--cream);color:var(--ink);font-family:Montserrat,Arial,sans-serif}\n.tb-rooted-city *{box-sizing:border-box}\n.tb-rooted-city a{text-decoration:none}\n.tb-rooted-city h1,.tb-rooted-city h2,.tb-rooted-city h3{font-family:Georgia,\"Times New Roman\",serif;color:var(--navy)}\n.tb-rooted-city__shell{width:min(1180px,calc(100% - 48px));margin:0 auto}\n.tb-rooted-city__hero{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(420px,.92fr);min-height:650px;background:var(--cream)}\n.tb-rooted-city__photo{min-height:650px;background-image:linear-gradient(90deg,rgba(38,54,74,.05),rgba(38,54,74,.18)),var(--city-photo);background-size:cover;background-position:center}\n.tb-rooted-city__hero-copy{display:flex;align-items:center;padding:72px clamp(36px,6vw,84px);position:relative;border-top:8px solid var(--green)}\n.tb-rooted-city__hero-copy:after{content:\"\";position:absolute;right:0;top:88px;width:18px;height:42%;background:var(--pink)}\n.tb-rooted-city__eyebrow{margin:0 0 18px;color:var(--pink);font-size:.94rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase}\n.tb-rooted-city__hero h1{margin:0;font-size:clamp(3.4rem,6.3vw,6.7rem);line-height:.86;letter-spacing:-.045em}\n.tb-rooted-city__hero h1 span{display:block;color:var(--pink);font-style:italic;font-weight:500}\n.tb-rooted-city__dek{max-width:590px;margin:28px 0 0;font-size:1.12rem;line-height:1.75}\n.tb-rooted-city__actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:32px}\n.tb-rooted-city__button{display:inline-flex;align-items:center;justify-content:center;min-height:54px;padding:14px 24px;background:var(--navy);color:#fff;font-size:.82rem;font-weight:800;letter-spacing:.11em;text-transform:uppercase}\n.tb-rooted-city__button--outline{background:transparent;color:var(--navy);border:1px solid var(--navy)}\n.tb-rooted-city__credit{margin-top:24px;font-size:.72rem;line-height:1.45;color:#667081}\n.tb-rooted-city__credit a{color:inherit;text-decoration:underline}\n.tb-rooted-city__intro{padding:92px 0}\n.tb-rooted-city__intro-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:64px;align-items:center}\n.tb-rooted-city__intro-card{min-height:430px;padding:54px;background:var(--navy);display:flex;flex-direction:column;justify-content:flex-end;position:relative;overflow:hidden}\n.tb-rooted-city__intro-card:before{content:\"ROOTED\";position:absolute;top:22px;left:34px;color:rgba(255,255,255,.08);font-family:Georgia,serif;font-size:clamp(5rem,12vw,10rem);line-height:1}\n.tb-rooted-city__intro-card .tb-rooted-city__eyebrow{color:#c77798}\n.tb-rooted-city__intro-card h2{position:relative;margin:0;color:#fff;font-size:clamp(2.5rem,5vw,4.5rem);line-height:1.02}\n.tb-rooted-city__intro-copy h2{font-size:clamp(2.7rem,5vw,4.8rem);line-height:1.02;margin:0}\n.tb-rooted-city__intro-copy h2 em{display:block;color:var(--pink);font-weight:500}\n.tb-rooted-city__intro-copy p{font-size:1.08rem;line-height:1.8;margin:24px 0 0}\n.tb-rooted-city__section{padding:88px 0}\n.tb-rooted-city__section--khaki{background:var(--khaki)}\n.tb-rooted-city__section--white{background:#fff}\n.tb-rooted-city__section-head{text-align:center;max-width:760px;margin:0 auto 44px}\n.tb-rooted-city__section-head .tb-rooted-city__eyebrow{margin-bottom:12px}\n.tb-rooted-city__section-head h2{font-size:clamp(2.6rem,5vw,4.6rem);line-height:1;margin:0}\n.tb-rooted-city__section-head h2 em{color:var(--pink);font-weight:500}\n.tb-rooted-city__section-head p{margin:20px auto 0;max-width:650px;line-height:1.7}\n.tb-rooted-city__story-grid{display:grid;grid-template-columns:1.35fr .65fr .65fr;gap:22px}\n.tb-rooted-city__story{min-height:330px;padding:34px;background:#fff;border:1px solid rgba(52,76,106,.18);display:flex;flex-direction:column;justify-content:flex-end}\n.tb-rooted-city__story--featured{background:var(--green);min-height:420px}\n.tb-rooted-city__story .tb-rooted-city__eyebrow{font-size:.76rem}\n.tb-rooted-city__story--featured .tb-rooted-city__eyebrow{color:#ffffff}\n.tb-rooted-city__story h3{font-size:2rem;line-height:1.08;margin:0}\n.tb-rooted-city__story--featured h3{font-size:clamp(2.6rem,4vw,4rem);color:#fff}\n.tb-rooted-city__story p{line-height:1.65;margin:16px 0 0}\n.tb-rooted-city__story--featured p{color:#fff}\n.tb-rooted-city__category-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}\n.tb-rooted-city__category{min-height:245px;padding:24px;display:flex;align-items:flex-end;position:relative;overflow:hidden}\n.tb-rooted-city__category:nth-child(1){background:rgba(199,119,152,.18)}\n.tb-rooted-city__category:nth-child(2){background:#88a28e}\n.tb-rooted-city__category:nth-child(3){background:#f3e7d9}\n.tb-rooted-city__category:nth-child(4){background:#344c6a}\n.tb-rooted-city__category:before{content:attr(data-number);position:absolute;right:12px;top:-12px;font-family:Georgia,serif;font-size:7rem;color:rgba(255,255,255,.45)}\n.tb-rooted-city__category h3{position:relative;margin:0;font-size:1.45rem}\n.tb-rooted-city__category:nth-child(2) h3,.tb-rooted-city__category:nth-child(4) h3{color:#fff}\n.tb-rooted-city__favorites{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}\n.tb-rooted-city__favorite{background:#fff;border-top:7px solid var(--pink);padding:28px;min-height:220px}\n.tb-rooted-city__favorite:nth-child(even){border-top-color:var(--green)}\n.tb-rooted-city__favorite h3{font-size:1.55rem;margin:0 0 12px}\n.tb-rooted-city__favorite p{line-height:1.6;margin:0;color:#566273}\n.tb-rooted-city__favorite small{display:block;margin-top:22px;color:var(--pink);font-weight:800;letter-spacing:.09em;text-transform:uppercase}\n.tb-rooted-city__guide-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}\n.tb-rooted-city__guide{padding:34px;background:var(--cream);border:1px solid rgba(52,76,106,.2);min-height:260px;display:flex;flex-direction:column}\n.tb-rooted-city__guide h3{font-size:2rem;line-height:1.08;margin:18px 0 12px}\n.tb-rooted-city__guide p{line-height:1.65;margin:0}\n.tb-rooted-city__guide small{margin-top:auto;padding-top:24px;color:var(--pink);font-weight:800;letter-spacing:.1em;text-transform:uppercase}\n.tb-rooted-city__duo{display:grid;grid-template-columns:1fr 1fr}\n.tb-rooted-city__duo>div{padding:72px clamp(28px,6vw,84px)}\n.tb-rooted-city__duo-left{background:var(--cream)}\n.tb-rooted-city__duo-right{background:var(--navy)}\n.tb-rooted-city__duo h2{font-size:clamp(2.5rem,4vw,4.2rem);line-height:1.03;margin:0}\n.tb-rooted-city__duo-right h2,.tb-rooted-city__duo-right p{color:#fff}\n.tb-rooted-city__duo p{line-height:1.7;max-width:580px}\n.tb-rooted-city__duo-right .tb-rooted-city__button{background:var(--pink)}\n.tb-rooted-city__move{padding:82px 0;background:var(--green);text-align:center}\n.tb-rooted-city__move h2{color:#fff;font-size:clamp(2.8rem,5vw,5rem);line-height:1;margin:0}\n.tb-rooted-city__move p{color:#fff;max-width:700px;margin:20px auto 30px;line-height:1.7}\n.tb-rooted-city__move .tb-rooted-city__button{background:#fff;color:var(--navy)}\n@media(max-width:980px){.tb-rooted-city__hero{grid-template-columns:1fr}.tb-rooted-city__photo{min-height:420px}.tb-rooted-city__hero-copy{padding:58px 32px}.tb-rooted-city__intro-grid,.tb-rooted-city__duo{grid-template-columns:1fr}.tb-rooted-city__story-grid{grid-template-columns:1fr 1fr}.tb-rooted-city__story--featured{grid-column:1/-1}.tb-rooted-city__category-grid,.tb-rooted-city__favorites{grid-template-columns:1fr 1fr}}\n@media(max-width:640px){.tb-rooted-city__shell{width:min(100% - 32px,1180px)}.tb-rooted-city__photo{min-height:310px}.tb-rooted-city__hero h1{font-size:clamp(3rem,17vw,5rem)}.tb-rooted-city__hero-copy:after{display:none}.tb-rooted-city__intro,.tb-rooted-city__section{padding:64px 0}.tb-rooted-city__intro-grid{gap:34px}.tb-rooted-city__intro-card{min-height:320px;padding:30px}.tb-rooted-city__story-grid,.tb-rooted-city__category-grid,.tb-rooted-city__favorites,.tb-rooted-city__guide-grid{grid-template-columns:1fr}.tb-rooted-city__story--featured{grid-column:auto}.tb-rooted-city__duo>div{padding:54px 24px}.tb-rooted-city__actions{align-items:stretch}.tb-rooted-city__button{width:100%}}\n\n.tb-rooted-city__intro{padding:84px 0 48px}\n.tb-rooted-city__intro-grid{grid-template-columns:minmax(300px,.82fr) minmax(0,1.18fr);gap:64px}\n.tb-rooted-city__intro-card{min-height:480px;padding:42px;background:linear-gradient(145deg,#fff 0%,var(--cream) 100%);border:1px solid rgba(52,76,106,.13);border-radius:28px;box-shadow:18px 18px 0 var(--khaki);display:flex;align-items:center;justify-content:center}\n.tb-rooted-city__intro-card:before{display:none}\n.tb-rooted-city__intro-logo{display:block;width:min(310px,84%);height:auto;filter:drop-shadow(0 15px 22px rgba(38,54,74,.13))}\n.tb-rooted-city__roots{padding:32px 0 96px}\n.tb-rooted-city__roots-card{display:grid;grid-template-columns:minmax(280px,.84fr) minmax(0,1.16fr);overflow:hidden;border-radius:28px;background:#fff;border:1px solid rgba(52,76,106,.12);box-shadow:0 24px 60px rgba(52,76,106,.12)}\n.tb-rooted-city__roots-mark{display:flex;flex-direction:column;justify-content:flex-end;min-height:430px;padding:52px;background:linear-gradient(155deg,var(--navy),#26364a);position:relative;overflow:hidden}\n.tb-rooted-city__roots-mark:before{content:\"ROOTS\";position:absolute;left:-10px;top:14px;font-family:Georgia,serif;font-size:clamp(5rem,11vw,9.5rem);line-height:1;color:rgba(255,255,255,.06)}\n.tb-rooted-city__roots-mark .tb-rooted-city__eyebrow{position:relative;color:#f2b51d}\n.tb-rooted-city__roots-mark h2{position:relative;margin:0;color:#fff!important;font-size:clamp(2.1rem,3.5vw,3.45rem);line-height:1.02}\n.tb-rooted-city__roots-copy{display:flex;flex-direction:column;justify-content:center;padding:clamp(44px,6vw,72px)}\n.tb-rooted-city__roots-copy p{margin:0;font-size:1.06rem;line-height:1.85}\n.tb-rooted-city__roots-link{display:inline-flex;align-items:center;gap:8px;width:max-content;margin-top:26px;color:var(--navy)!important;font-size:.78rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase;border-bottom:2px solid var(--pink);padding-bottom:6px}\n.tb-rooted-city__story,.tb-rooted-city__category,.tb-rooted-city__favorite,.tb-rooted-city__guide{border-radius:18px;box-shadow:0 14px 34px rgba(52,76,106,.10);transition:transform .2s ease,box-shadow .2s ease}\n.tb-rooted-city__story:hover,.tb-rooted-city__category:hover,.tb-rooted-city__favorite:hover,.tb-rooted-city__guide:hover{transform:translateY(-4px);box-shadow:0 18px 40px rgba(52,76,106,.15)}\n.tb-rooted-city__section--khaki{background:linear-gradient(180deg,var(--khaki),#eadfd2)}\n.tb-rooted-city__section-head{max-width:760px}\n@media(max-width:820px){.tb-rooted-city__intro-grid,.tb-rooted-city__roots-card{grid-template-columns:1fr}.tb-rooted-city__intro-card{min-height:360px;box-shadow:10px 10px 0 var(--khaki)}.tb-rooted-city__roots-mark{min-height:320px}.tb-rooted-city__roots-copy{padding:40px 30px}}\n\n</style>\n<main class=\"tb-rooted-city\" style=\"--city-photo:url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/maple-valley-lake-wilderness-scaled.jpg\')\">\n<section class=\"tb-rooted-city__hero\">\n<div class=\"tb-rooted-city__photo\" role=\"img\" aria-label=\"Maple Valley, Washington\"></div>\n<div class=\"tb-rooted-city__hero-copy\"><div>\n<p class=\"tb-rooted-city__eyebrow\">Helping you love where you live</p>\n<h1>Rooted in <span>Maple Valley</span></h1>\n<p class=\"tb-rooted-city__dek\">Lake days, wooded trails and a strong sense of community. This guide will collect the places and practical details that help Maple Valley feel like home.</p>\n<div class=\"tb-rooted-city__actions\"><a class=\"tb-rooted-city__button\" href=\"#city-stories\">Explore the city notes</a><a class=\"tb-rooted-city__button tb-rooted-city__button--outline\" href=\"/contact/\">Suggest a story</a></div>\n<p class=\"tb-rooted-city__credit\"><a href=\"https://commons.wikimedia.org/wiki/File:Lake_Wilderness_in_Maple_Valley.jpg\" target=\"_blank\" rel=\"noopener\">Lake Wilderness in Maple Valley, Yordanpopovbg, CC BY-SA 4.0</a></p>\n</div></div>\n</section>\n<section class=\"tb-rooted-city__intro\" id=\"city-stories\"><div class=\"tb-rooted-city__shell tb-rooted-city__intro-grid\">\n<div class=\"tb-rooted-city__intro-card\"><img class=\"tb-rooted-city__intro-logo\" src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/4.png\" alt=\"Rooted in Maple Valley logo\"></div>\n<div class=\"tb-rooted-city__intro-copy\"><p class=\"tb-rooted-city__eyebrow\">Start here</p><h2>A local guide that <em>grows with the city.</em></h2><p>Maple Valley is shaped by Lake Wilderness, nearby trails and neighborhoods that feel connected to the outdoors. This page will grow into a useful mix of local favorites, community stories and real estate guidance for people considering a move.</p><div class=\"tb-rooted-city__actions\"><a class=\"tb-rooted-city__button\" href=\"/contact/\">Ask Tanya about Maple Valley</a></div></div>\n</div></section>\n<section class=\"tb-rooted-city__roots\" aria-labelledby=\"roots-maple-valley\"><div class=\"tb-rooted-city__shell\"><div class=\"tb-rooted-city__roots-card\"><div class=\"tb-rooted-city__roots-mark\"><p class=\"tb-rooted-city__eyebrow\">The roots</p><h2 id=\"roots-maple-valley\">A city whose story follows the river and the trees.</h2></div><div class=\"tb-rooted-city__roots-copy\"><p>The Cedar River has shaped life here for generations. The Maple Valley area lies within the historic range of several Indigenous peoples, and the river was central to travel, food and culture long before the city existed. Homesteaders arrived in 1879, and local lore says the community\'s name was chosen by slips of paper drawn from a hat. Vine Maple Valley won, although the post office later shortened it to Maple Valley. Timber, coal and railroads built the early town, while Lake Wilderness became a gathering place that helped define its outdoor character. The city incorporated in 1997, but its deepest identity still comes from the landscape. Water, woods and neighbors who show up for one another remain at the heart of life here.</p><a class=\"tb-rooted-city__roots-link\" href=\"https://www.historylink.org/file/1922\" target=\"_blank\" rel=\"noopener noreferrer\">Explore Maple Valley\'s history <span aria-hidden=\"true\">→</span></a></div></div></div></section>\n\n<section class=\"tb-rooted-city__section tb-rooted-city__section--khaki\"><div class=\"tb-rooted-city__shell\">\n<div class=\"tb-rooted-city__section-head\"><p class=\"tb-rooted-city__eyebrow\">Maple Valley stories</p><h2>What we are <em>building next.</em></h2><p>A city hub should feel useful before it feels finished. These are the first three editorial tracks for Maple Valley.</p></div>\n<div class=\"tb-rooted-city__story-grid\">\n<a class=\"tb-rooted-city__story tb-rooted-city__story--featured\" href=\"/living-in-maple-valley-wa-local-guide/\" style=\"color:inherit;text-decoration:none\"><p class=\"tb-rooted-city__eyebrow\">Featured city guide</p><h3>What it is really like to live in Maple Valley</h3><p>Neighborhood feel, daily routines and the details people want before they make a move.</p></a>\n<article class=\"tb-rooted-city__story\"><p class=\"tb-rooted-city__eyebrow\">Coming next</p><h3>A local weekend in Maple Valley</h3><p>Food, coffee, parks and a few good reasons to leave the house.</p></article>\n<article class=\"tb-rooted-city__story\"><p class=\"tb-rooted-city__eyebrow\">Coming next</p><h3>The people behind the places</h3><p>Small businesses and community stories worth knowing.</p></article>\n</div></div></section>\n<section class=\"tb-rooted-city__section tb-rooted-city__section--white\"><div class=\"tb-rooted-city__shell\">\n<div class=\"tb-rooted-city__section-head\"><p class=\"tb-rooted-city__eyebrow\">Explore Maple Valley</p><h2>Find the part of town <em>you will love.</em></h2></div>\n<div class=\"tb-rooted-city__category-grid\">\n<div class=\"tb-rooted-city__category\" data-number=\"01\"><h3>Eat &amp; drink</h3></div>\n<div class=\"tb-rooted-city__category\" data-number=\"02\"><h3>Parks &amp; outdoors</h3></div>\n<div class=\"tb-rooted-city__category\" data-number=\"03\"><h3>Local businesses</h3></div>\n<div class=\"tb-rooted-city__category\" data-number=\"04\"><h3>Events &amp; community</h3></div>\n</div></div></section>\n<section class=\"tb-rooted-city__section\"><div class=\"tb-rooted-city__shell\">\n<div class=\"tb-rooted-city__section-head\"><p class=\"tb-rooted-city__eyebrow\">Tanya\'s Maple Valley list</p><h2>The spots worth <em>saving.</em></h2><p>This section is ready for Tanya\'s real favorites. The placeholders keep the page useful without pretending the list is finished.</p></div>\n<div class=\"tb-rooted-city__favorites\">\n<article class=\"tb-rooted-city__favorite\"><h3>Favorite coffee</h3><p>The kind of place you recommend when someone asks for good coffee and a comfortable corner.</p><small>Tanya\'s pick coming soon</small></article>\n<article class=\"tb-rooted-city__favorite\"><h3>Go-to walk</h3><p>A reliable reset for fresh air, movement and a better look at the city.</p><small>Tanya\'s pick coming soon</small></article>\n<article class=\"tb-rooted-city__favorite\"><h3>Easy dinner</h3><p>A local spot that works when you want something good without making it a whole production.</p><small>Tanya\'s pick coming soon</small></article>\n<article class=\"tb-rooted-city__favorite\"><h3>Local gem</h3><p>The small business or community place that helps Maple Valley feel like Maple Valley.</p><small>Tanya\'s pick coming soon</small></article>\n</div></div></section>\n<section class=\"tb-rooted-city__section tb-rooted-city__section--white\"><div class=\"tb-rooted-city__shell\">\n<div class=\"tb-rooted-city__section-head\"><p class=\"tb-rooted-city__eyebrow\">Maple Valley guide collection</p><h2>Practical answers, <em>all in one place.</em></h2></div>\n<div class=\"tb-rooted-city__guide-grid\">\n<a class=\"tb-rooted-city__guide\" href=\"/living-in-maple-valley-wa-local-guide/\" style=\"color:inherit;text-decoration:none\"><p class=\"tb-rooted-city__eyebrow\">Moving guide</p><h3>Living in Maple Valley</h3><p>The practical guide to neighborhoods, routines and what to know before moving.</p><small>Read the guide</small></a>\n<article class=\"tb-rooted-city__guide\"><p class=\"tb-rooted-city__eyebrow\">Local guide</p><h3>A weekend in Maple Valley</h3><p>A flexible list for food, coffee, parks and community events.</p><small>In progress</small></article>\n<article class=\"tb-rooted-city__guide\"><p class=\"tb-rooted-city__eyebrow\">Neighborhoods</p><h3>Where to look in Maple Valley</h3><p>A plain-language comparison built around how you actually want to live.</p><small>In progress</small></article>\n</div></div></section>\n<section class=\"tb-rooted-city__duo\">\n<div class=\"tb-rooted-city__duo-left\"><p class=\"tb-rooted-city__eyebrow\">Love the place?</p><h2>Explore what it is like to live nearby.</h2><p>Compare Maple Valley with the other communities Tanya knows and serves.</p><a class=\"tb-rooted-city__button tb-rooted-city__button--outline\" href=\"/rooted-cities/\">Explore all neighborhoods</a></div>\n<div class=\"tb-rooted-city__duo-right\"><p class=\"tb-rooted-city__eyebrow\">Share your Maple Valley</p><h2>Know a story we should tell?</h2><p>Favorite shop, hidden gem or everyday hero. Help shape this guide with the places and people that make Maple Valley feel like home.</p><a class=\"tb-rooted-city__button\" href=\"/contact/\">Suggest a Maple Valley story</a></div>\n</section>\n<section class=\"tb-rooted-city__move\"><div class=\"tb-rooted-city__shell\"><h2>Thinking about making Maple Valley home?</h2><p>Whether you are moving in, moving within the city or just curious about the market, Tanya can help you sort through the options without the sales pressure.</p><a class=\"tb-rooted-city__button\" href=\"/contact/\">Ask Tanya a question</a></div></section>\n</main>\n<!-- /wp:html -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->', 'Rooted in Maple Valley Page', '', 'publish', 'closed', 'closed', '', 'rooted-in-maple-valley-page', '', '', '2026-08-27 03:59:21', '2026-08-27 03:59:21', '', 0, 'https://violet-wren-104886.hostingersite.com/rooted-in-maple-valley-page/', 0, 'wp_template', '', 0),
(90460, 2, '2026-08-27 03:59:21', '2026-08-27 03:59:21', '', 'Maple Valley', '', 'inherit', 'closed', 'closed', '', '90244-revision-v1', '', '', '2026-08-27 03:59:21', '2026-08-27 03:59:21', '', 90244, 'https://violet-wren-104886.hostingersite.com/?p=90460', 0, 'revision', '', 0),
(90461, 2, '2026-08-27 03:59:21', '2026-08-27 03:59:21', '<!-- wp:template-part {\"slug\":\"header\",\"tagName\":\"header\",\"theme\":\"tanya-barrans\"} /-->\n\n<!-- wp:html -->\n<style>\n.tb-rooted-city{--navy:#344c6a;--pink:#c77798;--green:#718c78;--cream:#fbf7f0;--khaki:#ddcbb8;--ink:#26364a;background:var(--cream);color:var(--ink);font-family:Montserrat,Arial,sans-serif}\n.tb-rooted-city *{box-sizing:border-box}\n.tb-rooted-city a{text-decoration:none}\n.tb-rooted-city h1,.tb-rooted-city h2,.tb-rooted-city h3{font-family:Georgia,\"Times New Roman\",serif;color:var(--navy)}\n.tb-rooted-city__shell{width:min(1180px,calc(100% - 48px));margin:0 auto}\n.tb-rooted-city__hero{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(420px,.92fr);min-height:650px;background:var(--cream)}\n.tb-rooted-city__photo{min-height:650px;background-image:linear-gradient(90deg,rgba(38,54,74,.05),rgba(38,54,74,.18)),var(--city-photo);background-size:cover;background-position:center}\n.tb-rooted-city__hero-copy{display:flex;align-items:center;padding:72px clamp(36px,6vw,84px);position:relative;border-top:8px solid var(--green)}\n.tb-rooted-city__hero-copy:after{content:\"\";position:absolute;right:0;top:88px;width:18px;height:42%;background:var(--pink)}\n.tb-rooted-city__eyebrow{margin:0 0 18px;color:var(--pink);font-size:.94rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase}\n.tb-rooted-city__hero h1{margin:0;font-size:clamp(3.4rem,6.3vw,6.7rem);line-height:.86;letter-spacing:-.045em}\n.tb-rooted-city__hero h1 span{display:block;color:var(--pink);font-style:italic;font-weight:500}\n.tb-rooted-city__dek{max-width:590px;margin:28px 0 0;font-size:1.12rem;line-height:1.75}\n.tb-rooted-city__actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:32px}\n.tb-rooted-city__button{display:inline-flex;align-items:center;justify-content:center;min-height:54px;padding:14px 24px;background:var(--navy);color:#fff;font-size:.82rem;font-weight:800;letter-spacing:.11em;text-transform:uppercase}\n.tb-rooted-city__button--outline{background:transparent;color:var(--navy);border:1px solid var(--navy)}\n.tb-rooted-city__credit{margin-top:24px;font-size:.72rem;line-height:1.45;color:#667081}\n.tb-rooted-city__credit a{color:inherit;text-decoration:underline}\n.tb-rooted-city__intro{padding:92px 0}\n.tb-rooted-city__intro-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:64px;align-items:center}\n.tb-rooted-city__intro-card{min-height:430px;padding:54px;background:var(--navy);display:flex;flex-direction:column;justify-content:flex-end;position:relative;overflow:hidden}\n.tb-rooted-city__intro-card:before{content:\"ROOTED\";position:absolute;top:22px;left:34px;color:rgba(255,255,255,.08);font-family:Georgia,serif;font-size:clamp(5rem,12vw,10rem);line-height:1}\n.tb-rooted-city__intro-card .tb-rooted-city__eyebrow{color:#c77798}\n.tb-rooted-city__intro-card h2{position:relative;margin:0;color:#fff;font-size:clamp(2.5rem,5vw,4.5rem);line-height:1.02}\n.tb-rooted-city__intro-copy h2{font-size:clamp(2.7rem,5vw,4.8rem);line-height:1.02;margin:0}\n.tb-rooted-city__intro-copy h2 em{display:block;color:var(--pink);font-weight:500}\n.tb-rooted-city__intro-copy p{font-size:1.08rem;line-height:1.8;margin:24px 0 0}\n.tb-rooted-city__section{padding:88px 0}\n.tb-rooted-city__section--khaki{background:var(--khaki)}\n.tb-rooted-city__section--white{background:#fff}\n.tb-rooted-city__section-head{text-align:center;max-width:760px;margin:0 auto 44px}\n.tb-rooted-city__section-head .tb-rooted-city__eyebrow{margin-bottom:12px}\n.tb-rooted-city__section-head h2{font-size:clamp(2.6rem,5vw,4.6rem);line-height:1;margin:0}\n.tb-rooted-city__section-head h2 em{color:var(--pink);font-weight:500}\n.tb-rooted-city__section-head p{margin:20px auto 0;max-width:650px;line-height:1.7}\n.tb-rooted-city__story-grid{display:grid;grid-template-columns:1.35fr .65fr .65fr;gap:22px}\n.tb-rooted-city__story{min-height:330px;padding:34px;background:#fff;border:1px solid rgba(52,76,106,.18);display:flex;flex-direction:column;justify-content:flex-end}\n.tb-rooted-city__story--featured{background:var(--green);min-height:420px}\n.tb-rooted-city__story .tb-rooted-city__eyebrow{font-size:.76rem}\n.tb-rooted-city__story--featured .tb-rooted-city__eyebrow{color:#ffffff}\n.tb-rooted-city__story h3{font-size:2rem;line-height:1.08;margin:0}\n.tb-rooted-city__story--featured h3{font-size:clamp(2.6rem,4vw,4rem);color:#fff}\n.tb-rooted-city__story p{line-height:1.65;margin:16px 0 0}\n.tb-rooted-city__story--featured p{color:#fff}\n.tb-rooted-city__category-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}\n.tb-rooted-city__category{min-height:245px;padding:24px;display:flex;align-items:flex-end;position:relative;overflow:hidden}\n.tb-rooted-city__category:nth-child(1){background:rgba(199,119,152,.18)}\n.tb-rooted-city__category:nth-child(2){background:#88a28e}\n.tb-rooted-city__category:nth-child(3){background:#f3e7d9}\n.tb-rooted-city__category:nth-child(4){background:#344c6a}\n.tb-rooted-city__category:before{content:attr(data-number);position:absolute;right:12px;top:-12px;font-family:Georgia,serif;font-size:7rem;color:rgba(255,255,255,.45)}\n.tb-rooted-city__category h3{position:relative;margin:0;font-size:1.45rem}\n.tb-rooted-city__category:nth-child(2) h3,.tb-rooted-city__category:nth-child(4) h3{color:#fff}\n.tb-rooted-city__favorites{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}\n.tb-rooted-city__favorite{background:#fff;border-top:7px solid var(--pink);padding:28px;min-height:220px}\n.tb-rooted-city__favorite:nth-child(even){border-top-color:var(--green)}\n.tb-rooted-city__favorite h3{font-size:1.55rem;margin:0 0 12px}\n.tb-rooted-city__favorite p{line-height:1.6;margin:0;color:#566273}\n.tb-rooted-city__favorite small{display:block;margin-top:22px;color:var(--pink);font-weight:800;letter-spacing:.09em;text-transform:uppercase}\n.tb-rooted-city__guide-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}\n.tb-rooted-city__guide{padding:34px;background:var(--cream);border:1px solid rgba(52,76,106,.2);min-height:260px;display:flex;flex-direction:column}\n.tb-rooted-city__guide h3{font-size:2rem;line-height:1.08;margin:18px 0 12px}\n.tb-rooted-city__guide p{line-height:1.65;margin:0}\n.tb-rooted-city__guide small{margin-top:auto;padding-top:24px;color:var(--pink);font-weight:800;letter-spacing:.1em;text-transform:uppercase}\n.tb-rooted-city__duo{display:grid;grid-template-columns:1fr 1fr}\n.tb-rooted-city__duo>div{padding:72px clamp(28px,6vw,84px)}\n.tb-rooted-city__duo-left{background:var(--cream)}\n.tb-rooted-city__duo-right{background:var(--navy)}\n.tb-rooted-city__duo h2{font-size:clamp(2.5rem,4vw,4.2rem);line-height:1.03;margin:0}\n.tb-rooted-city__duo-right h2,.tb-rooted-city__duo-right p{color:#fff}\n.tb-rooted-city__duo p{line-height:1.7;max-width:580px}\n.tb-rooted-city__duo-right .tb-rooted-city__button{background:var(--pink)}\n.tb-rooted-city__move{padding:82px 0;background:var(--green);text-align:center}\n.tb-rooted-city__move h2{color:#fff;font-size:clamp(2.8rem,5vw,5rem);line-height:1;margin:0}\n.tb-rooted-city__move p{color:#fff;max-width:700px;margin:20px auto 30px;line-height:1.7}\n.tb-rooted-city__move .tb-rooted-city__button{background:#fff;color:var(--navy)}\n@media(max-width:980px){.tb-rooted-city__hero{grid-template-columns:1fr}.tb-rooted-city__photo{min-height:420px}.tb-rooted-city__hero-copy{padding:58px 32px}.tb-rooted-city__intro-grid,.tb-rooted-city__duo{grid-template-columns:1fr}.tb-rooted-city__story-grid{grid-template-columns:1fr 1fr}.tb-rooted-city__story--featured{grid-column:1/-1}.tb-rooted-city__category-grid,.tb-rooted-city__favorites{grid-template-columns:1fr 1fr}}\n@media(max-width:640px){.tb-rooted-city__shell{width:min(100% - 32px,1180px)}.tb-rooted-city__photo{min-height:310px}.tb-rooted-city__hero h1{font-size:clamp(3rem,17vw,5rem)}.tb-rooted-city__hero-copy:after{display:none}.tb-rooted-city__intro,.tb-rooted-city__section{padding:64px 0}.tb-rooted-city__intro-grid{gap:34px}.tb-rooted-city__intro-card{min-height:320px;padding:30px}.tb-rooted-city__story-grid,.tb-rooted-city__category-grid,.tb-rooted-city__favorites,.tb-rooted-city__guide-grid{grid-template-columns:1fr}.tb-rooted-city__story--featured{grid-column:auto}.tb-rooted-city__duo>div{padding:54px 24px}.tb-rooted-city__actions{align-items:stretch}.tb-rooted-city__button{width:100%}}\n\n.tb-rooted-city__intro{padding:84px 0 48px}\n.tb-rooted-city__intro-grid{grid-template-columns:minmax(300px,.82fr) minmax(0,1.18fr);gap:64px}\n.tb-rooted-city__intro-card{min-height:480px;padding:42px;background:linear-gradient(145deg,#fff 0%,var(--cream) 100%);border:1px solid rgba(52,76,106,.13);border-radius:28px;box-shadow:18px 18px 0 var(--khaki);display:flex;align-items:center;justify-content:center}\n.tb-rooted-city__intro-card:before{display:none}\n.tb-rooted-city__intro-logo{display:block;width:min(310px,84%);height:auto;filter:drop-shadow(0 15px 22px rgba(38,54,74,.13))}\n.tb-rooted-city__roots{padding:32px 0 96px}\n.tb-rooted-city__roots-card{display:grid;grid-template-columns:minmax(280px,.84fr) minmax(0,1.16fr);overflow:hidden;border-radius:28px;background:#fff;border:1px solid rgba(52,76,106,.12);box-shadow:0 24px 60px rgba(52,76,106,.12)}\n.tb-rooted-city__roots-mark{display:flex;flex-direction:column;justify-content:flex-end;min-height:430px;padding:52px;background:linear-gradient(155deg,var(--navy),#26364a);position:relative;overflow:hidden}\n.tb-rooted-city__roots-mark:before{content:\"ROOTS\";position:absolute;left:-10px;top:14px;font-family:Georgia,serif;font-size:clamp(5rem,11vw,9.5rem);line-height:1;color:rgba(255,255,255,.06)}\n.tb-rooted-city__roots-mark .tb-rooted-city__eyebrow{position:relative;color:#f2b51d}\n.tb-rooted-city__roots-mark h2{position:relative;margin:0;color:#fff!important;font-size:clamp(2.1rem,3.5vw,3.45rem);line-height:1.02}\n.tb-rooted-city__roots-copy{display:flex;flex-direction:column;justify-content:center;padding:clamp(44px,6vw,72px)}\n.tb-rooted-city__roots-copy p{margin:0;font-size:1.06rem;line-height:1.85}\n.tb-rooted-city__roots-link{display:inline-flex;align-items:center;gap:8px;width:max-content;margin-top:26px;color:var(--navy)!important;font-size:.78rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase;border-bottom:2px solid var(--pink);padding-bottom:6px}\n.tb-rooted-city__story,.tb-rooted-city__category,.tb-rooted-city__favorite,.tb-rooted-city__guide{border-radius:18px;box-shadow:0 14px 34px rgba(52,76,106,.10);transition:transform .2s ease,box-shadow .2s ease}\n.tb-rooted-city__story:hover,.tb-rooted-city__category:hover,.tb-rooted-city__favorite:hover,.tb-rooted-city__guide:hover{transform:translateY(-4px);box-shadow:0 18px 40px rgba(52,76,106,.15)}\n.tb-rooted-city__section--khaki{background:linear-gradient(180deg,var(--khaki),#eadfd2)}\n.tb-rooted-city__section-head{max-width:760px}\n@media(max-width:820px){.tb-rooted-city__intro-grid,.tb-rooted-city__roots-card{grid-template-columns:1fr}.tb-rooted-city__intro-card{min-height:360px;box-shadow:10px 10px 0 var(--khaki)}.tb-rooted-city__roots-mark{min-height:320px}.tb-rooted-city__roots-copy{padding:40px 30px}}\n\n</style>\n<main class=\"tb-rooted-city\" style=\"--city-photo:url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/maple-valley-lake-wilderness-scaled.jpg\')\">\n<section class=\"tb-rooted-city__hero\">\n<div class=\"tb-rooted-city__photo\" role=\"img\" aria-label=\"Maple Valley, Washington\"></div>\n<div class=\"tb-rooted-city__hero-copy\"><div>\n<p class=\"tb-rooted-city__eyebrow\">Helping you love where you live</p>\n<h1>Rooted in <span>Maple Valley</span></h1>\n<p class=\"tb-rooted-city__dek\">Lake days, wooded trails and a strong sense of community. This guide will collect the places and practical details that help Maple Valley feel like home.</p>\n<div class=\"tb-rooted-city__actions\"><a class=\"tb-rooted-city__button\" href=\"#city-stories\">Explore the city notes</a><a class=\"tb-rooted-city__button tb-rooted-city__button--outline\" href=\"/contact/\">Suggest a story</a></div>\n<p class=\"tb-rooted-city__credit\"><a href=\"https://commons.wikimedia.org/wiki/File:Lake_Wilderness_in_Maple_Valley.jpg\" target=\"_blank\" rel=\"noopener\">Lake Wilderness in Maple Valley, Yordanpopovbg, CC BY-SA 4.0</a></p>\n</div></div>\n</section>\n<section class=\"tb-rooted-city__intro\" id=\"city-stories\"><div class=\"tb-rooted-city__shell tb-rooted-city__intro-grid\">\n<div class=\"tb-rooted-city__intro-card\"><img class=\"tb-rooted-city__intro-logo\" src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/4.png\" alt=\"Rooted in Maple Valley logo\"></div>\n<div class=\"tb-rooted-city__intro-copy\"><p class=\"tb-rooted-city__eyebrow\">Start here</p><h2>A local guide that <em>grows with the city.</em></h2><p>Maple Valley is shaped by Lake Wilderness, nearby trails and neighborhoods that feel connected to the outdoors. This page will grow into a useful mix of local favorites, community stories and real estate guidance for people considering a move.</p><div class=\"tb-rooted-city__actions\"><a class=\"tb-rooted-city__button\" href=\"/contact/\">Ask Tanya about Maple Valley</a></div></div>\n</div></section>\n<section class=\"tb-rooted-city__roots\" aria-labelledby=\"roots-maple-valley\"><div class=\"tb-rooted-city__shell\"><div class=\"tb-rooted-city__roots-card\"><div class=\"tb-rooted-city__roots-mark\"><p class=\"tb-rooted-city__eyebrow\">The roots</p><h2 id=\"roots-maple-valley\">A city whose story follows the river and the trees.</h2></div><div class=\"tb-rooted-city__roots-copy\"><p>The Cedar River has shaped life here for generations. The Maple Valley area lies within the historic range of several Indigenous peoples, and the river was central to travel, food and culture long before the city existed. Homesteaders arrived in 1879, and local lore says the community\'s name was chosen by slips of paper drawn from a hat. Vine Maple Valley won, although the post office later shortened it to Maple Valley. Timber, coal and railroads built the early town, while Lake Wilderness became a gathering place that helped define its outdoor character. The city incorporated in 1997, but its deepest identity still comes from the landscape. Water, woods and neighbors who show up for one another remain at the heart of life here.</p><a class=\"tb-rooted-city__roots-link\" href=\"https://www.historylink.org/file/1922\" target=\"_blank\" rel=\"noopener noreferrer\">Explore Maple Valley\'s history <span aria-hidden=\"true\">→</span></a></div></div></div></section>\n\n<section class=\"tb-rooted-city__section tb-rooted-city__section--khaki\"><div class=\"tb-rooted-city__shell\">\n<div class=\"tb-rooted-city__section-head\"><p class=\"tb-rooted-city__eyebrow\">Maple Valley stories</p><h2>What we are <em>building next.</em></h2><p>A city hub should feel useful before it feels finished. These are the first three editorial tracks for Maple Valley.</p></div>\n<div class=\"tb-rooted-city__story-grid\">\n<a class=\"tb-rooted-city__story tb-rooted-city__story--featured\" href=\"/living-in-maple-valley-wa-local-guide/\" style=\"color:inherit;text-decoration:none\"><p class=\"tb-rooted-city__eyebrow\">Featured city guide</p><h3>What it is really like to live in Maple Valley</h3><p>Neighborhood feel, daily routines and the details people want before they make a move.</p></a>\n<article class=\"tb-rooted-city__story\"><p class=\"tb-rooted-city__eyebrow\">Coming next</p><h3>A local weekend in Maple Valley</h3><p>Food, coffee, parks and a few good reasons to leave the house.</p></article>\n<article class=\"tb-rooted-city__story\"><p class=\"tb-rooted-city__eyebrow\">Coming next</p><h3>The people behind the places</h3><p>Small businesses and community stories worth knowing.</p></article>\n</div></div></section>\n<section class=\"tb-rooted-city__section tb-rooted-city__section--white\"><div class=\"tb-rooted-city__shell\">\n<div class=\"tb-rooted-city__section-head\"><p class=\"tb-rooted-city__eyebrow\">Explore Maple Valley</p><h2>Find the part of town <em>you will love.</em></h2></div>\n<div class=\"tb-rooted-city__category-grid\">\n<div class=\"tb-rooted-city__category\" data-number=\"01\"><h3>Eat &amp; drink</h3></div>\n<div class=\"tb-rooted-city__category\" data-number=\"02\"><h3>Parks &amp; outdoors</h3></div>\n<div class=\"tb-rooted-city__category\" data-number=\"03\"><h3>Local businesses</h3></div>\n<div class=\"tb-rooted-city__category\" data-number=\"04\"><h3>Events &amp; community</h3></div>\n</div></div></section>\n<section class=\"tb-rooted-city__section\"><div class=\"tb-rooted-city__shell\">\n<div class=\"tb-rooted-city__section-head\"><p class=\"tb-rooted-city__eyebrow\">Tanya\'s Maple Valley list</p><h2>The spots worth <em>saving.</em></h2><p>This section is ready for Tanya\'s real favorites. The placeholders keep the page useful without pretending the list is finished.</p></div>\n<div class=\"tb-rooted-city__favorites\">\n<article class=\"tb-rooted-city__favorite\"><h3>Favorite coffee</h3><p>The kind of place you recommend when someone asks for good coffee and a comfortable corner.</p><small>Tanya\'s pick coming soon</small></article>\n<article class=\"tb-rooted-city__favorite\"><h3>Go-to walk</h3><p>A reliable reset for fresh air, movement and a better look at the city.</p><small>Tanya\'s pick coming soon</small></article>\n<article class=\"tb-rooted-city__favorite\"><h3>Easy dinner</h3><p>A local spot that works when you want something good without making it a whole production.</p><small>Tanya\'s pick coming soon</small></article>\n<article class=\"tb-rooted-city__favorite\"><h3>Local gem</h3><p>The small business or community place that helps Maple Valley feel like Maple Valley.</p><small>Tanya\'s pick coming soon</small></article>\n</div></div></section>\n<section class=\"tb-rooted-city__section tb-rooted-city__section--white\"><div class=\"tb-rooted-city__shell\">\n<div class=\"tb-rooted-city__section-head\"><p class=\"tb-rooted-city__eyebrow\">Maple Valley guide collection</p><h2>Practical answers, <em>all in one place.</em></h2></div>\n<div class=\"tb-rooted-city__guide-grid\">\n<a class=\"tb-rooted-city__guide\" href=\"/living-in-maple-valley-wa-local-guide/\" style=\"color:inherit;text-decoration:none\"><p class=\"tb-rooted-city__eyebrow\">Moving guide</p><h3>Living in Maple Valley</h3><p>The practical guide to neighborhoods, routines and what to know before moving.</p><small>Read the guide</small></a>\n<article class=\"tb-rooted-city__guide\"><p class=\"tb-rooted-city__eyebrow\">Local guide</p><h3>A weekend in Maple Valley</h3><p>A flexible list for food, coffee, parks and community events.</p><small>In progress</small></article>\n<article class=\"tb-rooted-city__guide\"><p class=\"tb-rooted-city__eyebrow\">Neighborhoods</p><h3>Where to look in Maple Valley</h3><p>A plain-language comparison built around how you actually want to live.</p><small>In progress</small></article>\n</div></div></section>\n<section class=\"tb-rooted-city__duo\">\n<div class=\"tb-rooted-city__duo-left\"><p class=\"tb-rooted-city__eyebrow\">Love the place?</p><h2>Explore what it is like to live nearby.</h2><p>Compare Maple Valley with the other communities Tanya knows and serves.</p><a class=\"tb-rooted-city__button tb-rooted-city__button--outline\" href=\"/neighborhoods/\">Explore all neighborhoods</a></div>\n<div class=\"tb-rooted-city__duo-right\"><p class=\"tb-rooted-city__eyebrow\">Share your Maple Valley</p><h2>Know a story we should tell?</h2><p>Favorite shop, hidden gem or everyday hero. Help shape this guide with the places and people that make Maple Valley feel like home.</p><a class=\"tb-rooted-city__button\" href=\"/contact/\">Suggest a Maple Valley story</a></div>\n</section>\n<section class=\"tb-rooted-city__move\"><div class=\"tb-rooted-city__shell\"><h2>Thinking about making Maple Valley home?</h2><p>Whether you are moving in, moving within the city or just curious about the market, Tanya can help you sort through the options without the sales pressure.</p><a class=\"tb-rooted-city__button\" href=\"/contact/\">Ask Tanya a question</a></div></section>\n</main>\n<!-- /wp:html -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"tagName\":\"footer\",\"theme\":\"tanya-barrans\"} /-->', 'Rooted in Maple Valley Page', '', 'inherit', 'closed', 'closed', '', '90459-revision-v1', '', '', '2026-08-27 03:59:21', '2026-08-27 03:59:21', '', 90459, 'https://violet-wren-104886.hostingersite.com/?p=90461', 0, 'revision', '', 0),
