ov .closing p{margin-left:auto;margin-right:auto}.cov .cards{grid-template-columns:1fr 1fr}.cov .hero .logo{left:75%;width:460px;height:460px}.cov .events{grid-template-columns:1fr}.cov .coffee-grid{grid-template-columns:1fr 1fr}.cov .story-shell{padding:30px}.cov .story-photo{position:relative;inset:auto;height:520px}.cov .story-copy{width:90%;margin:-90px auto 0}.cov .story-credit{position:static;margin-top:10px}.cov .blog-row{grid-template-columns:1fr}.cov .outdoor-links{grid-template-columns:1fr}}@media(max-width:560px){.cov section{padding:72px 0}.cov .cards{grid-template-columns:1fr}.cov .hero .logo{display:none}.cov .hero{min-height:650px}.cov .intro-photo,.cov .feature-photo{height:420px}.cov .lake ul{columns:1}.cov .coffee-grid,.cov .outdoor-grid{display:block}.cov .coffee-photo,.cov .outdoor-photo{height:300px;margin-bottom:16px}.cov .story-copy{width:100%;padding:30px;margin-top:-45px}.cov .mood-card{grid-template-columns:1fr}.cov .outdoor-link{padding:24px}}\n\n.cov .listings{background:var(--navy);padding:105px 0}\n.cov .listings .eyebrow{color:var(--mustard)}\n.cov .listings h2{color:#fff!important}\n.cov .listings-sub{color:#c9d2e0;max-width:640px;margin-bottom:10px}\n.cov .tb-sales-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:28px;margin-top:48px}\n.cov .tb-card{background:#fff;box-shadow:0 20px 50px rgba(0,0,0,.25)}\n.cov .tb-card p{padding:0 24px;margin:0}\n.cov .tb-card p:first-of-type{font-size:1.15rem;margin-top:18px!important;font-weight:700;color:var(--navy);font-family:Georgia,serif}\n.cov .tb-card p:last-of-type{margin-bottom:22px!important;color:var(--muted);font-size:.92rem}\n.cov .tb-sales-tag,.cov .tb-sales-tag--active{background:var(--mustard);color:var(--navy)}\n.cov .tb-sales-tag--pending{background:var(--navy);color:#fff;border:1px solid rgba(255,255,255,.4)}\n.cov .listings-mls-note{color:#8b98ad;font-size:.72rem;margin-top:18px}\n.cov .listings-cta{margin-top:40px}\n.cov .keep-exploring{background: