(90539, 2, '2026-08-28 00:36:34', '2026-08-28 00:36:34', '<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"tanya-barrans\",\"tagName\":\"header\"} /-->\n\n<style>\n.cov{--navy:#001830;--mustard:#E49C00;--ink:#202a35;--muted:#637080;--paper:#FCFCF0;--wash:#FCFCF0;background:var(--paper);color:var(--ink);font-family:Arial,sans-serif;overflow:hidden}.cov *{box-sizing:border-box}.cov a{color:var(--navy);text-decoration-thickness:1px;text-underline-offset:4px}.cov img{display:block;width:100%;height:100%;object-fit:cover}.cov .wrap{width:min(1160px,calc(100% - 44px));margin:auto}.cov .eyebrow{color:var(--mustard);font-size:.72rem;font-weight:800;letter-spacing:.18em;text-transform:uppercase;display:inline-flex;align-items:center;gap:8px}\n.cov .eyebrow::before{content:\"\";width:22px;height:2px;background:currentColor;display:inline-block}\n.cov a:not(.btn){transition:transform .25s ease}\n.cov a:not(.btn):hover{transform:translateX(3px)}\n.cov .tb-card a:hover{transform:none}\n.cov .mood-card,.cov .blog-card,.cov .lake-map,.cov .event{transition:transform .35s ease,box-shadow .35s ease}\n.cov .mood-card:hover,.cov .blog-card:hover,.cov .lake-map:hover,.cov .event:hover{transform:translateY(-4px);box-shadow:0 20px 45px rgba(0,24,48,.14)}.cov h1,.cov h2,.cov h3{font-family:Georgia,serif;color:var(--navy)!important;font-weight:400;letter-spacing:-.025em}.cov h2{font-size:clamp(2.5rem,5vw,4.6rem);line-height:1;margin:.15em 0 .45em}.cov p{line-height:1.75}.cov .hero{min-height:720px;position:relative;background:url(\'https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/city_of_covingtonwa_cover-scaled.jpeg\') center/cover}.cov .hero:after{content:\"\";position:absolute;inset:0;background:linear-gradient(90deg,rgba(7,20,39,.72),rgba(7,20,39,.05) 70%)}.cov .hero-copy{position:absolute;z-index:2;left:max(5vw,calc((100vw - 1160px)/2));bottom:72px;width:min(720px,calc(100% - 44px));color:white}.cov .hero h1{color:white!important;font-size:clamp(3.8rem,8vw