.92rem}\n.cov .tb-sales-tag,.cov .tb-sales-tag--active{background:var(--mustard);color:var(--navy)}\n.cov .tb-sales-tag--pending{background:var(--navy);color:#fff;border:1px solid rgba(255,255,255,.4)}\n.cov .listings-mls-note{color:#8b98ad;font-size:.72rem;margin-top:18px}\n.cov .listings-cta{margin-top:40px}\n.cov .keep-exploring{background:var(--wash);padding:60px 0}\n.cov .band-shopping{background:var(--wash)}\n.cov .band-reading{background:#F5EEDA}\n.cov .wrap-boxed{background:#fff;padding:56px;box-shadow:0 20px 50px rgba(0,24,48,.1);border-top:7px solid var(--mustard)}\n\n.cov .keep-exploring h2{color:var(--navy)!important;font-size:clamp(1.6rem,3vw,2.2rem);text-align:center;margin-bottom:32px}\n.cov .explore-links{display:flex;flex-wrap:wrap;justify-content:center;gap:36px}\n.cov .explore-links a{color:var(--navy);font-size:.95rem;font-weight:600;text-decoration:none;border-bottom:1px solid rgba(0,24,48,.35);padding-bottom:2px}\n.cov .explore-links a:hover{border-color:var(--mustard);color:var(--mustard)}\n.cov .story-video{position:relative;aspect-ratio:16/9;overflow:hidden;background:#000;box-shadow:0 24px 55px rgba(0,24,48,.14)}.cov .story-video video{width:100%;height:100%;object-fit:cover;display:block}.cov .story-copy-card{background:#fff;padding:44px 56px;border-top:7px solid var(--mustard);box-shadow:0 24px 55px rgba(0,24,48,.14);margin-top:32px}.cov .story-copy-cols{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:repeat(2,auto);grid-auto-flow:column;column-gap:48px;row-gap:1em;align-items:start}.cov .story-copy-cols p{margin:0}.cov .story-copy-card .lede{margin:16px 0 0}@media(max-width:900px){.cov .story-copy-cols{grid-template-columns:1fr}.cov .story-copy-card{padding:32px}}\n.cov .reading-grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:42px;align-items:start}\n.cov .reading-rail{background:#fff;box-shadow:0 20px 45px rgba(0,24,48,.12)}\n.cov .reading-rail .tb-blog-rail__intro>img{width:96px;height:96px;border-radius:50%;object-fit:cover}\n.cov .reading-rail .tb-blog-rail__intro{padding:36px 32px;text-align:center}\n.cov .reading-rail .tb-blog-rail__eyebrow{color:var(--mustard);font-size:.72rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase;margin:0 0 .5em}\n.cov .reading-rail h2{font-size:1.6rem;color:var(--navy);margin:.1em 0 .5em;line-height:1.15}\n.cov .reading-rail p{color:var(--muted);font-size:.95rem;line-height:1.5;margin:0 0 .5em}\n.cov .reading-rail .tb-blog-rail__button{display:inline-block;margin-top:14px;background:var(--mustard);color:var(--navy)!important;font-weight:800;text-transform:uppercase;font-size:.78rem;letter-spacing:.06em;padding:13px 22px;text-decoration:none!important}\n.cov .reading-rail .tb-blog-rail__button:hover{background:var(--navy);color:#fff!important}\n\n@media(max-width:900px){.cov .reading-grid{grid-template-columns:1fr}.cov .reading-rail{max-width:420px;margin:0 auto}}\n.cov strong.hl-sweep{background-image:linear-gradient(var(--mustard),var(--mustard));background-repeat:no-repeat;background-size:0% 88%;background-position:0 100%;padding:.02em .12em;-webkit-box-decoration-break:clone;box-decoration-break:clone;transition:background-size 1.1s cubic-bezier(.16,1,.3,1) .15s;opacity:1!important;transform:none!important;color:var(--navy)}\n.cov strong.hl-sweep.is-visible{background-size:100% 88%}\n.cov .cov-nl-overlay{position:fixed;inset:0;background:rgba(0,24,48,.72);display:flex;align-items:center;justify-content:center;padding:24px;z-index:9999;opacity:0;visibility:hidden;transition:opacity .35s ease}\n.cov .cov-nl-overlay.is-open{opacity:1;visibility:visible}\n.cov .cov-nl-modal{position:relative;background:var(--paper);max-width:440px;width:100%;padding:44px 36px 36px;border-top:7px solid var(--mustard);box-shadow:0 30px 70px rgba(0,24,48,.4);text-align:center;transform:translateY(16px);transition:transform .35s ease}\n.cov .cov-nl-overlay.is-open .cov-nl-modal{transform:translateY(0)}\n.cov .cov-nl-modal h2{margin:.2em 0 .4em;color:var(--navy)}\n.cov .cov-nl-modal .tb-script-accent{color:var(--mustard);font-weight:800;letter-spacing:.08em;text-transform:uppercase;font-size:.78rem}\n.cov .cov-nl-modal>p{color:var(--muted)}\n.cov .cov-nl-close{position:absolute;top:14px;right:16px;background:none;border:none;font-size:1.6rem;line-height:1;color:var(--muted);cursor:pointer;padding:4px 8px}\n.cov .cov-nl-close:hover{color:var(--navy)}\n.cov .cov-nl-privacy{font-size:.8rem;color:var(--muted);margin-top:14px}\n.cov .tb-newsletter-fields{display:flex;flex-direction:column;gap:12px;margin-top:22px}\n.cov .cov-nl-modal .tb-newsletter-input{flex:0 0 auto;width:100%}\n.cov .cov-nl-modal .tb-newsletter-input:focus{border-color:var(--mustard);box-shadow:0 0 0 1px var(--mustard)}\n.cov .cov-nl-modal .tb-newsletter-submit{background:var(--mustard);color:var(--navy)}\n.cov .cov-nl-modal .tb-newsletter-submit:hover{background:var(--navy);color:#fff}\n.cov .cov-nl-modal .tb-newsletter-status[data-state=\"success\"]{color:var(--navy);font-weight:700}\n.cov .cov-nl-modal .tb-newsletter-status[data-state=\"error\"]{color:#b3261e}\n</style>\n<main class=\"cov\">\n<header class=\"hero\"><div class=\"hero-copy\"><div class=\"eyebrow\">Rooted In &middot; South King County</div><h1>Living in Kent, Washington</h1><p>Established neighborhoods, valley living and a downtown that keeps reinventing itself&mdash;with Renton, Auburn and Covington close enough to borrow whenever the mood strikes.</p><div class=\"hero-buttons\"><a class=\"btn btn-solid\" href=\"https://tanyab.johnlscott.com/search/place/ChIJDWzOLRJYkFQRWgAVv23IR10\">Explore Kent Homes</a><a class=\"btn btn-outline\" href=\"https://violet-wren-104886.hostingersite.com/living-in-kent-wa-local-guide/\">What\'s It Really Like Here? &rarr;</a></div></div><img class=\"logo\" src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/Rooted-In-Logos-1.png\" alt=\"Rooted in Kent logo\"></header><section id=\"story\"><div class=\"wrap\">\n<div class=\"story-video\"><video autoplay muted loop controls playsinline poster=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/kent-green-river-scaled.jpg\"><source src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/Kent.mp4\" type=\"video/mp4\"></video></div>\n<article class=\"story-copy-card\"><div class=\"eyebrow\">A Kent story</div><h2>Kent didn\'t have nice things. And then, slowly, it did.</h2><div class=\"story-copy-cols\">\n<p>I spent a good chunk of my 20s in Kent&mdash;including a couple of years when I was part of a motorcycle club. Yeah, yeah, I know. It was a ridiculously fun chapter of my life, and if we\'re being fair, probably at least partially responsible for why I\'m sober today.</p>\n<p>Back then, Kent was a little different. This was the Kent of dive bars, commercial warehouses and nights out with friends&mdash;line dancing at the country bar that used to be here, bar hopping around town. Kent didn\'t have nice things. And then, slowly, it did.</p>\n<p>When Kent Station first opened, everyone was basically like, &ldquo;Wait&hellip; <strong>Kent</strong> gets this?&rdquo; The restaurants came. The movie theater came. The area around ShoWare became somewhere you actually planned to spend an evening instead of just passing through.</p>\n<p>My Kent nights changed too. Bar hopping eventually turned into T-Birds games with my brother and friends. These days, if I\'m heading to Kent, there\'s a good chance I\'m going to the movies (reclining seats are apparently a non-negotiable now), grabbing dinner nearby, or wandering around my actual happy place: Carpinito Brothers. Give me a coffee and nowhere else to be and I could spend half the day there.</p>\n</div><p class=\"lede\">Kent still has some of the old-school left&mdash;the industrial, gritty parts that have always been here. But now it\'s mixed with great restaurants, entertainment, hockey games, trails, parks, international food and neighborhoods that feel completely different depending on which direction you drive. Kent grew up a lot since my 20s. Thankfully, so did I.</p></article>\n</div></section><section class=\"history\"><div class=\"wrap split\"><div class=\"history-photo\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/kent-area-ca-1920-copy.jpg\" alt=\"Historic Kent-area hop farming and rail era\"></div><div><div class=\"eyebrow\">The roots</div><h2>Hops, rail lines and a city named for an English county.</h2><p>Long before there was a city called Kent, this fertile valley was part of the traditional homelands of Coast Salish peoples, including the Muckleshoot and Puyallup Tribes. White settlers arrived in the 1850s, and the rich river soil soon made hops the crop that put the valley on the map.</p><p>When the settlement of Titusville incorporated in 1890, it took the name Kent after the English county known for growing hops. The crops changed, but the spirit of the valley didn\'t&mdash;Japanese American farmers, dairy families, makers, aerospace workers and new neighbors from around the world all added layers to the city.</p><p class=\"lede\">Kent\'s roots are agricultural, international and resilient&mdash;qualities you can still feel in the neighborhoods, food and people here today.</p><a href=\"https://www.kentwa.gov/guides/kent-history\">Read Kent\'s history &rarr;</a></div></div></section><section class=\"ticker\"><div class=\"ticker-track\"><div class=\"ticker-item\"><b>135,603</b><span>Population</span></div><div class=\"ticker-item\"><b>47,200</b><span>Households</span></div><div class=\"ticker-item\"><b>$92,302</b><span>Median household income</span></div><div class=\"ticker-item\"><b>57.2%</b><span>Homeownership rate</span></div><div class=\"ticker-item\"><b>$587,800</b><span>Median home value</span></div><div class=\"ticker-item\"><b>2.9</b><span>Average household size</span></div><div class=\"ticker-item\"><b>~25%</b><span>Under age 18</span></div><div class=\"ticker-item\"><b>33.6</b><span>Square miles</span></div><div class=\"ticker-item\"><b>4,007</b><span>People per sq. mile</span></div><div class=\"ticker-item\"><b>30.4 min.</b><span>Average commute</span></div><div class=\"ticker-item\"><b>-0.6%</b><span>Change since 2020</span></div><div class=\"ticker-item\"><b>135,603</b><span>Population</span></div><div class=\"ticker-item\"><b>47,200</b><span>Households</span></div><div class=\"ticker-item\"><b>$92,302</b><span>Median household income</span></div><div class=\"ticker-item\"><b>57.2%</b><span>Homeownership rate</span></div><div class=\"ticker-item\"><b>$587,800</b><span>Median home value</span></div><div class=\"ticker-item\"><b>2.9</b><span>Average household size</span></div><div class=\"ticker-item\"><b>~25%</b><span>Under age 18</span></div><div class=\"ticker-item\"><b>33.6</b><span>Square miles</span></div><div class=\"ticker-item\"><b>4,007</b><span>People per sq. mile</span></div><div class=\"ticker-item\"><b>30.4 min.</b><span>Average commute</span></div><div class=\"ticker-item\"><b>-0.6%</b><span>Change since 2020</span></div></div></section><section class=\"band band-food\"><div class=\"wrap\"><div class=\"eyebrow\">Local food favorites</div><h2>Worth putting in the rotation.</h2><div class=\"food-features\"><article class=\"food-lead\" style=\"background:linear-gradient(165deg,rgba(0,24,48,.55),rgba(0,24,48,.97)),var(--navy)\"><div class=\"eyebrow\">No ambiance required</div><h3>Sushi Kaunta</h3><p>You walk in, you get your sushi, you leave&mdash;and somehow it\'s some of the best in Kent. Don\'t expect ambiance. Expect really good sushi.</p><a class=\"btn\" href=\"https://sushikaunta.com/\">Visit Sushi Kaunta</a></article><div class=\"food-stack\"><article class=\"food-item tb-reveal\"><h3>Asadero Prime</h3><p>Steak, done right. Hands-down the pick for Mexican prime and wagyu.</p><a href=\"https://www.asaderoprime.com/location/asadero-prime-kent/\">Visit Asadero Prime &rarr;</a></article><article class=\"food-item tb-reveal\"><h3>Paolo\'s Italian</h3><p>A secret (or not-so-secret) Italian gem that\'s been a Kent favorite for years.</p><a href=\"https://www.paolositalian.com/\">Visit Paolo\'s Italian &rarr;</a></article></div></div><div class=\"also-row\"><strong>Also worth a stop:</strong><a href=\"https://www.carpinito.com/\">Carpinito Brothers</a><span class=\"burger-line\">Tanya\'s actual happy place&mdash;give her a coffee and nowhere else to be and she could spend half the day there.</span></div></div></section><section class=\"outdoors\"><div class=\"wrap\"><div class=\"eyebrow\">Kent outdoors</div><h2>Trails, water and green space.</h2><div class=\"outdoor-grid\" style=\"grid-template-columns:1fr 1fr;grid-template-rows:380px\"><figure class=\"outdoor-photo tb-reveal\" style=\"grid-row:auto\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/kent-green-river-scaled.jpg\" alt=\"Green River Trail in Kent\"><figcaption class=\"caption\"><h3>Green River Trail</h3><p>Miles of paved trail for walking, running and biking right along the water.</p></figcaption></figure><figure class=\"outdoor-photo tb-reveal\" style=\"grid-row:auto\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/Lake-Meridian-Neighborhood-Kent-WA-Courtesy-NWMLS.webp\" alt=\"Lake Meridian in Kent, WA\"><figcaption class=\"caption\"><h3>Lake Meridian</h3><p>Swimming, boating and a different kind of outdoor day on the east side of the city.</p></figcaption></figure></div><div class=\"outdoor-links\"><div class=\"outdoor-link\"><h3>Green River Natural Resources Area</h3><p>Wildlife viewing, accessible gravel trails and viewing towers.</p></div><div class=\"outdoor-link\"><h3>East Hill &amp; West Hill</h3><p>Hillside neighborhoods with their own parks, shopping and everyday rhythm.</p></div></div></div></section><section class=\"band band-events\"><div class=\"wrap\"><div class=\"eyebrow\">Things to do &amp; annual events</div><h2>Somebody is usually planning something.</h2><p class=\"lede\">Between the arena, the trails and downtown, Kent isn\'t short on ways to spend an evening.</p><div class=\"events\"><article class=\"event tb-reveal\"><h3><a href=\"https://kcdays.com/\">Kent Cornucopia Days</a></h3><p>Kent\'s longtime annual downtown festival, with a parade, carnival, vendors, entertainment and a community 5K.</p></article><article class=\"event tb-reveal\"><h3><a href=\"https://www.accessoshowarecenter.com/events/seattle-thunderbirds\">Seattle Thunderbirds hockey</a></h3><p>WHL hockey at the accesso ShoWare Center&mdash;a Kent tradition for game nights with family and friends.</p></article><article class=\"event tb-reveal\"><h3>Kent Station movies &amp; dining</h3><p>Reclining-seat movie theater, restaurants and shops that turned downtown into somewhere you actually plan to spend an evening.</p></article></div></div></section><section class=\"lake\"><div class=\"wrap lake-grid\"><div><div class=\"eyebrow\">What\'s coming to Kent</div><h2>ReDiscover Downtown Kent</h2><p class=\"quote\">If you\'ve driven through downtown Kent and wondered what\'s next for some of those older commercial blocks along Central Avenue&mdash;there\'s an actual plan now.</p><p><a href=\"https://engage.kentwa.gov/downtown\"><strong>ReDiscover Downtown Kent</strong></a> is the city\'s 2026 update to its downtown development strategy, aimed at turning the area into a safe, vibrant, mixed-use hub. It includes:</p><ul><li>Targeted infrastructure investment</li><li>Support for mixed-income housing</li><li>Business recruitment and retention</li><li>Better pedestrian connectivity and transit access</li><li>Preserving downtown\'s historic character alongside new development</li></ul><p>The first concrete step landed in August 2026, when the City Council rezoned roughly 75 properties along Central Avenue and East Smith Street to support higher-density, mixed-use redevelopment.</p></div><aside class=\"lake-map tb-reveal\"><div class=\"eyebrow\">Official planning materials</div><strong>Central Avenue Corridor Rezone &amp; downtown plan</strong><p>See the City of Kent\'s official ReDiscover Downtown materials for the full plan, goals and zoning details.</p><a class=\"btn\" href=\"https://engage.kentwa.gov/downtown\">View the ReDiscover Downtown plan</a><p class=\"small\">Planning and zoning documents only. Actual redevelopment depends on individual property owners and will happen gradually over time.</p><div class=\"stats\"><div class=\"stat tb-reveal\"><b>~75</b>properties rezoned along Central Ave &amp; E. Smith St.</div><div class=\"stat tb-reveal\"><b>Aug. 2026</b>Central Avenue Corridor Rezone adopted</div></div></aside></div><div class=\"wrap\"><p class=\"lede\">But if ReDiscover Downtown follows through, it could reshape how downtown Kent feels and functions within just a few years:</p></div></section><section class=\"band band-shopping\"><div class=\"wrap split\"><div><div class=\"eyebrow\">Shopping, fitness &amp; medical care</div><h2>Life is close to home.</h2><p>Kent covers a lot of ground, but everyday errands still don\'t take much planning. Groceries, home projects, fitness, pharmacy runs and medical care are all within easy reach.</p><div class=\"convenience-list\"><span>Target</span><span>Fred Meyer</span><span>Walmart</span><span>Home Depot</span><span>IKEA</span><span>Safeway</span></div><p class=\"quote\">Kent Station gets most of the attention, but it\'s the everyday collection of big-box stores and services that makes life here genuinely convenient.</p><div class=\"medical-callout\"><strong>Kent is covered by multiple care options, not just a clinic or two.</strong>MultiCare Kent Clinic and Valley Medical Center\'s Kent Primary Care both have a presence in the city, with full hospital campuses a short drive away in Renton and Auburn. <a href=\"https://www.multicare.org/location/multicare-kent-clinic/\">Explore MultiCare Kent &rarr;</a></div></div><div class=\"intro-photo\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/Kentstation.jpg\" alt=\"Kent Station shopping and dining in Kent, Washington\"></div></div></section><section class=\"rule rule-budget\"><div class=\"wrap wrap-boxed\"><div class=\"eyebrow\">Living in Kent</div><h2>What your housing dollar can do here.</h2><p>Kent covers a lot of ground&mdash;from established East Hill and West Hill neighborhoods to newer construction in the valley, plus condos and townhomes near downtown and Kent Station.</p><p class=\"lede\">And that variety is kind of the whole point: <strong class=\"hl-sweep tb-reveal\">the right fit in Kent depends less on a citywide reputation and more on which neighborhood you\'re actually comparing.</strong></p><p>Kent\'s citywide median home value runs a bit below several of its King County neighbors, but the real differences show up block by block&mdash;East Hill living is a different budget conversation than a place near Lake Meridian or a new build out in the valley.</p><p>Add in direct access to SR 167, I-5 and regional transit, plus shopping, dining and parks spread across several distinct areas, and the real question becomes:</p><p class=\"lede\"><strong class=\"hl-sweep tb-reveal\">Does Kent\'s mix of neighborhoods actually match how you want to live&mdash;and what you want to spend?</strong></p><p>That\'s where knowing the neighborhoods, commute patterns and Kent\'s own micro-markets really matters.</p></div></section><section class=\"band band-reading\"><div class=\"wrap\"><div class=\"reading-grid\"><div class=\"reading-main\"><div class=\"eyebrow\">Thinking about making Kent home?</div><h2>Keep reading before you start scrolling listings.</h2><div class=\"blog-row\">\n<article class=\"blog-card tb-reveal\"><h3>Living in Kent, WA: A Practical Local Guide</h3><p>The practical rundown on neighborhoods, commuting and what makes each part of Kent feel different.</p><a href=\"https://violet-wren-104886.hostingersite.com/living-in-kent-wa-local-guide/\">Read the local guide &rarr;</a></article>\n<article class=\"blog-card tb-reveal\"><h3>Renton Highlands Guide: Where Community and Character Meet</h3><p>The location is different; the neighborhood-comparison approach still travels well.</p><a href=\"https://violet-wren-104886.hostingersite.com/renton-highlands-neighborhood-guide/\">Read the article &rarr;</a></article>\n<article class=\"blog-card tb-reveal\"><h3>Most Common Home Inspection Issues in Renton-Area Homes</h3><p>Practical, area-agnostic advice worth knowing before you make an offer anywhere in South King County.</p><a href=\"https://violet-wren-104886.hostingersite.com/home-inspection-issues-renton-wa/\">Read the article &rarr;</a></article>\n</div></div><aside class=\"tb-blog-rail reading-rail tb-reveal\"><section class=\"tb-blog-rail__intro\"><img src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/07/contact-circle.jpg\" alt=\"Tanya Barrans, Kent real estate broker\" loading=\"lazy\"><p class=\"tb-blog-rail__eyebrow\" style=\"color:#E49C00!important\">Local guidance, rooted here</p><h2>Have Kent questions?</h2><p>I can help you sort through neighborhoods, commute routes and budget&mdash;without the pressure.</p><a class=\"tb-blog-rail__button\" href=\"/contact/\">Ask Tanya a question</a></section></aside></div></div></section><section class=\"listings\"><div class=\"wrap\">\n<div class=\"eyebrow\">Current Kent Listings</div>\n<h2>See what\'s on the market right now.</h2>\n<p class=\"listings-sub\">A snapshot of homes currently for sale in Kent. Want the full details on any of these, or something that isn\'t listed yet? Let\'s talk.</p>\n<div class=\"tb-sales-grid\">\n<div class=\"wp-block-group tb-card tb-reveal\"><a href=\"/contact/\" style=\"text-decoration:none;color:inherit;display:block\"><div class=\"tb-sales-photo\"><span class=\"tb-sales-tag tb-sales-tag--active\">For Sale</span><img src=\"https://assets.jlscontent.com/thumbs/wanwmls/256/204/2562040-t.jpg\" alt=\"For sale home at 13215 SE 262nd Street, Kent, WA\"></div><p><strong>13215 SE 262nd Street, Kent, WA</strong></p><p>$1,099,000 &middot; 4 Bed &middot; 2.5 Bath &middot; 3,174 SqFt</p></a></div>\n<div class=\"wp-block-group tb-card tb-reveal\"><a href=\"/contact/\" style=\"text-decoration:none;color:inherit;display:block\"><div class=\"tb-sales-photo\"><span class=\"tb-sales-tag tb-sales-tag--active\">For Sale</span><img src=\"https://assets.jlscontent.com/thumbs/wanwmls/257/268/2572685-t.jpg\" alt=\"For sale home at 11912 SE 240th Place, Kent, WA\"></div><p><strong>11912 SE 240th Place, Kent, WA</strong></p><p>$925,000 &middot; 5 Bed &middot; 2.75 Bath &middot; 2,988 SqFt</p></a></div>\n<div class=\"wp-block-group tb-card tb-reveal\"><a href=\"/contact/\" style=\"text-decoration:none;color:inherit;display:block\"><div class=\"tb-sales-photo\"><span class=\"tb-sales-tag tb-sales-tag--active\">For Sale</span><img src=\"https://assets.jlscontent.com/thumbs/wanwmls/251/915/2519158-t.jpg\" alt=\"For sale home at 26421 106th Avenue SE, Kent, WA\"></div><p><strong>26421 106th Avenue SE, Kent, WA</strong></p><p>$749,000 &middot; 3 Bed &middot; 2.25 Bath &middot; 1,908 SqFt</p></a></div>\n</div></div></section><section class=\"closing\"><div class=\"wrap\"><img class=\"logo\" src=\"https://violet-wren-104886.hostingersite.com/wp-content/uploads/2026/08/Rooted-In-Logos-1.png\" alt=\"Rooted in Kent logo\"><div class=\"closing-copy\"><div class=\"eyebrow\">Local guidance, rooted here</div><h2>Thinking about making Kent home?</h2><p class=\"closing-lede\">Established neighborhoods, valley living and a downtown that keeps reinventing itself.</p><p>Whether you\'re moving in, moving across town or comparing South King County communities, Tanya can help you sort through the options without the pressure.</p><a class=\"btn\" href=\"/contact/\">Ask Tanya about Kent</a></div></div></section><section class=\"keep-exploring\"><div class=\"wrap\">\n<h2>Keep Exploring South King County</h2>\n<div class=\"explore-links\">\n<a href=\"https://violet-wren-104886.hostingersite.com/rooted-in-covington/\">Rooted in Covington &rarr;</a>\n<a href=\"https://violet-wren-104886.hostingersite.com/rooted-in-maple-valley/\">Rooted in Maple Valley &rarr;</a>\n<a href=\"https://violet-wren-104886.hostingersite.com/rooted-in-newcastle/\">Rooted in Newcastle &rarr;</a>\n<a href=\"https://violet-wren-104886.hostingersite.com/rooted-in-renton/\">Rooted in Renton &rarr;</a>\n</div>\n</div></section><div id=\"cov-newsletter-modal\" class=\"cov-nl-overlay\" aria-hidden=\"true\">\n<div class=\"cov-nl-modal\">\n<button type=\"button\" class=\"cov-nl-close\" aria-label=\"Close\">&times;</button>\n<p class=\"tb-script-accent\">Let\'s stay in touch</p>\n<h2>Notes worth opening.</h2>\n<p>Useful Kent home ideas and honest local guidance—delivered with no pressure and no polished filler.</p>\n<form class=\"tb-newsletter-form\" novalidate>\n<div class=\"tb-newsletter-fields\">\n<label class=\"tb-sr-only\" for=\"cov-nl-name\">First name</label>\n<input type=\"text\" id=\"cov-nl-name\" name=\"name\" class=\"tb-newsletter-input\" placeholder=\"First name\" autocomplete=\"given-name\">\n<label class=\"tb-sr-only\" for=\"cov-nl-email\">Email address</label>\n<input type=\"email\" id=\"cov-nl-email\" name=\"email\" class=\"tb-newsletter-input\" placeholder=\"Email address\" autocomplete=\"email\" required>\n<div class=\"tb-newsletter-hp\" aria-hidden=\"true\"><label for=\"cov-nl-website\">Website</label><input type=\"text\" id=\"cov-nl-website\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\"></div>\n<button type=\"submit\" class=\"tb-newsletter-submit\">Subscribe</button>\n</div>\n<p class=\"tb-newsletter-status\" role=\"status\" aria-live=\"polite\"></p>\n</form>\n<p class=\"cov-nl-privacy\">No spam. Unsubscribe whenever you like.</p>\n</div>\n</div>\n<script>\n(function(){\n  var modal = document.getElementById(\'cov-newsletter-modal\');\n  if(!modal) return;\n  var KEY = \'tbCovNlDismissedAt\';\n  function dismissedRecently(){\n    try{\n      var t = localStorage.getItem(KEY);\n      if(!t) return false;\n      return (Date.now() - parseInt(t,10)) < 1000*60*60*24*7;\n    }catch(e){ return false; }\n  }\n  function loadNewsletterScript(){\n    if (window.tanyaNewsletter) return;\n    fetch(\'/living-in-kent-wa-local-guide/\', {credentials:\'same-origin\'})\n      .then(function(r){ return r.text(); })\n      .then(function(html){\n        var m = html.match(/var tanyaNewsletter\\s*=\\s*(\\{[^}]*\\});/);\n        if(m){ try{ window.tanyaNewsletter = JSON.parse(m[1]); }catch(e){} }\n      })\n      .catch(function(){})\n      .then(function(){\n        var s = document.createElement(\'script\');\n        s.src = \'/wp-content/themes/tanya-barrans/assets/js/newsletter.js\';\n        document.body.appendChild(s);\n      });\n  }\n  function openModal(){\n    if(modal.classList.contains(\'is-open\')) return;\n    loadNewsletterScript();\n    modal.classList.add(\'is-open\');\n    modal.setAttribute(\'aria-hidden\',\'false\');\n  }\n  function closeModal(remember){\n    modal.classList.remove(\'is-open\');\n    modal.setAttribute(\'aria-hidden\',\'true\');\n    if(remember){ try{ localStorage.setItem(KEY, String(Date.now())); }catch(e){} }\n  }\n  modal.querySelector(\'.cov-nl-close\').addEventListener(\'click\', function(){ closeModal(true); });\n  modal.addEventListener(\'click\', function(e){ if(e.target===modal) closeModal(true); });\n  var form = modal.querySelector(\'.tb-newsletter-form\');\n  form.addEventListener(\'submit\', function(){ setTimeout(function(){ closeModal(true); }, 2500); });\n  if(!dismissedRecently()){\n    var shown = false;\n    function maybeShow(){ if(!shown){ shown = true; openModal(); } }\n    var timer = setTimeout(maybeShow, 20000);\n    window.addEventListener(\'scroll\', function(){\n      var doc = document.documentElement;\n      var pct = window.scrollY / (doc.scrollHeight - window.innerHeight);\n      if(pct > 0.45){ clearTimeout(timer); maybeShow(); }\n    }, {passive:true});\n  }\n})();\n</script>\n</main>\n\n<!-- wp:template-part {\"slug\":\"footer-rooted\",\"theme\":\"tanya-barrans\",\"tagName\":\"footer\"} /-->\n', 'Rooted in Kent Page', '', 'inherit', 'closed', 'closed', '', '90449-revision-v1', '', '', '2026-08-28 03:59:29', '2026-08-28 03:59:29', '', 90449, 'https://violet-wren-104886.hostingersite.com/?p=90551', 0, 'revision', '', 0);
