to{background:#F5EEDA}.cov .carpinito-grid{display:grid;grid-template-columns:.72fr 1.28fr;gap:6vw;align-items:center}.cov .carpinito-copy .lede{font-size:1.35rem}.cov .carpinito-gallery{display:grid;grid-template-columns:1fr 1fr;gap:18px}.cov .place-figure{margin:0;background:#fff;box-shadow:0 16px 38px rgba(0,24,48,.11)}.cov .place-figure img{height:420px}.cov .place-figure figcaption{padding:20px 22px;color:var(--navy)}.cov .place-figure figcaption strong{display:block;font:400 1.45rem Georgia,serif;margin-bottom:6px}.cov .place-figure figcaption span{display:block;color:var(--muted);font-size:.92rem;line-height:1.5}.cov .caption-link{display:inline-block;margin-top:10px;color:inherit!important;font-weight:800}.cov .outdoor-photo .caption .caption-link{color:#fff!important}.cov .station-figure{margin:0;background:#fff;box-shadow:0 16px 38px rgba(0,24,48,.11)}.cov .station-figure img{height:520px}.cov .station-figure figcaption{padding:22px 24px}.cov .station-figure figcaption strong{display:block;font:400 1.7rem Georgia,serif;color:var(--navy);margin-bottom:6px}.cov .station-figure figcaption span{display:block;color:var(--muted);line-height:1.55}.cov .station-figure figcaption a{display:inline-block;margin-top:10px;font-weight:800}@media(max-width:850px){.cov .carpinito-grid{grid-template-columns:1fr}}@media(max-width:560px){.cov .carpinito-gallery{grid-template-columns:1fr}.cov .place-figure img,.cov .station-figure img{height:320px}}.cov .mood-list{display:grid;gap:20px}.cov .mood-card{display:grid;grid-template-columns:210px 1fr;align-items:center;border:1px solid #d6dbe0}.cov .mood-label{height:100%;display:grid;place-items:center;padding:28px 22px;background:var(--navy);color:var(--mustard);font-size:1.08rem;line-height:1.25;font-weight:900;letter-spacing:.1em;text-align:center;text-transform:uppercase}.cov .mood-copy{padding:26px 34px}.cov .mood-copy h3{font-size:1.8rem;margin:.1em 0}.cov .outdoors{background:var(--navy);color:#fff}.cov .outdoors h2,.cov .